import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  Box, VStack, HStack, Text, Button, Progress, Badge, Icon,
  Card, CardHeader, CardBody, Heading, useToast, Alert, AlertIcon,
  AlertDescription, Divider, List, ListItem, ListIcon, Spinner,
  Modal, ModalOverlay, ModalContent, ModalHeader, ModalBody, ModalFooter,
  ModalCloseButton, useDisclosure, Input, Textarea, FormControl, FormLabel
} from '@chakra-ui/react';
import {
  CloudUploadOutlined, SyncOutlined, CheckCircleOutlined,
  CloseCircleOutlined, FileOutlined, HistoryOutlined,
  InfoCircleOutlined, WarningOutlined, RocketOutlined,
  ClockCircleOutlined, DownloadOutlined
} from '@ant-design/icons';
import { getApiUrl } from '../utils/apiUrlHelper';

const NewUpdateSettings = () => {
  const toast = useToast();
  const fileInputRef = useRef(null);
  const progressIntervalRef = useRef(null);
  const { isOpen: isChangelogOpen, onOpen: onChangelogOpen, onClose: onChangelogClose } = useDisclosure();

  // الحالات
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [updating, setUpdating] = useState(false);
  const [updateInfo, setUpdateInfo] = useState({
    hasUpdate: false,
    currentVersion: '1.0.0',
    newVersion: null,
    fileSize: null,
    changelog: [],
    lastCheck: null
  });
  const [progress, setProgress] = useState({
    status: 'idle',
    progress: 0,
    currentFile: '',
    totalFiles: 0,
    processedFiles: 0,
    updatedFiles: [],
    skippedFiles: [],
    errors: []
  });
  const [newChangelog, setNewChangelog] = useState('');

  // ألوان الثيم
  const cardBg = 'var(--stake-bg-card, #1b2b38)';
  const headerBg = 'var(--stake-bg-secondary, #0f212e)';
  const cardBorder = 'var(--stake-border-primary, #2f4553)';
  const headerText = 'var(--stake-text-primary, white)';
  const subText = 'var(--stake-text-secondary, #a0aec0)';

  // التحقق من وجود تحديثات
  const checkForUpdates = useCallback(async () => {
    try {
      setLoading(true);
      const response = await fetch(getApiUrl('/api/update_system.php?action=check'));
      const data = await response.json();
      
      if (data.success) {
        setUpdateInfo(data);
      } else {
        throw new Error(data.message);
      }
    } catch (error) {
      console.error('Error checking updates:', error);
      toast({
        title: 'خطأ في التحقق من التحديثات',
        description: error.message,
        status: 'error',
        duration: 5000
      });
    } finally {
      setLoading(false);
    }
  }, [toast]);

  // رفع ملف التحديث
  const handleFileUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    if (!file.name.endsWith('.zip')) {
      toast({
        title: 'خطأ',
        description: 'يجب أن يكون الملف بصيغة ZIP',
        status: 'error',
        duration: 3000
      });
      return;
    }

    setUploading(true);
    const formData = new FormData();
    formData.append('updateFile', file);
    formData.append('action', 'upload');

    try {
      const response = await fetch(getApiUrl('/api/update_system.php'), {
        method: 'POST',
        body: formData
      });
      const data = await response.json();

      if (data.success) {
        toast({
          title: 'تم رفع الملف بنجاح',
          description: `حجم الملف: ${data.fileSize}`,
          status: 'success',
          duration: 3000
        });
        checkForUpdates();
      } else {
        throw new Error(data.message);
      }
    } catch (error) {
      toast({
        title: 'فشل في رفع الملف',
        description: error.message,
        status: 'error',
        duration: 5000
      });
    } finally {
      setUploading(false);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  // بدء التحديث
  const startUpdate = async () => {
    if (!updateInfo.hasUpdate) return;

    setUpdating(true);
    setProgress({
      status: 'starting',
      progress: 0,
      currentFile: '',
      totalFiles: 0,
      processedFiles: 0,
      updatedFiles: [],
      skippedFiles: [],
      errors: []
    });

    // بدء متابعة التقدم
    progressIntervalRef.current = setInterval(async () => {
      try {
        const response = await fetch(getApiUrl('/api/update_system.php?action=progress'));
        const data = await response.json();
        
        if (data.success && data.progress) {
          setProgress(data.progress);
          
          if (data.progress.status === 'completed' || data.progress.status === 'error') {
            clearInterval(progressIntervalRef.current);
            setUpdating(false);
            
            if (data.progress.status === 'completed') {
              toast({
                title: 'تم التحديث بنجاح! 🎉',
                description: `تم تحديث ${data.progress.updatedFiles.length} ملف`,
                status: 'success',
                duration: 5000
              });
              checkForUpdates();
            }
          }
        }
      } catch (error) {
        console.error('Error getting progress:', error);
      }
    }, 500);

    // بدء التحديث
    try {
      const response = await fetch(getApiUrl('/api/update_system.php?action=start'));
      const data = await response.json();
      
      if (!data.success) {
        clearInterval(progressIntervalRef.current);
        setUpdating(false);
        throw new Error(data.message);
      }
    } catch (error) {
      clearInterval(progressIntervalRef.current);
      setUpdating(false);
      toast({
        title: 'فشل في بدء التحديث',
        description: error.message,
        status: 'error',
        duration: 5000
      });
    }
  };

  // تنظيف عند إلغاء المكون
  useEffect(() => {
    return () => {
      if (progressIntervalRef.current) {
        clearInterval(progressIntervalRef.current);
      }
    };
  }, []);

  // التحقق من التحديثات عند التحميل
  useEffect(() => {
    checkForUpdates();
  }, [checkForUpdates]);

  // حفظ changelog
  const saveChangelog = async () => {
    try {
      const response = await fetch(getApiUrl('/api/update_system.php'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'save_changelog',
          changelog: {
            version: updateInfo.currentVersion,
            updates: [
              { date: new Date().toISOString(), summary: newChangelog },
              ...updateInfo.changelog
            ]
          }
        })
      });
      const data = await response.json();
      
      if (data.success) {
        toast({ title: 'تم حفظ سجل التغييرات', status: 'success' });
        setNewChangelog('');
        onChangelogClose();
        checkForUpdates();
      }
    } catch (error) {
      toast({ title: 'فشل في الحفظ', status: 'error' });
    }
  };

  // رسالة الحالة
  const getStatusMessage = () => {
    switch (progress.status) {
      case 'starting': return 'جاري بدء التحديث...';
      case 'extracting': return 'جاري فك الضغط...';
      case 'updating': return 'جاري تحديث الملفات...';
      case 'completed': return 'اكتمل التحديث بنجاح!';
      case 'error': return 'حدث خطأ أثناء التحديث';
      default: return '';
    }
  };

  // لون شريط التقدم
  const getProgressColor = () => {
    switch (progress.status) {
      case 'completed': return 'green';
      case 'error': return 'red';
      default: return 'blue';
    }
  };

  if (loading) {
    return (
      <Box p={8} textAlign="center">
        <Spinner size="xl" color="blue.400" />
        <Text mt={4} color={subText}>جاري التحقق من التحديثات...</Text>
      </Box>
    );
  }

  return (
    <Box>
      <VStack align="stretch" spacing={6}>
        {/* حالة النظام */}
        <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
          <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
            <HStack spacing="3">
              <Icon as={RocketOutlined} color="blue.300" boxSize={5} />
              <Heading size="sm" color={headerText}>حالة النظام</Heading>
            </HStack>
          </CardHeader>
          <CardBody>
            <VStack align="stretch" spacing={4}>
              <HStack justify="space-between">
                <HStack>
                  <Icon as={InfoCircleOutlined} color="blue.300" />
                  <Text color={subText}>الإصدار الحالي:</Text>
                </HStack>
                <Badge colorScheme="blue" fontSize="md" px={3} py={1}>
                  v{updateInfo.currentVersion}
                </Badge>
              </HStack>

              {updateInfo.lastCheck && (
                <HStack justify="space-between">
                  <HStack>
                    <Icon as={ClockCircleOutlined} color="gray.400" />
                    <Text color={subText}>آخر فحص:</Text>
                  </HStack>
                  <Text color={subText} fontSize="sm">{updateInfo.lastCheck}</Text>
                </HStack>
              )}

              <Divider borderColor={cardBorder} />

              {updateInfo.hasUpdate ? (
                <Alert status="info" bg="blue.900" borderRadius="lg" border="1px solid" borderColor="blue.600">
                  <AlertIcon />
                  <Box>
                    <Text fontWeight="bold" color="blue.100">
                      يوجد تحديث جاهز للتثبيت
                    </Text>
                    <AlertDescription color="blue.200">
                      حجم الملف: {updateInfo.fileSize}
                      {updateInfo.newVersion && ` • الإصدار الجديد: v${updateInfo.newVersion}`}
                    </AlertDescription>
                  </Box>
                </Alert>
              ) : (
                <Alert status="success" bg="green.900" borderRadius="lg" border="1px solid" borderColor="green.600">
                  <AlertIcon />
                  <Box>
                    <Text fontWeight="bold" color="green.100">
                      لا يوجد تحديثات جديدة
                    </Text>
                    <AlertDescription color="green.200">
                      النظام محدث لآخر إصدار ✓
                    </AlertDescription>
                  </Box>
                </Alert>
              )}
            </VStack>
          </CardBody>
        </Card>

        {/* رفع التحديث */}
        <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
          <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
            <HStack spacing="3">
              <Icon as={CloudUploadOutlined} color="purple.300" boxSize={5} />
              <Heading size="sm" color={headerText}>رفع تحديث جديد</Heading>
            </HStack>
          </CardHeader>
          <CardBody>
            <VStack spacing={4}>
              <Text color={subText} textAlign="center">
                ارفع ملف <code style={{ color: '#63b3ed' }}>deploy.zip</code> لتحديث النظام
              </Text>
              
              <input
                type="file"
                ref={fileInputRef}
                accept=".zip"
                onChange={handleFileUpload}
                style={{ display: 'none' }}
              />
              
              <Button
                leftIcon={<Icon as={CloudUploadOutlined} />}
                colorScheme="purple"
                size="lg"
                onClick={() => fileInputRef.current?.click()}
                isLoading={uploading}
                loadingText="جاري الرفع..."
                isDisabled={updating}
              >
                اختر ملف التحديث
              </Button>
            </VStack>
          </CardBody>
        </Card>

        {/* شريط التقدم */}
        {updating && (
          <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
            <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
              <HStack spacing="3">
                <Spinner size="sm" color="blue.300" />
                <Heading size="sm" color={headerText}>جاري التحديث...</Heading>
              </HStack>
            </CardHeader>
            <CardBody>
              <VStack spacing={4} align="stretch">
                <HStack justify="space-between">
                  <Text color={subText}>{getStatusMessage()}</Text>
                  <Badge colorScheme={getProgressColor()}>{progress.progress}%</Badge>
                </HStack>
                
                <Progress
                  value={progress.progress}
                  colorScheme={getProgressColor()}
                  size="lg"
                  borderRadius="full"
                  hasStripe
                  isAnimated
                />

                {progress.currentFile && (
                  <HStack>
                    <Icon as={FileOutlined} color="blue.300" />
                    <Text color={subText} fontSize="sm" isTruncated>
                      {progress.currentFile}
                    </Text>
                  </HStack>
                )}

                <HStack justify="space-between" fontSize="sm" color={subText}>
                  <Text>الملفات المعالجة: {progress.processedFiles}/{progress.totalFiles}</Text>
                  <Text>تم تحديث: {progress.updatedFiles.length}</Text>
                </HStack>

                {/* قائمة الملفات المحدثة */}
                {progress.updatedFiles.length > 0 && (
                  <Box maxH="150px" overflowY="auto" bg={headerBg} p={3} borderRadius="lg">
                    <Text color="green.300" fontSize="sm" mb={2}>الملفات المحدثة:</Text>
                    <List spacing={1}>
                      {progress.updatedFiles.slice(-10).map((file, idx) => (
                        <ListItem key={idx} fontSize="xs" color={subText}>
                          <ListIcon as={CheckCircleOutlined} color="green.400" />
                          {file}
                        </ListItem>
                      ))}
                    </List>
                  </Box>
                )}

                {/* الأخطاء */}
                {progress.errors.length > 0 && (
                  <Alert status="error" borderRadius="lg">
                    <AlertIcon />
                    <Box>
                      {progress.errors.map((err, idx) => (
                        <Text key={idx} fontSize="sm">{err}</Text>
                      ))}
                    </Box>
                  </Alert>
                )}
              </VStack>
            </CardBody>
          </Card>
        )}

        {/* أزرار الإجراءات */}
        <HStack justify="center" spacing={4} flexWrap="wrap">
          <Button
            leftIcon={<Icon as={SyncOutlined} />}
            colorScheme="blue"
            variant="outline"
            onClick={checkForUpdates}
            isDisabled={updating}
          >
            التحقق من التحديثات
          </Button>

          {updateInfo.hasUpdate && (
            <Button
              leftIcon={<Icon as={DownloadOutlined} />}
              colorScheme="green"
              size="lg"
              onClick={startUpdate}
              isLoading={updating}
              loadingText="جاري التحديث..."
            >
              تثبيت التحديث الآن
            </Button>
          )}

          <Button
            leftIcon={<Icon as={HistoryOutlined} />}
            colorScheme="gray"
            variant="ghost"
            onClick={onChangelogOpen}
          >
            سجل التغييرات
          </Button>
        </HStack>

        {/* سجل التغييرات */}
        <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
          <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
            <HStack spacing="3">
              <Icon as={HistoryOutlined} color="orange.300" boxSize={5} />
              <Heading size="sm" color={headerText}>آخر التحديثات</Heading>
            </HStack>
          </CardHeader>
          <CardBody>
            {updateInfo.changelog && updateInfo.changelog.length > 0 ? (
              <List spacing={3}>
                {updateInfo.changelog.slice(0, 5).map((update, idx) => (
                  <ListItem key={idx} p={3} bg={headerBg} borderRadius="lg">
                    <HStack justify="space-between" mb={1}>
                      <Badge colorScheme="blue">{update.date?.split('T')[0] || update.date?.split(' ')[0]}</Badge>
                      {update.filesUpdated && (
                        <Badge colorScheme="green">{update.filesUpdated} ملف</Badge>
                      )}
                    </HStack>
                    <Text color={subText} fontSize="sm">{update.summary}</Text>
                  </ListItem>
                ))}
              </List>
            ) : (
              <Text color={subText} textAlign="center" py={4}>
                لا يوجد سجل تحديثات سابقة
              </Text>
            )}
          </CardBody>
        </Card>

        {/* تحذيرات */}
        <Alert status="warning" bg="orange.900" borderRadius="lg" border="1px solid" borderColor="orange.600">
          <AlertIcon />
          <Box>
            <Text fontWeight="bold" color="orange.100">تنبيه هام</Text>
            <AlertDescription color="orange.200" fontSize="sm">
              • يُنصح بأخذ نسخة احتياطية قبل التحديث<br />
              • لا تغلق الصفحة أثناء عملية التحديث<br />
              • الملفات المحمية (config, uploads) لن يتم تعديلها
            </AlertDescription>
          </Box>
        </Alert>
      </VStack>

      {/* Modal سجل التغييرات */}
      <Modal isOpen={isChangelogOpen} onClose={onChangelogClose} size="xl">
        <ModalOverlay bg="rgba(0,0,0,0.7)" />
        <ModalContent bg={cardBg} borderColor={cardBorder}>
          <ModalHeader color={headerText}>
            <HStack>
              <Icon as={HistoryOutlined} />
              <Text>سجل التغييرات</Text>
            </HStack>
          </ModalHeader>
          <ModalCloseButton color={headerText} />
          <ModalBody>
            <VStack spacing={4} align="stretch">
              <FormControl>
                <FormLabel color={subText}>إضافة ملاحظة جديدة</FormLabel>
                <Textarea
                  value={newChangelog}
                  onChange={(e) => setNewChangelog(e.target.value)}
                  placeholder="وصف التغييرات..."
                  bg={headerBg}
                  borderColor={cardBorder}
                  color={headerText}
                />
              </FormControl>

              <Divider borderColor={cardBorder} />

              <Text fontWeight="bold" color={headerText}>السجل السابق:</Text>
              {updateInfo.changelog?.map((update, idx) => (
                <Box key={idx} p={3} bg={headerBg} borderRadius="lg">
                  <HStack justify="space-between" mb={1}>
                    <Badge colorScheme="blue">{update.date?.split('T')[0] || update.date?.split(' ')[0]}</Badge>
                  </HStack>
                  <Text color={subText} fontSize="sm">{update.summary}</Text>
                </Box>
              ))}
            </VStack>
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onChangelogClose} color={subText}>
              إغلاق
            </Button>
            <Button colorScheme="blue" onClick={saveChangelog} isDisabled={!newChangelog.trim()}>
              حفظ
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Box>
  );
};

export default NewUpdateSettings;

