import React, { useState } from 'react';
import { 
  Box,
  Heading,
  Text,
  HStack,
  VStack,
  Button, 
  Icon,
} from '@chakra-ui/react';
import { 
  FiUpload, 
  FiRefreshCw, 
  FiPlus, 
  FiDatabase,
  FiLink,
  FiMonitor,
} from 'react-icons/fi';

// Import tab contents
import NewFingerprintSettings from '../components/NewFingerprintSettings';
import FingerprintImportTab from '../components/FingerprintImportTab';
import FingerprintIntegrationTab from '../components/FingerprintIntegrationTab';
import VirtualFingerprintDevice from '../components/VirtualFingerprintDevice';

const FingerprintManagement = () => {
  const [activeTabIndex, setActiveTabIndex] = useState(0);

  // Tab change handler
  const handleTabChange = (index) => {
    setActiveTabIndex(index);
  };


  return (
    <>
      {/* Header Section */}
      <Box mb="8">
        <HStack spacing="8" align="flex-start">
          {/* Title Section */}
          <VStack align="flex-start" spacing="2" flex="1" minW="300px">
            <Heading size="lg" className="stake-heading-3">
              إدارة البصمة
            </Heading>

          </VStack>
        </HStack>
      </Box>

      {/* Sidebar and Content Layout */}
      <HStack align="flex-start" spacing="6">
        {/* Sidebar Navigation */}
        <Box w="250px" p="4" bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" border="1px solid" borderColor="gray.200">
          <VStack align="stretch" spacing="2">
            <Button
              leftIcon={<FiDatabase size="16" />}
              variant="ghost"
              justifyContent="flex-start"
              h="48px"
              w="100%"
              bg={activeTabIndex === 0 ? "rgba(255, 255, 255, 0.1)" : "transparent"}
              color="white"
              onClick={() => handleTabChange(0)}
              _hover={{
                bg: "rgba(255, 255, 255, 0.1)"
              }}
              _active={{
                bg: "rgba(255, 255, 255, 0.1)"
              }}
            >
              الأجهزة
            </Button>
            <Button
              leftIcon={<FiUpload size="16" />}
              variant="ghost"
              justifyContent="flex-start"
              h="48px"
              w="100%"
              bg={activeTabIndex === 1 ? "rgba(255, 255, 255, 0.1)" : "transparent"}
              color="white"
              onClick={() => handleTabChange(1)}
              _hover={{
                bg: "rgba(255, 255, 255, 0.1)"
              }}
              _active={{
                bg: "rgba(255, 255, 255, 0.1)"
              }}
            >
              الاستيراد
            </Button>
            <Button
              leftIcon={<FiLink size="16" />}
              variant="ghost"
              justifyContent="flex-start"
              h="48px"
              w="100%"
              bg={activeTabIndex === 2 ? "rgba(255, 255, 255, 0.1)" : "transparent"}
              color="white"
              onClick={() => handleTabChange(2)}
              _hover={{
                bg: "rgba(255, 255, 255, 0.1)"
              }}
              _active={{
                bg: "rgba(255, 255, 255, 0.1)"
              }}
            >
              التكامل
            </Button>
            <Button
              leftIcon={<FiMonitor size="16" />}
              variant="ghost"
              justifyContent="flex-start"
              h="48px"
              w="100%"
              bg={activeTabIndex === 3 ? "rgba(255, 255, 255, 0.1)" : "transparent"}
              color="white"
              onClick={() => handleTabChange(3)}
              _hover={{
                bg: "rgba(255, 255, 255, 0.1)"
              }}
              _active={{
                bg: "rgba(255, 255, 255, 0.1)"
              }}
            >
              الجهاز الافتراضي
            </Button>
          </VStack>
        </Box>

        {/* Main Content */}
        <Box flex="1">
          {/* Tab Content */}
          {activeTabIndex === 0 && <NewFingerprintSettings />}
          {activeTabIndex === 1 && <FingerprintImportTab />}
          {activeTabIndex === 2 && <FingerprintIntegrationTab />}
          {activeTabIndex === 3 && <VirtualFingerprintDevice />}
        </Box>
      </HStack>
    </>
  );
};

export default FingerprintManagement;
