import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { getApiUrl } from '../utils/apiUrlHelper';
import {
  Box,
  Container,
  VStack,
  HStack,
  Text,
  Heading,
  Button,
  Card,
  CardBody,
  CardHeader,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  TableContainer,
  Badge,
  Grid,
  GridItem,
  Avatar,
  Icon,
  useColorModeValue,
  useToast,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  ModalCloseButton,
  useDisclosure,
  FormControl,
  FormLabel,
  FormErrorMessage,
  Input,
  Select,
  Textarea,
  NumberInput,
  NumberInputField,
  NumberInputStepper,
  NumberIncrementStepper,
  NumberDecrementStepper,
  Divider,
  Flex,
  Spacer,
  Circle,
  Image,
  Stack,
  SimpleGrid,
  InputGroup,
  InputLeftElement,
  InputRightElement,
  Menu,
  MenuButton,
  MenuList,
  MenuItem,
  MenuDivider,
  IconButton,
  Tooltip,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Progress,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  StatArrow,
  Checkbox,
  CheckboxGroup,
} from '@chakra-ui/react';
import {
  FiUsers,
  FiPlus,
  FiSearch,
  FiChevronUp,
  FiChevronDown,
  FiFilter,
  FiEdit,
  FiTrash2,
  FiEye,
  FiMoreVertical,
  FiDownload,
  FiUpload,
  FiRefreshCw,
  FiUser,
  FiMail,
  FiCheckCircle,
  FiXCircle,
  FiBriefcase,
  FiDollarSign,
  FiX,
  FiHash,
  FiPhone,
  FiMapPin,
  FiCalendar,
  FiClock,
  FiAlertCircle,
  FiUserPlus,
  FiUserMinus,
  FiSettings,
  FiSave,
  FiPercent,
  FiMaximize,
  FiMinimize,
  FiTarget,
  FiKey,
} from 'react-icons/fi';
import EnglishKeyTooltip from '../components/EnglishKeyTooltip';
import { useForm, useWatch, Controller, watch } from 'react-hook-form';
import useCurrency from '../hooks/useCurrency';

const PremiumEmployees = () => {
  const toast = useToast();
  const { isOpen: isAddOpen, onOpen: onAddOpen, onClose: onAddClose } = useDisclosure();
  const { isOpen: isEditOpen, onOpen: onEditOpen, onClose: onEditClose } = useDisclosure();
  const { isOpen: isViewOpen, onOpen: onViewOpen, onClose: onViewClose } = useDisclosure();
  
  const [employees, setEmployees] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [costCenters, setCostCenters] = useState([]);
  const [departmentCostCenters, setDepartmentCostCenters] = useState([]);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedDepartment, setSelectedDepartment] = useState('');
  const [selectedCostCenter, setSelectedCostCenter] = useState('');
  const [selectedSalaryType, setSelectedSalaryType] = useState('');
  const [selectedEmployee, setSelectedEmployee] = useState(null);
  const [selectedRowKeys, setSelectedRowKeys] = useState([]);
  const [selectedEmployees, setSelectedEmployees] = useState([]);
  const { isOpen: isBulkEditOpen, onOpen: onBulkEditOpen, onClose: onBulkEditClose } = useDisclosure();
  const { isOpen: isBulkDeleteOpen, onOpen: onBulkDeleteOpen, onClose: onBulkDeleteClose } = useDisclosure();
  const [stats, setStats] = useState({
    total: 0,
    active: 0,
    inactive: 0,
    departments: 0,
  });
  
  // View mode state
  const [viewMode, setViewMode] = useState('table'); // 'table' or 'grid'
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showAllContent, setShowAllContent] = useState(false); // إضافة حالة عرض كل المحتوى
  
  // Sorting function
  const handleSort = (key) => {
    let direction = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  // Get sort icon
  const getSortIcon = (key) => {
    if (sortConfig.key !== key) {
      return <Icon as={FiChevronUp} boxSize="4" className="stake-text-secondary" />;
    }
    return sortConfig.direction === 'asc' 
      ? <Icon as={FiChevronUp} boxSize="4" color="blue.500" />
      : <Icon as={FiChevronDown} boxSize="4" color="blue.500" />;
  };
  
  // Bulk edit form state
  const [bulkEditForm, setBulkEditForm] = useState({
    salary_type: '',
    department: '',
    cost_center: '',
    position: '',
    status: '',
    base_salary: '',
    location: ''
  });
  
  // Sorting state
  const [sortConfig, setSortConfig] = useState({
    key: null,
    direction: 'asc' // 'asc' or 'desc'
  });
  
  // Pagination state - تحسين الأداء
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage] = useState(20); // عرض 20 موظف في كل صفحة

  // Filter states - Updated to fix undefined error
  const [salaryTypeFilter, setSalaryTypeFilter] = useState('');
  const [departmentFilter, setDepartmentFilter] = useState('');
  const [costCenterFilter, setCostCenterFilter] = useState('');
  
  // Combined filter states
  const [selectedFilterType, setSelectedFilterType] = useState('');

  const { register, handleSubmit, reset, control, setValue, trigger, watch, formState: { errors } } = useForm();
  const { formatCurrency, isCurrencyEnabled, reloadSettings } = useCurrency();

  // Fullscreen functions - تحسين الأداء
  const toggleFullscreen = useCallback(() => {
    setIsFullscreen(!isFullscreen);
  }, [isFullscreen]);

  // Clear all filters - تحسين الأداء
  const clearFilters = useCallback(() => {
    setSearchTerm('');
    setSalaryTypeFilter('');
    setDepartmentFilter('');
    setCostCenterFilter('');
    setSelectedFilterType('');
  }, []);

  // Handle filter type selection
  const handleFilterTypeSelect = (filterType) => {
    setSelectedFilterType(filterType);
    // Clear other filters when selecting a new type
    setSalaryTypeFilter('');
    setDepartmentFilter('');
    setCostCenterFilter('');
  };

  // Handle filter value selection
  const handleFilterValueSelect = (value) => {
    switch (selectedFilterType) {
      case 'salaryType':
        setSalaryTypeFilter(value);
        break;
      case 'department':
        setDepartmentFilter(value);
        break;
      case 'costCenter':
        setCostCenterFilter(value);
        break;
      default:
        break;
    }
    setSelectedFilterType('');
  };

  useEffect(() => {
    loadEmployees();
    loadDepartments();
    loadCostCenters();
    reloadSettings(); // إعادة تحميل إعدادات العملة
  }, []);

  // مراقبة تغيير القسم في مودال إضافة موظف جديد
  const watchedDepartment = watch('department');
  console.log('watchedDepartment:', watchedDepartment);
  useEffect(() => {
    if (watchedDepartment && isAddOpen) {
      loadCostCentersByDepartment(watchedDepartment);
    } else if (isAddOpen && !watchedDepartment) {
      // مسح مراكز التكلفة عند عدم وجود قسم مختار
      setDepartmentCostCenters([]);
    }
  }, [watchedDepartment, isAddOpen]);

  // مراقبة تغيير القسم في مودال تعديل الموظف
  useEffect(() => {
    if (watchedDepartment && isEditOpen) {
      loadCostCentersByDepartment(watchedDepartment);
    } else if (isEditOpen && !watchedDepartment) {
      // مسح مراكز التكلفة عند عدم وجود قسم مختار
      setDepartmentCostCenters([]);
    }
  }, [watchedDepartment, isEditOpen]);

  // مراقبة نوع الراتب في مودال التعديل
  const watchedSalaryType = watch('salary_type');
  console.log('watchedSalaryType:', watchedSalaryType);
  
  // إعداد قيمة salary_type عند فتح مودال التعديل
  useEffect(() => {
    if (isEditOpen && selectedEmployee) {
      setValue('salary_type', selectedEmployee.salary_type || 'Monthly');
      setValue('department', selectedEmployee.department || '');
      // تحميل مراكز التكلفة للقسم المختار
      if (selectedEmployee.department) {
        loadCostCentersByDepartment(selectedEmployee.department);
      }
    }
  }, [isEditOpen, selectedEmployee, setValue]);

  const loadEmployees = async () => {
    setLoading(true);
    try {
      console.log('Loading employees from database...');
      const response = await fetch(getApiUrl('/api/unified_employees_api.php?action=get_employees'));
      const data = await response.json();
      
      if (data.success && data.data) {
        console.log('Employees loaded successfully:', data.data);
        console.log('First employee department_description:', data.data[0]?.department_description);
        console.log('First employee AC-No.:', data.data[0]?.['AC-No.']);
        
        // تحويل البيانات إلى التنسيق المطلوب
        const formattedEmployees = data.data.map(emp => ({
          id: emp.id,
          employee_code: emp.employee_code || '',
          name: emp.name || emp.name_en || '',
          name_ar: emp.name_ar || emp.name || '',
          base_salary: emp.base_salary || emp.salary || 0,
          salary_type: emp.salary_type || 'Monthly',
          department: emp.department || emp.department_name || '',
          department_description: emp.department_description || '',
          cost_center: emp.cost_center || '',
          position: emp.position || '',
          location: emp.location || 'برج العرب',
          status: emp.status || 'active',
          hire_date: emp.hire_date || emp.created_at || new Date().toISOString().split('T')[0],
          is_insured: emp.is_insured || false,
          daily_work_hours: emp.daily_work_hours || 8,
          'AC-No.': emp['AC-No.'] || '',
        }));
        
        setEmployees(formattedEmployees);
        console.log('Formatted employees with AC-No.:', formattedEmployees.map(emp => ({ name: emp.name, ac_no: emp['AC-No.'] })));
        setStats({
          total: formattedEmployees.length,
          active: formattedEmployees.filter(emp => emp.status === 'active').length,
          inactive: formattedEmployees.filter(emp => emp.status === 'inactive').length,
          departments: [...new Set(formattedEmployees.map(emp => emp.department).filter(Boolean))].length,
        });
        
        toast({
          title: 'تم تحميل الموظفين بنجاح',
          description: `تم تحميل ${formattedEmployees.length} موظف من قاعدة البيانات`,
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
      } else {
        throw new Error(data.message || 'فشل في تحميل بيانات الموظفين');
      }
    } catch (error) {
      console.error('Error loading employees:', error);
      toast({
        title: 'خطأ في تحميل الموظفين',
        description: error.message || 'حدث خطأ أثناء تحميل بيانات الموظفين',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    } finally {
      setLoading(false);
    }
  };

  const loadDepartments = async () => {
    try {
      console.log('Loading departments from database...');
      const response = await fetch(getApiUrl('/api/unified_employees_api.php?action=get_departments'));
      const data = await response.json();
      
      if (data.success && data.data) {
        console.log('Departments loaded successfully:', data.data);
        setDepartments(data.data);
      } else {
        console.warn('Failed to load departments, using fallback data');
        // Fallback data
        const fallbackDepartments = [
          { id: 1, name: 'المبيعات' },
          { id: 2, name: 'المحاسبة' },
          { id: 3, name: 'التقنية' },
          { id: 4, name: 'الموارد البشرية' },
          { id: 5, name: 'التسويق' },
        ];
        setDepartments(fallbackDepartments);
      }
    } catch (error) {
      console.error('Error loading departments:', error);
      // Fallback data on error
      const fallbackDepartments = [
        { id: 1, name: 'المبيعات' },
        { id: 2, name: 'المحاسبة' },
        { id: 3, name: 'التقنية' },
        { id: 4, name: 'الموارد البشرية' },
        { id: 5, name: 'التسويق' },
      ];
      setDepartments(fallbackDepartments);
    }
  };

  const loadCostCenters = async () => {
    try {
      console.log('Loading cost centers from database...');
      const response = await fetch(getApiUrl('/api/cost_centers.php?action=list'));
      const data = await response.json();
      
      if (data.success && data.data) {
        console.log('Cost centers loaded successfully:', data.data);
        setCostCenters(data.data);
      } else {
        console.warn('Failed to load cost centers, using fallback data');
        // Fallback data
        const fallbackCostCenters = [
          { id: 1, name: 'مركز مبيعات 1' },
          { id: 2, name: 'مركز محاسبة 1' },
          { id: 3, name: 'مركز تقنية 1' },
          { id: 4, name: 'مركز موارد بشرية 1' },
          { id: 5, name: 'مركز تسويق 1' },
        ];
        setCostCenters(fallbackCostCenters);
      }
    } catch (error) {
      console.error('Error loading cost centers:', error);
      // Fallback data on error
      const fallbackCostCenters = [
        { id: 1, name: 'مركز مبيعات 1' },
        { id: 2, name: 'مركز محاسبة 1' },
        { id: 3, name: 'مركز تقنية 1' },
        { id: 4, name: 'مركز موارد بشرية 1' },
        { id: 5, name: 'مركز تسويق 1' },
      ];
      setCostCenters(fallbackCostCenters);
    }
  };

  const loadCostCentersByDepartment = async (departmentName) => {
    try {
      console.log('Loading cost centers for department:', departmentName);
      const response = await fetch(getApiUrl(`/api/unified_employees_api.php?action=get_cost_centers_by_department&department=${encodeURIComponent(departmentName)}`));
      const data = await response.json();
      
      if (data.success && data.data) {
        console.log('Department cost centers loaded successfully:', data.data);
        setDepartmentCostCenters(data.data);
      } else {
        console.warn('Failed to load department cost centers, using all cost centers');
        setDepartmentCostCenters(costCenters);
      }
    } catch (error) {
      console.error('Error loading department cost centers:', error);
      setDepartmentCostCenters(costCenters);
    }
  };

  const handleAddEmployee = async (data) => {
    try {
      console.log('Adding new employee:', data);
      console.log('Cost center value:', data.cost_center);
      console.log('Department value:', data.department);
      console.log('AC-No. value:', data.ac_no);
      
      const response = await fetch(getApiUrl('/api/unified_employees_api.php'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          action: 'add_employee',
          employee_data: {
            employee_code: data.employee_code,
            'AC-No.': data.ac_no,
            name: data.name,
            name_ar: data.name_ar,
            base_salary: data.base_salary,
            salary_type: data.salary_type,
            department: data.department,
            cost_center: data.cost_center,
            position: data.position,
            location: data.location,
            hire_date: data.hire_date,
            status: data.status || 'active',
            is_insured: data.is_insured === true || data.is_insured === 'true',
          }
        })
      });
      
      const result = await response.json();
      
      if (result.success) {
        toast({
          title: 'تم إضافة الموظف بنجاح',
          description: `تم إضافة ${data.name_ar || data.name} إلى قاعدة البيانات`,
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        
        reset();
        onAddClose();
        
        // إعادة تحميل قائمة الموظفين
        await loadEmployees();
      } else {
        throw new Error(result.message || 'فشل في إضافة الموظف');
      }
    } catch (error) {
      console.error('Error adding employee:', error);
      toast({
        title: 'خطأ في إضافة الموظف',
        description: error.message || 'حدث خطأ أثناء إضافة الموظف',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const handleEditEmployee = async (data) => {
    try {
      console.log('Updating employee:', selectedEmployee.id, data);
      console.log('AC-No. value:', data.ac_no);
      
      const response = await fetch(getApiUrl('/api/unified_employees_api.php'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          action: 'update_employee',
          employee_id: selectedEmployee.id,
          employee_data: {
            employee_code: data.employee_code,
            'AC-No.': data.ac_no,
            name: data.name,
            name_ar: data.name_ar,
            base_salary: data.base_salary,
            salary_type: data.salary_type,
            department: data.department,
            cost_center: data.cost_center,
            position: data.position,
            location: data.location,
            hire_date: data.hire_date,
            status: data.status || 'active',
            is_insured: data.is_insured === true || data.is_insured === 'true',
          }
        })
      });
      
      const result = await response.json();
      
      if (result.success) {
        toast({
          title: 'تم تحديث بيانات الموظف',
          description: `تم تحديث بيانات ${data.name_ar || data.name} بنجاح`,
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        
        reset();
        onEditClose();
        
        // إعادة تحميل قائمة الموظفين
        await loadEmployees();
      } else {
        throw new Error(result.message || 'فشل في تحديث بيانات الموظف');
      }
    } catch (error) {
      console.error('Error updating employee:', error);
      toast({
        title: 'خطأ في تحديث بيانات الموظف',
        description: error.message || 'حدث خطأ أثناء تحديث بيانات الموظف',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const handleDeleteEmployee = async (employee) => {
    try {
      console.log('Deleting employee:', employee.id);
      
      const response = await fetch(getApiUrl('/api/unified_employees_api.php'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          action: 'delete_employee',
          employee_id: employee.id
        })
      });
      
      const result = await response.json();
      
      if (result.success) {
        toast({
          title: 'تم حذف الموظف',
          description: `تم حذف ${employee.name_ar || employee.name} من قاعدة البيانات`,
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        
        // إعادة تحميل قائمة الموظفين
        await loadEmployees();
      } else {
        throw new Error(result.message || 'فشل في حذف الموظف');
      }
    } catch (error) {
      console.error('Error deleting employee:', error);
      toast({
        title: 'خطأ في حذف الموظف',
        description: error.message || 'حدث خطأ أثناء حذف الموظف',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  // دوال التحديد الجماعي
  const handleRowSelection = {
    selectedRowKeys,
    onChange: (selectedRowKeys, selectedRows) => {
      setSelectedRowKeys(selectedRowKeys);
      setSelectedEmployees(selectedRows);
    },
    getCheckboxProps: (record) => ({
      name: record.name,
    }),
  };

  const handleBulkEdit = () => {
    if (selectedEmployees.length === 0) {
      toast({
        title: 'تحذير',
        description: 'يرجى اختيار موظف واحد على الأقل',
        status: 'warning',
        duration: 3000,
        isClosable: true,
      });
      return;
    }
    onBulkEditOpen();
  };

  const handleBulkDelete = async () => {
    if (selectedEmployees.length === 0) {
      toast({
        title: 'تحذير',
        description: 'يرجى اختيار موظف واحد على الأقل',
        status: 'warning',
        duration: 3000,
        isClosable: true,
      });
      return;
    }

    try {
      const employeeIds = selectedEmployees.map(emp => emp.id);
      const response = await fetch(getApiUrl('/api/unified_employees_api.php'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'bulk_delete_employees',
          employee_ids: employeeIds
        })
      });
      
      const data = await response.json();
      if (data.success) {
        toast({
          title: 'تم الحذف بنجاح',
          description: `تم حذف ${selectedEmployees.length} موظف بنجاح`,
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        setSelectedRowKeys([]);
        setSelectedEmployees([]);
        loadEmployees();
      } else {
        toast({
          title: 'خطأ في الحذف',
          description: 'خطأ في حذف الموظفين: ' + data.message,
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
      }
    } catch (error) {
      toast({
        title: 'خطأ في الحذف',
        description: 'خطأ في حذف الموظفين: ' + error.message,
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const handleBulkEditSubmit = async (values) => {
    try {
      const employeeIds = selectedEmployees.map(emp => emp.id);
      const response = await fetch(getApiUrl('/api/unified_employees_api.php'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'bulk_update_employees',
          employee_ids: employeeIds,
          update_data: values
        })
      });
      
      const data = await response.json();
      if (data.success) {
        toast({
          title: 'تم التحديث بنجاح',
          description: `تم تحديث ${selectedEmployees.length} موظف بنجاح`,
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        onBulkEditClose();
        setSelectedRowKeys([]);
        setSelectedEmployees([]);
        loadEmployees();
      } else {
        toast({
          title: 'خطأ في التحديث',
          description: 'خطأ في تحديث الموظفين: ' + data.message,
          status: 'error',
          duration: 5000,
          isClosable: true,
        });
      }
    } catch (error) {
      toast({
        title: 'خطأ في التحديث',
        description: 'خطأ في تحديث الموظفين: ' + error.message,
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  const handleCalculateSalary = async (employee) => {
    try {
      console.log('Calculating salary for employee:', employee.id);
      
      const response = await fetch(getApiUrl('/api/unified_salary_api_v2.php'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          action: 'calculate_employee',
          employee_id: employee.id,
          period: new Date().toISOString().slice(0, 7) // YYYY-MM format
        })
      });
      
      const result = await response.json();
      
      if (result.success) {
        const salaryAmount = result.data.net_salary || result.data.total_salary || 0;
        toast({
          title: 'تم حساب الراتب بنجاح',
          description: `راتب ${employee.name_ar || employee.name}: ${formatCurrency(salaryAmount)}`,
          status: 'success',
          duration: 5000,
          isClosable: true,
        });
      } else {
        throw new Error(result.message || 'فشل في حساب الراتب');
      }
    } catch (error) {
      console.error('Error calculating salary:', error);
      toast({
        title: 'خطأ في حساب الراتب',
        description: error.message || 'حدث خطأ أثناء حساب الراتب',
        status: 'error',
        duration: 5000,
        isClosable: true,
      });
    }
  };

  // Handle view employee - Fixed undefined error + تحسين الأداء
  const handleViewEmployee = useCallback((employee) => {
    setSelectedEmployee(employee);
    onViewOpen();
  }, [onViewOpen]);

  // Handle edit employee - Open edit modal + تحسين الأداء
  const handleEditEmployeeClick = useCallback((employee) => {
    console.log('Editing employee:', employee);
    setSelectedEmployee(employee);
    
    const formData = {
      employee_code: employee.employee_code || '',
      ac_no: employee['AC-No.'] || '',
      name: employee.name || '',
      name_ar: employee.name_ar || '',
      base_salary: employee.base_salary || 0,
      salary_type: employee.salary_type || 'Monthly',
      department: employee.department || '',
      cost_center: employee.cost_center || '',
      position: employee.position || '',
      location: employee.location || '',
      hire_date: employee.hire_date || '',
      status: employee.status || 'active',
      is_insured: employee.is_insured ? 'true' : 'false',
    };
    
    console.log('Form data to reset:', formData);
    console.log('Employee salary_type:', employee.salary_type);
    reset(formData);
    onEditOpen();
  }, [reset, onEditOpen]);

  // Handle edit modal close - Return to view modal
  const handleEditClose = useCallback(() => {
    onEditClose();
    // فتح مودال التفاصيل مرة أخرى بعد إغلاق مودال التعديل
    if (selectedEmployee) {
      onViewOpen();
    }
  }, [onEditClose, onViewOpen, selectedEmployee]);

  // تحسين الأداء - استخدام useMemo لتجنب إعادة الحساب في كل render
  const filteredEmployees = useMemo(() => {
    let filtered = employees.filter(employee => {
      const matchesSearch = employee.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                           employee.name_ar?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                           employee.employee_code?.toLowerCase().includes(searchTerm.toLowerCase());
      
      // استخدام الفلاتر الصحيحة - دمج فلاتر الوضع العادي ووضع ملء الشاشة
      const departmentFilterToUse = departmentFilter || selectedDepartment;
      const costCenterFilterToUse = costCenterFilter || selectedCostCenter;
      const salaryTypeFilterToUse = salaryTypeFilter || selectedSalaryType;
      
      const matchesDepartment = !departmentFilterToUse || employee.department === departmentFilterToUse;
      const matchesCostCenter = !costCenterFilterToUse || employee.cost_center === costCenterFilterToUse;
      const matchesSalaryType = !salaryTypeFilterToUse || employee.salary_type === salaryTypeFilterToUse;
      return matchesSearch && matchesDepartment && matchesCostCenter && matchesSalaryType;
    });

    // Apply sorting if configured
    if (sortConfig.key) {
      filtered.sort((a, b) => {
        let aValue = a[sortConfig.key];
        let bValue = b[sortConfig.key];

        // Handle different data types
        if (sortConfig.key === 'employee_code' || sortConfig.key === 'AC-No.') {
          // For employee codes, try to parse as numbers first
          aValue = parseInt(aValue) || aValue || '';
          bValue = parseInt(bValue) || bValue || '';
        } else if (sortConfig.key === 'base_salary') {
          // For salary, parse as numbers
          aValue = parseFloat(aValue) || 0;
          bValue = parseFloat(bValue) || 0;
        } else {
          // For text fields, convert to lowercase for case-insensitive sorting
          aValue = (aValue || '').toString().toLowerCase();
          bValue = (bValue || '').toString().toLowerCase();
        }

        if (aValue < bValue) {
          return sortConfig.direction === 'asc' ? -1 : 1;
        }
        if (aValue > bValue) {
          return sortConfig.direction === 'asc' ? 1 : -1;
        }
        return 0;
      });
    }

    return filtered;
  }, [employees, searchTerm, departmentFilter, costCenterFilter, salaryTypeFilter, selectedDepartment, selectedCostCenter, selectedSalaryType, sortConfig]);

  // Pagination - تحسين الأداء
  const paginatedEmployees = useMemo(() => {
    if (showAllContent) {
      return filteredEmployees; // عرض جميع السجلات
    }
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    return filteredEmployees.slice(startIndex, endIndex);
  }, [filteredEmployees, currentPage, itemsPerPage, showAllContent]);

  const totalPages = Math.ceil(filteredEmployees.length / itemsPerPage);

  const StatCard = ({ title, value, change, changeType, icon, color, bgGradient }) => (
    <Card
      className="stake-card"
      overflow="hidden"
      position="relative"
      transition="all 0.3s ease"
      boxShadow="0 4px 15px rgba(0, 0, 0, 0.05)"
    >
      <CardBody p="6">
        <HStack justify="space-between" align="flex-start" mb="4">
          <VStack align="flex-start" spacing="1">
            <Text fontSize="sm" fontWeight="medium" color="gray.600">
              {title}
            </Text>
            <Heading  color="gray.800" fontWeight="bold">
              {value}
            </Heading>
          </VStack>
          <Circle size="10" bg={bgGradient} color="white">
            <Icon as={icon} boxSize="5" />
          </Circle>
        </HStack>
        {change && (
          <HStack spacing="2">
            <Icon as={changeType === 'increase' ? 'FiTrendingUp' : 'FiTrendingDown'} color={changeType === 'increase' ? 'green.500' : 'red.500'} />
            <Text fontSize="sm" color={changeType === 'increase' ? 'green.600' : 'red.600'} fontWeight="medium">
              {change}
            </Text>
          </HStack>
        )}
      </CardBody>
    </Card>
  );

  return (
    <Box>
      {/* Header Section */}
      <Box mb="8">
        <HStack justify="space-between" align="center" mb="6">
          <VStack align="flex-start" spacing="2">
            <Heading  className="stake-heading-3">
              إدارة الموظفين
            </Heading>
          </VStack>
          <HStack spacing="3">
            <Box position="relative">
              <Button
                leftIcon={<FiDownload />}
                className="stake-btn-secondary expandable-btn"
                h="44px"
                w="44px"
                minW="44px"
                px="0"
                fontWeight="600"
                transition="all 0.3s ease"
                overflow="hidden"
                justifyContent="center"
                _hover={{
                  w: "120px",
                  minW: "120px",
                  px: "6",
                  bg: "var(--stake-bg-secondary)",
                  color: "#1475e1",
                  borderColor: "#1475e1",
                  transform: "translateY(-1px)",
                  boxShadow: "var(--stake-shadow-md)",
                  justifyContent: "flex-start"
                }}
              >
                <Text
                  position="absolute"
                  left="50px"
                  top="50%"
                  transform="translateY(-50%)"
                  opacity="0"
                  transition="opacity 0.3s ease 0.1s"
                  whiteSpace="nowrap"
                  fontSize="14px"
                  fontWeight="600"
                  color="inherit"
                  className="expandable-text"
                >
                  تصدير
                </Text>
              </Button>
            </Box>
            <Box position="relative">
              <Button
                leftIcon={<FiUpload />}
                className="stake-btn-secondary expandable-btn"
                h="44px"
                w="44px"
                minW="44px"
                px="0"
                fontWeight="600"
                transition="all 0.3s ease"
                overflow="hidden"
                justifyContent="center"
                _hover={{
                  w: "120px",
                  minW: "120px",
                  px: "6",
                  bg: "var(--stake-bg-secondary)",
                  color: "#1475e1",
                  borderColor: "#1475e1",
                  transform: "translateY(-1px)",
                  boxShadow: "var(--stake-shadow-md)",
                  justifyContent: "flex-start"
                }}
              >
                <Text
                  position="absolute"
                  left="50px"
                  top="50%"
                  transform="translateY(-50%)"
                  opacity="0"
                  transition="opacity 0.3s ease 0.1s"
                  whiteSpace="nowrap"
                  fontSize="14px"
                  fontWeight="600"
                  color="inherit"
                  className="expandable-text"
                >
                  استيراد
                </Text>
              </Button>
            </Box>
            <Box position="relative">
              <Button
                leftIcon={<FiPlus />}
                className="stake-btn expandable-btn"
                onClick={onAddOpen}
                h="44px"
                w="44px"
                minW="44px"
                px="0"
                fontWeight="600"
                transition="all 0.3s ease"
                overflow="hidden"
                justifyContent="center"
                _hover={{
                  w: "140px",
                  minW: "140px",
                  px: "6",
                  transform: "translateY(-1px)",
                  boxShadow: "var(--stake-shadow-md)",
                  justifyContent: "flex-start"
                }}
              >
                <Text
                  position="absolute"
                  left="50px"
                  top="50%"
                  transform="translateY(-50%)"
                  opacity="0"
                  transition="opacity 0.3s ease 0.1s"
                  whiteSpace="nowrap"
                  fontSize="14px"
                  fontWeight="600"
                  color="inherit"
                  className="expandable-text"
                >
                  إضافة موظف
                </Text>
              </Button>
            </Box>
          </HStack>
        </HStack>

        {/* Statistics Cards */}
      </Box>

      {/* Filters and Search */}
      <Box mb="6">
        <HStack spacing="4" align="end" wrap="wrap">
          {/* Search Bar */}
          <Box flex="1" minW="200px">
            <InputGroup>
              <Input
                placeholder="البحث بالاسم أو الكود..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                borderRadius="xl"
                className="stake-input"
                bg="var(--stake-bg-secondary)"
                border="1px solid"
                borderColor="var(--stake-border-primary)"
                color="var(--stake-text-primary)"
                pr="12"
                _focus={{
                  borderColor: 'var(--stake-border-accent)',
                  boxShadow: '0 0 0 1px var(--stake-border-accent)',
                  bg: 'var(--stake-bg-primary)'
                }}
                _hover={{
                  borderColor: 'var(--stake-border-accent)',
                  bg: 'var(--stake-bg-hover)'
                }}
                _placeholder={{
                  color: 'var(--stake-text-secondary)',
                  fontWeight: '500'
                }}
              />
              <InputRightElement>
                <Icon as={FiSearch} color="var(--stake-text-secondary)" />
              </InputRightElement>
            </InputGroup>
          </Box>

          {/* Combined Filter */}
          <Box
            display="flex"
            alignItems="center"
            gap="2"
            minW="250px"
          >
            {/* Filter Type Dropdown */}
            <Menu>
              <MenuButton
                as={Button}
                rightIcon={<FiChevronDown />}
                h="44px"
                flex="1"
                borderRadius="lg"
                border="none"
                boxShadow="none"
                className="stake-input"
                _focus={{
                  borderColor: "transparent",
                  boxShadow: "none"
                }}
                _hover={{
                  borderColor: "transparent",
                  boxShadow: "none"
                }}
              >
                {selectedFilterType ? 
                  (selectedFilterType === 'salaryType' ? 'نوع الراتب' :
                   selectedFilterType === 'department' ? 'القسم' :
                   selectedFilterType === 'costCenter' ? 'مركز التكلفة' : 'نوع الفلتر') :
                  'نوع الفلتر'
                }
              </MenuButton>
              <MenuList className="stake-card" bg="var(--stake-bg-primary, #0f212e)" border="1px solid #2f4553" boxShadow="0 12px 24px rgba(0,0,0,0.35)" borderRadius="12px">
                <MenuItem icon={<FiDollarSign />} onClick={() => handleFilterTypeSelect('salaryType')}>
                  نوع الراتب
                </MenuItem>
                <MenuItem icon={<FiBriefcase />} onClick={() => handleFilterTypeSelect('department')}>
                  القسم
                </MenuItem>
                <MenuItem icon={<FiBriefcase />} onClick={() => handleFilterTypeSelect('costCenter')}>
                  مركز التكلفة
                </MenuItem>
              </MenuList>
            </Menu>

            {/* Separator */}
            <Box w="1px" bg="var(--stake-border-primary)" h="20px" />

            {/* Filter Value Dropdown */}
            <Menu>
              <MenuButton
                as={Button}
                rightIcon={<FiChevronDown />}
                h="44px"
                flex="1"
                borderRadius="lg"
                border="none"
                boxShadow="none"
                className="stake-input"
                _focus={{
                  borderColor: "transparent",
                  boxShadow: "none"
                }}
                _hover={{
                  borderColor: "transparent",
                  boxShadow: "none"
                }}
                isDisabled={!selectedFilterType}
              >
                {selectedFilterType === 'salaryType' && salaryTypeFilter ? 
                  (salaryTypeFilter === 'Monthly' ? 'شهري' : 'أسبوعي') :
                selectedFilterType === 'department' && departmentFilter ? departmentFilter :
                selectedFilterType === 'costCenter' && costCenterFilter ? costCenterFilter :
                'اختر القيمة'
                }
              </MenuButton>
              <MenuList className="stake-card" bg="var(--stake-bg-primary, #0f212e)" border="1px solid #2f4553" boxShadow="0 12px 24px rgba(0,0,0,0.35)" borderRadius="12px">
                {selectedFilterType === 'salaryType' && (
                  <>
                    <MenuItem icon={<FiDollarSign />} onClick={() => setSalaryTypeFilter('Monthly')}>شهري</MenuItem>
                    <MenuItem icon={<FiDollarSign />} onClick={() => setSalaryTypeFilter('Weekly')}>أسبوعي</MenuItem>
                  </>
                )}
                {selectedFilterType === 'department' && (
                  <>
                    {departments.map(dept => (
                      <MenuItem key={dept.id} icon={<FiBriefcase />} onClick={() => setDepartmentFilter(dept.name)}>
                        {dept.description || dept.name}
                      </MenuItem>
                    ))}
                  </>
                )}
                {selectedFilterType === 'costCenter' && (
                  <>
                    {costCenters.map(center => (
                      <MenuItem key={center.id} icon={<FiBriefcase />} onClick={() => setCostCenterFilter(center.name)}>
                        {center.name}
                      </MenuItem>
                    ))}
                  </>
                )}
              </MenuList>
            </Menu>
          </Box>

          {/* Clear Filters Button */}
          <IconButton
            icon={<FiX />}
            variant="outline"
            colorScheme="red"
            onClick={clearFilters}
            w="44px"
            h="44px"
            className="stake-input"
            borderRadius="xl"
            aria-label="مسح الفلاتر"
            _hover={{
              bg: "var(--stake-bg-hover)",
              borderColor: "var(--stake-border-accent)"
            }}
          />
        </HStack>
      </Box>

      {/* Employees Table */}
      <Card className="stake-card" overflow="hidden">
        <CardHeader pb="4">
          <HStack justify="space-between">
            <Heading  className="stake-heading-3">
              قائمة الموظفين ({filteredEmployees.length})
            </Heading>
            <HStack spacing="2">
              <Tooltip 
                label={showAllContent ? "العودة للصفحات" : "عرض كل المحتوى"}
                bg="var(--stake-bg-secondary)"
                color="var(--stake-text-primary)"
                borderColor="var(--stake-border-primary)"
              >
                <IconButton
                  icon={showAllContent ? <FiMinimize /> : <FiMaximize />}
                  bg={showAllContent ? 'orange.500' : 'purple.500'}
                  color="white"
                  _hover={{ 
                    bg: showAllContent ? 'orange.600' : 'purple.600'
                  }}
                  _active={{ 
                    bg: showAllContent ? 'orange.700' : 'purple.700'
                  }}
                  border="1px solid"
                  borderColor={showAllContent ? 'orange.500' : 'purple.500'}
                  aria-label={showAllContent ? "العودة للصفحات" : "عرض كل المحتوى"}
                  onClick={() => {
                    setShowAllContent(!showAllContent);
                    if (!showAllContent) {
                      setCurrentPage(1); // إعادة تعيين الصفحة عند عرض كل المحتوى
                    }
                  }}
                />
              </Tooltip>
              <Tooltip 
                label={isFullscreen ? "خروج من ملء الشاشة" : "عرض ملء الشاشة"}
                bg="var(--stake-bg-secondary)"
                color="var(--stake-text-primary)"
                borderColor="var(--stake-border-primary)"
              >
                <IconButton
                  icon={isFullscreen ? <FiMinimize /> : <FiMaximize />}
                  variant="outline"
                  colorScheme="purple"
                  aria-label={isFullscreen ? "خروج من ملء الشاشة" : "عرض ملء الشاشة"}
                  onClick={toggleFullscreen}
                />
              </Tooltip>
            </HStack>
          </HStack>
        </CardHeader>
        
        {/* Bulk Actions for Normal Table */}
        {viewMode === 'table' && selectedEmployees.length > 0 && (
          <HStack spacing="3" p="3" bg="blue.50" borderRadius="lg" border="1px solid" borderColor="blue.200" mx="6" mb="4">
            <Text fontSize="sm" fontWeight="medium" color="blue.700">
              تم اختيار {selectedEmployees.length} موظف
            </Text>
            <HStack spacing="2">
              <Button
                bg="blue.500"
                color="white"
                _hover={{ bg: "blue.600" }}
                _active={{ bg: "blue.700" }}
                leftIcon={<FiEdit />}
                onClick={handleBulkEdit}
              >
                تعديل الكل
              </Button>
              <Button
                bg="red.500"
                color="white"
                _hover={{ bg: "red.600" }}
                _active={{ bg: "red.700" }}
                leftIcon={<FiTrash2 />}
                onClick={handleBulkDelete}
              >
                حذف الكل
              </Button>
            </HStack>
          </HStack>
        )}
        
        <CardBody pt="0">
          {viewMode === 'table' ? (
            <TableContainer className="stake-table main-content">
              <Table variant="simple"  className="stake-table main-content">
                <Thead position="sticky" top="0" zIndex="5" bg="var(--stake-bg-primary)" boxShadow="var(--stake-shadow-sm)">
                  <Tr>
                    <Th>
                      <Checkbox
                        isChecked={selectedRowKeys.length === paginatedEmployees.length && paginatedEmployees.length > 0}
                        isIndeterminate={selectedRowKeys.length > 0 && selectedRowKeys.length < paginatedEmployees.length}
                        onChange={(e) => {
                          if (e.target.checked) {
                            const allKeys = paginatedEmployees.map(emp => emp.id);
                            setSelectedRowKeys(allKeys);
                            setSelectedEmployees(paginatedEmployees);
                          } else {
                            setSelectedRowKeys([]);
                            setSelectedEmployees([]);
                          }
                        }}
                      />
                    </Th>
                    <Th cursor="pointer" onClick={() => handleSort('employee_code')}>
                      <HStack spacing="2">
                        {getSortIcon('employee_code')}
                        <EnglishKeyTooltip englishKey="employee_code">
                          رقم الموظف
                        </EnglishKeyTooltip>
                      </HStack>
                    </Th>
                    <Th cursor="pointer" onClick={() => handleSort('AC-No.')}>
                      <HStack spacing="2">
                        {getSortIcon('AC-No.')}
                        <EnglishKeyTooltip englishKey="fingerprint_code">
                          كود البصمة
                        </EnglishKeyTooltip>
                      </HStack>
                    </Th>
                    <Th>
                      <EnglishKeyTooltip englishKey="employee_name">
                        اسم الموظف
                      </EnglishKeyTooltip>
                    </Th>
                    <Th cursor="pointer" onClick={() => handleSort('base_salary')}>
                      <HStack spacing="2">
                        {getSortIcon('base_salary')}
                        <EnglishKeyTooltip englishKey="base_salary">
                          الراتب الأساسي
                        </EnglishKeyTooltip>
                      </HStack>
                    </Th>
                    <Th cursor="pointer" onClick={() => handleSort('salary_type')}>
                      <HStack spacing="2">
                        {getSortIcon('salary_type')}
                        <EnglishKeyTooltip englishKey="salary_type">
                          نوع الراتب
                        </EnglishKeyTooltip>
                      </HStack>
                    </Th>
                    <Th cursor="pointer" onClick={() => handleSort('department')}>
                      <HStack spacing="2">
                        {getSortIcon('department')}
                        <EnglishKeyTooltip englishKey="department">
                          القسم
                        </EnglishKeyTooltip>
                      </HStack>
                    </Th>
                    <Th cursor="pointer" onClick={() => handleSort('cost_center')}>
                      <HStack spacing="2">
                        {getSortIcon('cost_center')}
                        <EnglishKeyTooltip englishKey="cost_center">
                          مركز التكلفة
                        </EnglishKeyTooltip>
                      </HStack>
                    </Th>
                    <Th cursor="pointer" onClick={() => handleSort('position')}>
                      <HStack spacing="2">
                        {getSortIcon('position')}
                        <EnglishKeyTooltip englishKey="position">
                          المنصب
                        </EnglishKeyTooltip>
                      </HStack>
                    </Th>
                    <Th>
                      <EnglishKeyTooltip englishKey="location">
                        الموقع
                      </EnglishKeyTooltip>
                    </Th>
                  </Tr>
                </Thead>
                <Tbody>
                  {paginatedEmployees.map((employee) => (
                    <Tr 
                      key={employee.id}
                      onDoubleClick={() => handleViewEmployee(employee)}
                      cursor="pointer"
                      _hover={{ bg: "var(--stake-bg-hover)" }}
                    >
                      <Td>
                        <Checkbox
                          isChecked={selectedRowKeys.includes(employee.id)}
                          onChange={(e) => {
                            if (e.target.checked) {
                              setSelectedRowKeys([...selectedRowKeys, employee.id]);
                              setSelectedEmployees([...selectedEmployees, employee]);
                            } else {
                              setSelectedRowKeys(selectedRowKeys.filter(key => key !== employee.id));
                              setSelectedEmployees(selectedEmployees.filter(emp => emp.id !== employee.id));
                            }
                          }}
                        />
                      </Td>
                      <Td>
                        <Text fontWeight="semibold" color="blue.600" fontFamily="mono">
                          {employee.employee_code}
                        </Text>
                      </Td>
                      <Td>
                        <Text fontWeight="semibold" color="green.600" fontFamily="mono">
                          {employee['AC-No.'] || '-'}
                        </Text>
                      </Td>
                      <Td>
                        <VStack align="flex-start" spacing="1">
                          <Text fontWeight="semibold" color="gray.800">
                            {employee.name_ar || employee.name}
                          </Text>
                          <Text fontSize="xs" color="gray.500">
                            {employee.name}
                          </Text>
                        </VStack>
                      </Td>
                      <Td>
                        <Text fontWeight="semibold" color="green.600">
                          {formatCurrency(employee.base_salary || 0)}
                        </Text>
                      </Td>
                      <Td>
                        <Badge
                          colorScheme={employee.salary_type === 'Monthly' ? 'blue' : 'purple'}
                          variant="subtle"
                          borderRadius="full"
                          px="3"
                          py="1"
                        >
                          {employee.salary_type === 'Monthly' ? 'شهري' : 'أسبوعي'}
                        </Badge>
                      </Td>
                      <Td>
                        <Badge colorScheme="purple" variant="subtle" borderRadius="full" px="3" py="1">
                          {employee.department_description || employee.department || '-'}
                        </Badge>
                      </Td>
                      <Td>
                        <Text fontSize="sm" color="gray.600">
                          {employee.cost_center || '-'}
                        </Text>
                      </Td>
                      <Td>
                        <Text fontSize="sm" color="gray.700">
                          {employee.position || '-'}
                        </Text>
                      </Td>
                      <Td>
                        <Badge
                          colorScheme={employee.location === 'برج العرب' ? 'blue' : 'green'}
                          variant="subtle"
                          borderRadius="full"
                          px="3"
                          py="1"
                        >
                          {employee.location || '-'}
                        </Badge>
                      </Td>
                    </Tr>
                  ))}
                </Tbody>
              </Table>
            </TableContainer>
          ) : (
            <SimpleGrid columns={{ base: 1, md: 2, lg: 3, xl: 4 }} spacing="6">
              {filteredEmployees.map((employee) => (
                <Card 
                  key={employee.id} 
                  bg="white" 
                  border="1px solid" 
                  borderColor="gray.200" 
                  borderRadius="xl" 
                  overflow="hidden"
                  onDoubleClick={() => handleViewEmployeeClick(employee)}
                  cursor="pointer"
                  _hover={{ 
                    transform: "translateY(-2px)",
                    boxShadow: "lg",
                    borderColor: "blue.300"
                  }}
                  transition="all 0.2s ease"
                >
                  <CardBody p="6">
                    <VStack spacing="4" align="stretch">
                      {/* Header with Avatar */}
                      <HStack justify="space-between" align="flex-start">
                        <Avatar  name={employee.name_ar} bg="blue.500" />
                      </HStack>
                      
                      {/* Employee Info */}
                      <VStack spacing="2" align="stretch">
                        <VStack spacing="1" align="flex-start">
                          <Text fontWeight="bold" fontSize="lg" color="gray.800">
                            {employee.name_ar}
                          </Text>
                          <Text fontSize="sm" color="gray.500">
                            {employee.name}
                          </Text>
                          <Text fontSize="xs" color="blue.600" fontFamily="mono" fontWeight="semibold">
                            #{employee.employee_code}
                          </Text>
                        </VStack>
                        
                        <Divider />
                        
                        <VStack spacing="2" align="stretch">
                          <HStack justify="space-between">
                            <Text fontSize="sm" color="gray.600">الراتب:</Text>
                            <Text fontWeight="semibold" color="green.600">
                              {formatCurrency(employee.base_salary || 0)}
                            </Text>
                          </HStack>
                          <HStack justify="space-between">
                            <Text fontSize="sm" color="gray.600">النوع:</Text>
                            <Badge
                              colorScheme={employee.salary_type === 'Monthly' ? 'blue' : 'green'}
                              variant="subtle"
                            >
                              {employee.salary_type}
                            </Badge>
                          </HStack>
                          <HStack justify="space-between">
                            <Text fontSize="sm" color="gray.600">القسم:</Text>
                            <Text fontSize="sm" color="gray.700">{employee.department_description || employee.department || '-'}</Text>
                          </HStack>
                          <HStack justify="space-between">
                            <Text fontSize="sm" color="gray.600">المنصب:</Text>
                            <Text fontSize="sm" color="gray.700">{employee.position || '-'}</Text>
                          </HStack>
                        </VStack>
                      </VStack>
                      
                      {/* Actions */}
                      <HStack spacing="2" justify="center">
                        <Tooltip 
                          label="عرض التفاصيل"
                          bg="var(--stake-bg-secondary)"
                          color="var(--stake-text-primary)"
                          borderColor="var(--stake-border-primary)"
                        >
                          <IconButton
                            icon={<FiEye />}
                            variant="outline"
                            colorScheme="blue"
                            onClick={() => handleViewEmployee(employee)}
                          />
                        </Tooltip>
                        <Tooltip 
                          label="تعديل"
                          bg="var(--stake-bg-secondary)"
                          color="var(--stake-text-primary)"
                          borderColor="var(--stake-border-primary)"
                        >
                          <IconButton
                            icon={<FiEdit />}
                            variant="outline"
                            colorScheme="green"
                            onClick={() => handleEditEmployeeClick(employee)}
                          />
                        </Tooltip>
                        <Tooltip 
                          label="حساب الراتب"
                          bg="var(--stake-bg-secondary)"
                          color="var(--stake-text-primary)"
                          borderColor="var(--stake-border-primary)"
                        >
                          <IconButton
                            icon={<FiPercent />}
                            variant="outline"
                            colorScheme="purple"
                            onClick={() => handleCalculateSalary(employee)}
                          />
                        </Tooltip>
                        <Tooltip 
                          label="حذف"
                          bg="var(--stake-bg-secondary)"
                          color="var(--stake-text-primary)"
                          borderColor="var(--stake-border-primary)"
                        >
                          <IconButton
                            icon={<FiTrash2 />}
                            variant="outline"
                            colorScheme="red"
                            onClick={() => handleDeleteEmployee(employee)}
                          />
                        </Tooltip>
                      </HStack>
                    </VStack>
                  </CardBody>
                </Card>
              ))}
            </SimpleGrid>
          )}
        </CardBody>
        
        {/* Pagination for Normal View */}
        {totalPages > 1 && !showAllContent && (
          <Box p="4" borderTop="1px" borderColor="gray.200">
            <HStack justify="space-between" align="center">
              <Text fontSize="sm" color="gray.600">
                عرض {filteredEmployees.length} من أصل {employees.length} موظف
              </Text>
              <HStack spacing="2">
                <Button
                  variant="outline"
                  onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
                  isDisabled={currentPage === 1}
                >
                  السابق
                </Button>
                <Text fontSize="sm" color="gray.600">
                  صفحة {currentPage} من {totalPages}
                </Text>
                <Button
                  variant="outline"
                  onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
                  isDisabled={currentPage === totalPages}
                >
                  التالي
                </Button>
              </HStack>
            </HStack>
          </Box>
        )}
      </Card>

      {/* Add Employee Modal */}
      <Modal isOpen={isAddOpen} onClose={onAddClose} size="4xl" isCentered>
        <ModalOverlay bg="rgba(0, 0, 0, 0.7)" backdropFilter="blur(8px)" />
        <ModalContent bg="var(--stake-bg-primary)" border="none" borderRadius="3xl" boxShadow="0 25px 50px -12px rgba(0, 0, 0, 0.25)" overflow="hidden">
          <ModalHeader
            bg="var(--stake-bg-primary, #0f212e)"
            color="white"
            borderRadius="24px 24px 0 0"
            p="4"
            position="relative"
            boxShadow="0 4px 20px rgba(0, 0, 0, 0.4)"
          >
            <HStack justify="space-between" align="center" w="full">
              <Text fontSize="lg" fontWeight="bold">
                إضافة موظف جديد
              </Text>
              
              <HStack spacing="6" align="center" flex="1" justify="center">
                <HStack spacing="2">
                  <Icon as={FiUser} color="blue.300" boxSize="4" />
                  <Text fontSize="sm" className="stake-text-secondary">
                    موظف جديد
                  </Text>
                </HStack>
                <HStack spacing="2">
                  <Icon as={FiHash} color="green.300" boxSize="4" />
                  <Text fontSize="sm" className="stake-text-secondary">سيتم إنشاء كود تلقائياً</Text>
                </HStack>
                <HStack spacing="2">
                  <Icon as={FiBriefcase} color="purple.300" boxSize="4" />
                  <Text fontSize="sm" className="stake-text-secondary">
                    سيتم تحديده لاحقاً
                  </Text>
                </HStack>

              </HStack>
              
              <Box w="40px"></Box>
              <ModalCloseButton 
                color="white"
                bg="rgba(255, 255, 255, 0.1)"
                borderRadius="full"
                _hover={{
                  bg: "rgba(255, 255, 255, 0.2)"
                }}
                _active={{
                  transform: "scale(0.95)"
                }}
              />
            </HStack>
          </ModalHeader>
          <ModalBody p="8">
            <form onSubmit={handleSubmit(handleAddEmployee)}>
              <VStack spacing="6" align="stretch">
                {/* المعلومات الأساسية */}
                <Box>
                  <Text fontSize="lg" fontWeight="bold" mb="4" color="var(--stake-text-primary)">
                    المعلومات الأساسية
                  </Text>
                  <Grid templateColumns={{ base: "1fr", md: "2fr 2fr 1fr 1fr 1fr" }} gap="4">
                    <GridItem>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl isRequired>
                          <FormLabel className="stake-label">الاسم بالإنجليزية</FormLabel>
                          <Input
                            {...register('name', { required: 'الاسم بالإنجليزية مطلوب' })}
                            placeholder="Employee Name"
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          />
                          <FormErrorMessage>
                            {errors.name && errors.name.message}
                          </FormErrorMessage>
                        </FormControl>
                      </Box>
                    </GridItem>
                    <GridItem>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl>
                          <FormLabel className="stake-label">الاسم بالعربية</FormLabel>
                          <Input
                            {...register('name_ar')}
                            placeholder="اسم الموظف بالعربية"
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          />
                        </FormControl>
                      </Box>
                    </GridItem>
                    <GridItem>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl>
                          <FormLabel className="stake-label">كود البصمة</FormLabel>
                          <Input
                            {...register('ac_no')}
                            placeholder="AC-No."
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          />
                        </FormControl>
                      </Box>
                    </GridItem>
                    <GridItem>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl isRequired>
                          <FormLabel className="stake-label">كود الموظف</FormLabel>
                          <InputGroup>
                            <Input
                              {...register('employee_code', { required: 'كود الموظف مطلوب' })}
                              placeholder=""
                              className="stake-input"
                              bg="var(--stake-bg-secondary, #182935)"
                              borderColor="var(--stake-border-primary, #2f4553)"
                              color="white"
                              pr="12"
                              _focus={{
                                borderColor: "#3b82f6",
                                boxShadow: "0 0 0 1px #3b82f6"
                              }}
                              _hover={{
                                borderColor: "#4a5568"
                              }}
                            />
                            <InputRightElement width="4.5rem">
                              <IconButton
                                aria-label="توليد كود الموظف"
                                icon={<FiRefreshCw />}
                                variant="ghost"
                                color="blue.400"
                                _hover={{
                                  color: "blue.300",
                                  bg: "rgba(59, 130, 246, 0.1)"
                                }}
                                onClick={async () => {
                                  try {
                                    const response = await fetch(getApiUrl('/api/unified_employees_api.php?action=generate_employee_code'));
                                    const data = await response.json();
                                    if (data.success) {
                                      setValue('employee_code', data.employee_code);
                                      await trigger('employee_code');
                                      toast({
                                        title: 'تم توليد كود الموظف',
                                        description: `الكود الجديد: ${data.employee_code}`,
                                        status: 'success',
                                        duration: 3000,
                                        isClosable: true,
                                      });
                                    }
                                  } catch (error) {
                                    toast({
                                      title: 'خطأ في توليد الكود',
                                      description: error.message,
                                      status: 'error',
                                      duration: 5000,
                                      isClosable: true,
                                    });
                                  }
                                }}
                              />
                            </InputRightElement>
                          </InputGroup>
                          <FormErrorMessage>
                            {errors.employee_code && errors.employee_code.message}
                          </FormErrorMessage>
                        </FormControl>
                      </Box>
                    </GridItem>
                    <GridItem>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl isRequired>
                          <FormLabel className="stake-label">الراتب الأساسي</FormLabel>
                          <Input
                            type="number"
                            {...register('base_salary', { required: 'الراتب الأساسي مطلوب' })}
                            placeholder="0"
                            defaultValue={0}
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          />
                          <FormErrorMessage>
                            {errors.base_salary && errors.base_salary.message}
                          </FormErrorMessage>
                        </FormControl>
                      </Box>
                    </GridItem>
                  </Grid>
                </Box>

                {/* معلومات العمل */}
                <Box>
                  <Text fontSize="lg" fontWeight="bold" mb="4" color="var(--stake-text-primary)">
                    معلومات العمل
                  </Text>
                  {watch('salary_type') === 'Monthly' ? (
                    <SimpleGrid columns={{ base: 1, md: 3 }} spacing="4">
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl isRequired>
                          <FormLabel className="stake-label">نوع الراتب</FormLabel>
                          <Select
                            {...register('salary_type', { required: 'نوع الراتب مطلوب' })}
                            placeholder="اختر نوع الراتب"
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          >
<option value="Monthly" style={{background: '#1a2c38', color: 'white'}}>شهري</option>
                                <option value="Weekly" style={{background: '#1a2c38', color: 'white'}}>أسبوعي</option>
                          </Select>
                          <FormErrorMessage>
                            {errors.salary_type && errors.salary_type.message}
                          </FormErrorMessage>
                        </FormControl>
                      </Box>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl>
                          <FormLabel className="stake-label">القسم</FormLabel>
                          <Select
                            {...register('department')}
                            placeholder="اختر القسم"
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          >
                            {departments.map(dept => (
                              <option key={dept.id} value={dept.name}>{dept.description || dept.name}</option>
                            ))}
                          </Select>
                        </FormControl>
                      </Box>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl>
                          <FormLabel className="stake-label">المنصب</FormLabel>
                          <Input
                            {...register('position')}
                            placeholder="المنصب"
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          />
                        </FormControl>
                      </Box>
                    </SimpleGrid>
                  ) : (
                    <SimpleGrid columns={{ base: 1, md: 4 }} spacing="4">
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl isRequired>
                          <FormLabel className="stake-label">نوع الراتب</FormLabel>
                          <Select
                            {...register('salary_type', { required: 'نوع الراتب مطلوب' })}
                            placeholder="اختر نوع الراتب"
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          >
<option value="Monthly" style={{background: '#1a2c38', color: 'white'}}>شهري</option>
                                <option value="Weekly" style={{background: '#1a2c38', color: 'white'}}>أسبوعي</option>
                          </Select>
                          <FormErrorMessage>
                            {errors.salary_type && errors.salary_type.message}
                          </FormErrorMessage>
                        </FormControl>
                      </Box>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl>
                          <FormLabel className="stake-label">القسم</FormLabel>
                          <Select
                            {...register('department')}
                            placeholder="اختر القسم"
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          >
                            {departments.map(dept => (
                              <option key={dept.id} value={dept.name}>{dept.description || dept.name}</option>
                            ))}
                          </Select>
                        </FormControl>
                      </Box>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl>
                          <FormLabel className="stake-label">مركز التكلفة</FormLabel>
                          <Controller
                            name="cost_center"
                            control={control}
                            render={({ field }) => (
                              <Select
                                {...field}
                                placeholder={watch('department') ? "اختر مركز التكلفة" : "اختر القسم أولاً"}
                                className="stake-input"
                                bg="var(--stake-bg-secondary, #182935)"
                                borderColor="var(--stake-border-primary, #2f4553)"
                                color="white"
                                isDisabled={!watch('department')}
                                _focus={{
                                  borderColor: "#3b82f6",
                                  boxShadow: "0 0 0 1px #3b82f6"
                                }}
                                _hover={{
                                  borderColor: "#4a5568"
                                }}
                              >
                                {(watch('department') && departmentCostCenters.length > 0 ? departmentCostCenters : []).map(center => (
                                  <option key={center.id} value={center.name}>{center.name}</option>
                                ))}
                              </Select>
                            )}
                          />
                          {!watch('department') && (
                            <Text fontSize="sm" color="orange.300" mt="1">
                              يجب اختيار القسم أولاً لعرض مراكز التكلفة
                            </Text>
                          )}
                        </FormControl>
                      </Box>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl>
                          <FormLabel className="stake-label">المنصب</FormLabel>
                          <Input
                            {...register('position')}
                            placeholder="المنصب"
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          />
                        </FormControl>
                      </Box>
                    </SimpleGrid>
                  )}
                </Box>

                {/* معلومات إضافية */}
                <Box>
                  <Text fontSize="lg" fontWeight="bold" mb="4" color="var(--stake-text-primary)">
                    معلومات إضافية
                  </Text>
                  <SimpleGrid columns={{ base: 1, md: 3 }} spacing="4">
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <FormControl>
                        <FormLabel className="stake-label">الموقع</FormLabel>
                        <Select
                          {...register('location')}
                          placeholder="اختر الموقع"
                          className="stake-input"
                          bg="var(--stake-bg-secondary, #182935)"
                          borderColor="var(--stake-border-primary, #2f4553)"
                          color="white"
                          _focus={{
                            borderColor: "#3b82f6",
                            boxShadow: "0 0 0 1px #3b82f6"
                          }}
                          _hover={{
                            borderColor: "#4a5568"
                          }}
                        >
                          <option value="برج العرب" style={{background: '#1a2c38', color: 'white'}}>برج العرب</option>
                          <option value="محرم بك" style={{background: '#1a2c38', color: 'white'}}>محرم بك</option>
                        </Select>
                      </FormControl>
                    </Box>
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <FormControl>
                        <FormLabel className="stake-label">تاريخ التعيين</FormLabel>
                        <Input
                          {...register('hire_date')}
                          type="date"
                          defaultValue={new Date().toISOString().split('T')[0]}
                          className="stake-input"
                          bg="var(--stake-bg-secondary, #182935)"
                          borderColor="var(--stake-border-primary, #2f4553)"
                          color="white"
                          _focus={{
                            borderColor: "#3b82f6",
                            boxShadow: "0 0 0 1px #3b82f6"
                          }}
                          _hover={{
                            borderColor: "#4a5568"
                          }}
                        />
                      </FormControl>
                    </Box>
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <FormControl>
                        <FormLabel className="stake-label">الحالة</FormLabel>
                        <Select
                          {...register('status')}
                          placeholder="اختر الحالة"
                          className="stake-input"
                          bg="var(--stake-bg-secondary, #182935)"
                          borderColor="var(--stake-border-primary, #2f4553)"
                          color="white"
                          _focus={{
                            borderColor: "#3b82f6",
                            boxShadow: "0 0 0 1px #3b82f6"
                          }}
                          _hover={{
                            borderColor: "#4a5568"
                          }}
                        >
                          <option value="active" style={{background: '#1a2c38', color: 'white'}}>نشط</option>
                          <option value="inactive" style={{background: '#1a2c38', color: 'white'}}>غير نشط</option>
                          <option value="terminated" style={{background: '#1a2c38', color: 'white'}}>منتهي الخدمة</option>
                        </Select>
                      </FormControl>
                    </Box>
                  </SimpleGrid>
                </Box>

              </VStack>
            </form>
          </ModalBody>
          <ModalFooter 
            justifyContent="space-between"
            gap="4"
            bg="var(--stake-bg-primary, #0f212e)"
            borderTop="1px solid"
            borderColor="var(--stake-border-primary, #2f4553)"
            borderRadius="0 0 24px 24px"
            p="6"
            boxShadow="0 -4px 20px rgba(0, 0, 0, 0.4)"
          >
            <HStack spacing="4" align="center">
              <Checkbox
                {...register('is_insured')}
                defaultChecked={false}
                colorScheme="blue"
                onChange={(e) => {
                  setValue('is_insured', e.target.checked);
                }}
              >
                <Text color="#d5dceb" fontWeight="medium">
                  مؤمن عليه
                </Text>
              </Checkbox>
            </HStack>
            <HStack spacing="3">
              <Button 
                onClick={onAddClose}
                h="48px"
                px="8"
                fontWeight="600"
                borderRadius="xl"
                bg="var(--stake-bg-secondary, #182935)"
                color="#d5dceb"
                border="1px solid"
                borderColor="var(--stake-border-primary, #2f4553)"
                _hover={{
                  bg: "#213743",
                  borderColor: "#3b82f6"
                }}
              >
                إلغاء
              </Button>
              <Button
                leftIcon={<FiSave />}
                h="48px"
                px="8"
                fontWeight="600"
                borderRadius="xl"
                bg="#3b82f6"
                color="white"
                _hover={{
                  bg: "#2563eb"
                }}
                onClick={handleSubmit(handleAddEmployee)}
              >
                إضافة الموظف
              </Button>
            </HStack>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* View Employee Modal */}
      <Modal isOpen={isViewOpen} onClose={onViewClose} size="4xl" isCentered>
        <ModalOverlay bg="rgba(0, 0, 0, 0.7)" backdropFilter="blur(8px)" />
        <ModalContent bg="var(--stake-bg-primary)" border="none" borderRadius="3xl" boxShadow="0 25px 50px -12px rgba(0, 0, 0, 0.25)" overflow="hidden">
          <ModalHeader
            bg="var(--stake-bg-primary, #0f212e)"
            color="white"
            borderRadius="24px 24px 0 0"
            p="4"
            position="relative"
          >
            <HStack justify="space-between" align="center" w="full">
              <Text fontSize="lg" fontWeight="bold">
                تفاصيل الموظف
              </Text>
              
              <HStack spacing="6" align="center" flex="1" justify="center">
                <HStack spacing="2">
                  <Icon as={FiUser} color="blue.300" boxSize="4" />
                  <Text fontSize="sm" className="stake-text-secondary">
                    {selectedEmployee?.name_ar || selectedEmployee?.name || 'غير محدد'}
                  </Text>
                </HStack>
                <HStack spacing="2">
                  <Icon as={FiHash} color="green.300" boxSize="4" />
                  <Text fontSize="sm" className="stake-text-secondary">{selectedEmployee?.employee_code || '-'}</Text>
                </HStack>
                <HStack spacing="2">
                  <Icon as={FiKey} color="orange.300" boxSize="4" />
                  <Text fontSize="sm" className="stake-text-secondary">{selectedEmployee?.['AC-No.'] || '-'}</Text>
                </HStack>
                {selectedEmployee?.salary_type === 'Monthly' ? (
                  <HStack spacing="2">
                    <Icon as={FiBriefcase} color="purple.300" boxSize="4" />
                    <Text fontSize="sm" className="stake-text-secondary">
                      {selectedEmployee?.department_description || selectedEmployee?.department || '-'}
                    </Text>
                  </HStack>
                ) : (
                  <HStack spacing="2">
                    <Icon as={FiTarget} color="blue.300" boxSize="4" />
                    <Text fontSize="sm" className="stake-text-secondary">
                      {selectedEmployee?.cost_center || '-'}
                    </Text>
                  </HStack>
                )}
                <HStack spacing="2">
                  <Icon as={FiDollarSign} color="orange.300" boxSize="4" />
                  <Badge 
                    colorScheme={selectedEmployee?.salary_type === 'Monthly' ? 'purple' : 'blue'}
                    variant="solid"
                    px="2"
                    py="1"
                    borderRadius="md"
                    fontSize="xs"
                  >
                    {selectedEmployee?.salary_type === 'Monthly' ? 'شهري' : 'أسبوعي'}
                  </Badge>
                </HStack>
              </HStack>
              
              <Box w="40px"></Box>
              <ModalCloseButton 
                color="white"
                bg="rgba(255, 255, 255, 0.1)"
                borderRadius="full"
                _hover={{
                  bg: "rgba(255, 255, 255, 0.2)"
                }}
                _active={{
                  transform: "scale(0.95)"
                }}
              />
            </HStack>
          </ModalHeader>
          <ModalBody p="8">
            {selectedEmployee && (
              <VStack spacing="6" align="stretch">
                {/* معلومات الراتب */}
                <Box>
                  <Text fontSize="lg" fontWeight="bold" mb="4" color="var(--stake-text-primary)">
                    معلومات الراتب
                  </Text>
                  <SimpleGrid columns={{ base: 1, md: 3 }} spacing="4">
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <VStack align="flex-start" spacing="2">
                        <Text fontSize="sm" color="var(--stake-text-secondary)" fontWeight="medium">
                          الراتب الأساسي
                        </Text>
                        <Text fontSize="md" fontWeight="bold" color="green.400">
                          {formatCurrency(selectedEmployee.base_salary || 0)}
                        </Text>
                      </VStack>
                    </Box>
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <VStack align="flex-start" spacing="2">
                        <Text fontSize="sm" color="var(--stake-text-secondary)" fontWeight="medium">
                          نوع الراتب
                        </Text>
                        <Badge
                          colorScheme={selectedEmployee.salary_type === 'Monthly' ? 'purple' : 'blue'}
                          variant="solid"
                          px="3"
                          py="1"
                          borderRadius="md"
                        >
                          {selectedEmployee.salary_type === 'Monthly' ? 'شهري' : 'أسبوعي'}
                        </Badge>
                      </VStack>
                    </Box>
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <VStack align="flex-start" spacing="2">
                        <Text fontSize="sm" color="var(--stake-text-secondary)" fontWeight="medium">
                          مؤمن عليه
                        </Text>
                        <Badge
                          colorScheme={selectedEmployee.is_insured ? 'green' : 'red'}
                          variant="solid"
                          px="3"
                          py="1"
                          borderRadius="md"
                        >
                          {selectedEmployee.is_insured ? 'نعم' : 'لا'}
                        </Badge>
                      </VStack>
                    </Box>
                  </SimpleGrid>
                </Box>

                {/* معلومات العمل */}
                <Box>
                  <Text fontSize="lg" fontWeight="bold" mb="4" color="var(--stake-text-primary)">
                    معلومات العمل
                  </Text>
                  <SimpleGrid columns={{ base: 1, md: 3 }} spacing="4">
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <VStack align="flex-start" spacing="2">
                        <Text fontSize="sm" color="var(--stake-text-secondary)" fontWeight="medium">
                          القسم
                        </Text>
                        <Text fontSize="md" fontWeight="bold" color="var(--stake-text-primary)">
                          {selectedEmployee.department_description || selectedEmployee.department || '-'}
                        </Text>
                      </VStack>
                    </Box>
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <VStack align="flex-start" spacing="2">
                        <Text fontSize="sm" color="var(--stake-text-secondary)" fontWeight="medium">
                          مركز التكلفة
                        </Text>
                        <Text fontSize="md" fontWeight="bold" color="var(--stake-text-primary)">
                          {selectedEmployee.cost_center || '-'}
                        </Text>
                      </VStack>
                    </Box>
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <VStack align="flex-start" spacing="2">
                        <Text fontSize="sm" color="var(--stake-text-secondary)" fontWeight="medium">
                          المنصب
                        </Text>
                        <Text fontSize="md" fontWeight="bold" color="var(--stake-text-primary)">
                          {selectedEmployee.position || '-'}
                        </Text>
                      </VStack>
                    </Box>
                  </SimpleGrid>
                </Box>

                {/* معلومات إضافية */}
                <Box>
                  <Text fontSize="lg" fontWeight="bold" mb="4" color="var(--stake-text-primary)">
                    معلومات إضافية
                  </Text>
                  <SimpleGrid columns={{ base: 1, md: 3 }} spacing="4">
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <VStack align="flex-start" spacing="2">
                        <Text fontSize="sm" color="var(--stake-text-secondary)" fontWeight="medium">
                          الموقع
                        </Text>
                        <Text fontSize="md" fontWeight="bold" color="var(--stake-text-primary)">
                          {selectedEmployee.location || '-'}
                        </Text>
                      </VStack>
                    </Box>
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <VStack align="flex-start" spacing="2">
                        <Text fontSize="sm" color="var(--stake-text-secondary)" fontWeight="medium">
                          تاريخ التعيين
                        </Text>
                        <Text fontSize="md" fontWeight="bold" color="var(--stake-text-primary)">
                          {selectedEmployee.hire_date ? new Date(selectedEmployee.hire_date).toLocaleDateString('ar-EG') : '-'}
                        </Text>
                      </VStack>
                    </Box>
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <VStack align="flex-start" spacing="2">
                        <Text fontSize="sm" color="var(--stake-text-secondary)" fontWeight="medium">
                          الحالة
                        </Text>
                        <Badge
                          colorScheme={selectedEmployee.status === 'active' ? 'green' : 'red'}
                          variant="solid"
                          px="3"
                          py="1"
                          borderRadius="md"
                        >
                          {selectedEmployee.status === 'active' ? 'نشط' : 'غير نشط'}
                        </Badge>
                      </VStack>
                    </Box>
                  </SimpleGrid>
                </Box>
              </VStack>
            )}
          </ModalBody>
          <ModalFooter 
            justifyContent="center" // Center content horizontally
            gap="4"
            bg="var(--stake-bg-primary, #0f212e)"
            borderTop="1px solid"
            borderColor="var(--stake-border-primary, #2f4553)"
            borderRadius="0 0 24px 24px"
            p="6"
            boxShadow="0 -4px 20px rgba(0, 0, 0, 0.4)"
          >
            <HStack spacing="3">
              <Button
                leftIcon={<FiEdit />}
                h="48px"
                px="8"
                fontWeight="600"
                borderRadius="xl"
                bg="#3b82f6"
                color="white"
                _hover={{ bg: "#2563eb" }}
                onClick={() => {
                  onViewClose();
                  onEditOpen();
                }}
              >
                تعديل البيانات
              </Button>
              <Button
                leftIcon={<FiTrash2 />}
                h="48px"
                px="8"
                fontWeight="600"
                borderRadius="xl"
                bg="#dc2626"
                color="white"
                _hover={{ bg: "#b91c1c" }}
                onClick={() => {
                  const employeeName = selectedEmployee?.name_ar || selectedEmployee?.name || 'هذا الموظف';
                  const confirmMessage = `⚠️ تحذير: حذف الموظف نهائياً\n\nالموظف: ${employeeName}\nالكود: ${selectedEmployee?.employee_code || 'غير محدد'}\n\nهذا الإجراء سيحذف:\n• بيانات الموظف من قاعدة البيانات\n• جميع سجلات الحضور والانصراف\n• جميع البيانات المرتبطة بالموظف\n\n⚠️ لا يمكن التراجع عن هذا الإجراء!\n\nهل أنت متأكد من المتابعة؟`;

                  if (window.confirm(confirmMessage)) {
                    handleDeleteEmployee(selectedEmployee);
                    onViewClose();
                  }
                }}
              >
                حذف الموظف
              </Button>
            </HStack>
          </ModalFooter>

        </ModalContent>
      </Modal>

      {/* Edit Employee Modal - unified format to match new design */}
      <Modal isOpen={isEditOpen} onClose={handleEditClose} size="4xl" isCentered>
        <ModalOverlay bg="rgba(0, 0, 0, 0.7)" backdropFilter="blur(8px)" />
        <ModalContent bg="var(--stake-bg-primary)" border="none" borderRadius="3xl" boxShadow="0 25px 50px -12px rgba(0, 0, 0, 0.25)" overflow="hidden">
          <ModalHeader
            bg="var(--stake-bg-primary, #0f212e)"
            color="white"
            borderRadius="24px 24px 0 0"
            p="4"
            position="relative"
            boxShadow="0 4px 20px rgba(0, 0, 0, 0.4)"
          >
            <HStack justify="space-between" align="center" w="full">
              <Text fontSize="lg" fontWeight="bold">
                تعديل بيانات الموظف
              </Text>
              
              <HStack spacing="6" align="center" flex="1" justify="center">
                <HStack spacing="2">
                  <Icon as={FiUser} color="blue.300" boxSize="4" />
                  <Text fontSize="sm" className="stake-text-secondary">
                    {selectedEmployee?.name_ar || selectedEmployee?.name || 'غير محدد'}
                  </Text>
                </HStack>
                <HStack spacing="2">
                  <Icon as={FiHash} color="green.300" boxSize="4" />
                  <Text fontSize="sm" className="stake-text-secondary">{selectedEmployee?.employee_code || '-'}</Text>
                </HStack>
                <HStack spacing="2">
                  <Icon as={FiKey} color="orange.300" boxSize="4" />
                  <Text fontSize="sm" className="stake-text-secondary">{selectedEmployee?.['AC-No.'] || '-'}</Text>
                </HStack>
                <HStack spacing="2">
                  <Icon as={FiBriefcase} color="purple.300" boxSize="4" />
                  <Text fontSize="sm" className="stake-text-secondary">
                    {selectedEmployee?.department_description || selectedEmployee?.department || '-'}
                  </Text>
                </HStack>
                <HStack spacing="2">
                  <Icon as={FiDollarSign} color="orange.300" boxSize="4" />
                  <Badge 
                    colorScheme={selectedEmployee?.salary_type === 'Monthly' ? 'purple' : 'blue'}
                    variant="solid"
                    px="2"
                    py="1"
                    borderRadius="md"
                    fontSize="xs"
                  >
                    {selectedEmployee?.salary_type === 'Monthly' ? 'شهري' : 'أسبوعي'}
                  </Badge>
                </HStack>
              </HStack>
              
              <Box w="40px"></Box>
              <ModalCloseButton 
                color="white"
                bg="rgba(255, 255, 255, 0.1)"
                borderRadius="full"
                _hover={{
                  bg: "rgba(255, 255, 255, 0.2)"
                }}
                _active={{
                  transform: "scale(0.95)"
                }}
              />
            </HStack>
          </ModalHeader>
          <ModalBody p="8">
            <form onSubmit={handleSubmit(handleEditEmployee)}>
              <VStack spacing="6" align="stretch">
                {/* المعلومات الأساسية */}
                <Box>
                  <Text fontSize="lg" fontWeight="bold" mb="4" color="var(--stake-text-primary)">
                    المعلومات الأساسية
                  </Text>
                  <VStack spacing="4" align="stretch">
                    {/* الصف الأول: الأسماء */}
                    <SimpleGrid columns={{ base: 1, md: 2 }} spacing="4">
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl isRequired>
                          <FormLabel className="stake-label">الاسم بالإنجليزية</FormLabel>
                          <Input
                            {...register('name', { required: 'الاسم بالإنجليزية مطلوب' })}
                            placeholder="Employee Name"
                            defaultValue={selectedEmployee?.name || ''}
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          />
                          <FormErrorMessage>
                            {errors.name && errors.name.message}
                          </FormErrorMessage>
                        </FormControl>
                      </Box>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl>
                          <FormLabel className="stake-label">الاسم بالعربية</FormLabel>
                          <Input
                            {...register('name_ar')}
                            placeholder="اسم الموظف بالعربية"
                            defaultValue={selectedEmployee?.name_ar || ''}
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          />
                        </FormControl>
                      </Box>
                    </SimpleGrid>
                    
                    {/* الصف الثاني: الأكواد والراتب */}
                    <SimpleGrid columns={{ base: 1, md: 3 }} spacing="4">
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl isRequired>
                          <FormLabel className="stake-label">كود الموظف</FormLabel>
                          <Input
                            {...register('employee_code', { required: 'كود الموظف مطلوب' })}
                            placeholder="كود الموظف"
                            defaultValue={selectedEmployee?.employee_code || ''}
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          />
                          <FormErrorMessage>
                            {errors.employee_code && errors.employee_code.message}
                          </FormErrorMessage>
                        </FormControl>
                      </Box>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl>
                          <FormLabel className="stake-label">كود البصمة</FormLabel>
                          <Input
                            {...register('ac_no')}
                            placeholder="AC-No."
                            defaultValue={selectedEmployee?.['AC-No.'] || ''}
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          />
                        </FormControl>
                      </Box>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl isRequired>
                          <FormLabel className="stake-label">الراتب الأساسي</FormLabel>
                          <Input
                            type="number"
                            {...register('base_salary', { required: 'الراتب الأساسي مطلوب' })}
                            placeholder="0"
                            defaultValue={selectedEmployee?.base_salary || 0}
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          />
                          <FormErrorMessage>
                            {errors.base_salary && errors.base_salary.message}
                          </FormErrorMessage>
                        </FormControl>
                      </Box>
                    </SimpleGrid>
                  </VStack>
                </Box>


                {/* معلومات العمل */}
                <Box>
                  <Text fontSize="lg" fontWeight="bold" mb="4" color="var(--stake-text-primary)">
                    معلومات العمل
                  </Text>
                  {watchedSalaryType === 'Monthly' ? (
                    <SimpleGrid columns={{ base: 1, md: 3 }} spacing="4">
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl>
                          <FormLabel className="stake-label">نوع الراتب</FormLabel>
                          <Controller
                            name="salary_type"
                            control={control}
                            render={({ field }) => (
                              <Select
                                {...field}
                                placeholder="اختر نوع الراتب"
                                className="stake-input"
                                bg="var(--stake-bg-secondary, #182935)"
                                borderColor="var(--stake-border-primary, #2f4553)"
                                color="white"
                                sx={{
                                  option: {
                                    background: '#1a2c38',
                                    color: 'white',
                                  }
                                }}
                                _focus={{
                                  borderColor: "#3b82f6",
                                  boxShadow: "0 0 0 1px #3b82f6"
                                }}
                                _hover={{
                                  borderColor: "#4a5568"
                                }}
                              >
                                <option value="Monthly" style={{background: '#1a2c38', color: 'white'}}>شهري</option>
                                <option value="Weekly" style={{background: '#1a2c38', color: 'white'}}>أسبوعي</option>
                              </Select>
                            )}
                          />
                        </FormControl>
                      </Box>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl>
                          <FormLabel className="stake-label">القسم</FormLabel>
                          <Controller
                            name="department"
                            control={control}
                            render={({ field }) => (
                              <Select
                                {...field}
                                placeholder="اختر القسم"
                                className="stake-input"
                                bg="var(--stake-bg-secondary, #182935)"
                                borderColor="var(--stake-border-primary, #2f4553)"
                                color="white"
                                _focus={{
                                  borderColor: "#3b82f6",
                                  boxShadow: "0 0 0 1px #3b82f6"
                                }}
                                _hover={{
                                  borderColor: "#4a5568"
                                }}
                              >
                                {departments.map(dept => (
                                  <option key={dept.id} value={dept.name}>{dept.description || dept.name}</option>
                                ))}
                              </Select>
                            )}
                          />
                        </FormControl>
                      </Box>
                      <Box
                        bg="var(--stake-bg-secondary)"
                        p="4"
                        borderRadius="xl"
                        border="1px solid"
                        borderColor="var(--stake-border-primary)"
                      >
                        <FormControl>
                          <FormLabel className="stake-label">المنصب</FormLabel>
                          <Input
                            {...register('position')}
                            placeholder="المنصب"
                            defaultValue={selectedEmployee?.position || ''}
                            className="stake-input"
                            bg="var(--stake-bg-secondary, #182935)"
                            borderColor="var(--stake-border-primary, #2f4553)"
                            color="white"
                            _focus={{
                              borderColor: "#3b82f6",
                              boxShadow: "0 0 0 1px #3b82f6"
                            }}
                            _hover={{
                              borderColor: "#4a5568"
                            }}
                          />
                        </FormControl>
                      </Box>
                    </SimpleGrid>
                  ) : (
                    <VStack spacing="4" align="stretch">
                      {/* الصف الأول */}
                      <SimpleGrid columns={{ base: 1, md: 2 }} spacing="4">
                        <Box
                          bg="var(--stake-bg-secondary)"
                          p="4"
                          borderRadius="xl"
                          border="1px solid"
                          borderColor="var(--stake-border-primary)"
                        >
                          <FormControl>
                            <FormLabel className="stake-label">نوع الراتب</FormLabel>
                            <Controller
                              name="salary_type"
                              control={control}
                              render={({ field }) => (
                                <Select
                                  {...field}
                                  placeholder="اختر نوع الراتب"
                                  className="stake-input"
                                  bg="var(--stake-bg-secondary, #182935)"
                                  borderColor="var(--stake-border-primary, #2f4553)"
                                  color="white"
                                  _focus={{
                                    borderColor: "#3b82f6",
                                    boxShadow: "0 0 0 1px #3b82f6"
                                  }}
                                  _hover={{
                                    borderColor: "#4a5568"
                                  }}
                                >
<option value="Monthly" style={{background: '#1a2c38', color: 'white'}}>شهري</option>
                                <option value="Weekly" style={{background: '#1a2c38', color: 'white'}}>أسبوعي</option>
                                </Select>
                              )}
                            />
                          </FormControl>
                        </Box>
                        <Box
                          bg="var(--stake-bg-secondary)"
                          p="4"
                          borderRadius="xl"
                          border="1px solid"
                          borderColor="var(--stake-border-primary)"
                        >
                          <FormControl>
                            <FormLabel className="stake-label">القسم</FormLabel>
                            <Controller
                              name="department"
                              control={control}
                              render={({ field }) => (
                                <Select
                                  {...field}
                                  placeholder="اختر القسم"
                                  className="stake-input"
                                  bg="var(--stake-bg-secondary, #182935)"
                                  borderColor="var(--stake-border-primary, #2f4553)"
                                  color="white"
                                  _focus={{
                                    borderColor: "#3b82f6",
                                    boxShadow: "0 0 0 1px #3b82f6"
                                  }}
                                  _hover={{
                                    borderColor: "#4a5568"
                                  }}
                                >
                                  {departments.map(dept => (
                                    <option key={dept.id} value={dept.name}>{dept.description || dept.name}</option>
                                  ))}
                                </Select>
                              )}
                            />
                          </FormControl>
                        </Box>
                      </SimpleGrid>
                      
                      {/* الصف الثاني */}
                      <SimpleGrid columns={{ base: 1, md: 2 }} spacing="4">
                        <Box
                          bg="var(--stake-bg-secondary)"
                          p="4"
                          borderRadius="xl"
                          border="1px solid"
                          borderColor="var(--stake-border-primary)"
                        >
                          <FormControl>
                            <FormLabel className="stake-label">مركز التكلفة</FormLabel>
                            <Controller
                              name="cost_center"
                              control={control}
                              defaultValue={selectedEmployee?.cost_center || ''}
                              render={({ field }) => (
                                <Select
                                  {...field}
                                  placeholder={watchedDepartment ? "اختر مركز التكلفة" : "اختر القسم أولاً"}
                                  className="stake-input"
                                  bg="var(--stake-bg-secondary, #182935)"
                                  borderColor="var(--stake-border-primary, #2f4553)"
                                  color="white"
                                  isDisabled={!watchedDepartment}
                                  _focus={{
                                    borderColor: "#3b82f6",
                                    boxShadow: "0 0 0 1px #3b82f6"
                                  }}
                                  _hover={{
                                    borderColor: "#4a5568"
                                  }}
                                >
                                  {(watchedDepartment && departmentCostCenters.length > 0 ? departmentCostCenters : []).map(center => (
                                    <option key={center.id} value={center.name}>{center.name}</option>
                                  ))}
                                </Select>
                              )}
                            />
                            {!watchedDepartment && (
                              <Text fontSize="sm" color="orange.300" mt="1">
                                يجب اختيار القسم أولاً لعرض مراكز التكلفة
                              </Text>
                            )}
                          </FormControl>
                        </Box>
                        <Box
                          bg="var(--stake-bg-secondary)"
                          p="4"
                          borderRadius="xl"
                          border="1px solid"
                          borderColor="var(--stake-border-primary)"
                        >
                          <FormControl>
                            <FormLabel className="stake-label">المنصب</FormLabel>
                            <Input
                              {...register('position')}
                              placeholder="المنصب"
                              defaultValue={selectedEmployee?.position || ''}
                              className="stake-input"
                              bg="var(--stake-bg-secondary, #182935)"
                              borderColor="var(--stake-border-primary, #2f4553)"
                              color="white"
                              _focus={{
                                borderColor: "#3b82f6",
                                boxShadow: "0 0 0 1px #3b82f6"
                              }}
                              _hover={{
                                borderColor: "#4a5568"
                              }}
                            />
                          </FormControl>
                        </Box>
                      </SimpleGrid>
                    </VStack>
                  )}
                </Box>

                {/* معلومات إضافية */}
                <Box>
                  <Text fontSize="lg" fontWeight="bold" mb="4" color="var(--stake-text-primary)">
                    معلومات إضافية
                  </Text>
                  <SimpleGrid columns={{ base: 1, md: 3 }} spacing="4">
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <FormControl>
                        <FormLabel className="stake-label">الموقع</FormLabel>
                        <Select
                          {...register('location')}
                          placeholder="اختر الموقع"
                          defaultValue={selectedEmployee?.location || ''}
                          className="stake-input"
                          bg="var(--stake-bg-secondary, #182935)"
                          borderColor="var(--stake-border-primary, #2f4553)"
                          color="white"
                          _focus={{
                            borderColor: "#3b82f6",
                            boxShadow: "0 0 0 1px #3b82f6"
                          }}
                          _hover={{
                            borderColor: "#4a5568"
                          }}
                        >
                          <option value="برج العرب" style={{background: '#1a2c38', color: 'white'}}>برج العرب</option>
                          <option value="محرم بك" style={{background: '#1a2c38', color: 'white'}}>محرم بك</option>
                        </Select>
                      </FormControl>
                    </Box>
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <FormControl>
                        <FormLabel className="stake-label">تاريخ التعيين</FormLabel>
                        <Input
                          {...register('hire_date')}
                          type="date"
                          defaultValue={selectedEmployee?.hire_date || ''}
                          className="stake-input"
                          bg="var(--stake-bg-secondary, #182935)"
                          borderColor="var(--stake-border-primary, #2f4553)"
                          color="white"
                          _focus={{
                            borderColor: "#3b82f6",
                            boxShadow: "0 0 0 1px #3b82f6"
                          }}
                          _hover={{
                            borderColor: "#4a5568"
                          }}
                        />
                      </FormControl>
                    </Box>
                    <Box
                      bg="var(--stake-bg-secondary)"
                      p="4"
                      borderRadius="xl"
                      border="1px solid"
                      borderColor="var(--stake-border-primary)"
                    >
                      <FormControl>
                        <FormLabel className="stake-label">الحالة</FormLabel>
                        <Select
                          {...register('status')}
                          placeholder="اختر الحالة"
                          defaultValue={selectedEmployee?.status || 'active'}
                          className="stake-input"
                          bg="var(--stake-bg-secondary, #182935)"
                          borderColor="var(--stake-border-primary, #2f4553)"
                          color="white"
                          _focus={{
                            borderColor: "#3b82f6",
                            boxShadow: "0 0 0 1px #3b82f6"
                          }}
                          _hover={{
                            borderColor: "#4a5568"
                          }}
                        >
                          <option value="active" style={{background: '#1a2c38', color: 'white'}}>نشط</option>
                          <option value="inactive" style={{background: '#1a2c38', color: 'white'}}>غير نشط</option>
                          <option value="terminated" style={{background: '#1a2c38', color: 'white'}}>منتهي الخدمة</option>
                        </Select>
                      </FormControl>
                    </Box>
                  </SimpleGrid>
                </Box>
              </VStack>
            </form>
          </ModalBody>
          <ModalFooter 
            justifyContent="space-between"
            gap="4"
            bg="var(--stake-bg-primary, #0f212e)"
            borderTop="1px solid"
            borderColor="var(--stake-border-primary, #2f4553)"
            borderRadius="0 0 24px 24px"
            p="6"
            boxShadow="0 -4px 20px rgba(0, 0, 0, 0.4)"
          >
            <HStack spacing="4" align="center">
              <Checkbox
                {...register('is_insured')}
                defaultChecked={selectedEmployee?.is_insured || false}
                colorScheme="blue"
                onChange={(e) => {
                  setValue('is_insured', e.target.checked);
                }}
              >
                <Text color="#d5dceb" fontWeight="medium">
                  مؤمن عليه
                </Text>
              </Checkbox>

            </HStack>
            <HStack spacing="3">
              <Button 
                onClick={handleEditClose}
                h="48px"
                px="8"
                fontWeight="600"
                borderRadius="xl"
                bg="var(--stake-bg-secondary, #182935)"
                color="#d5dceb"
                border="1px solid"
                borderColor="var(--stake-border-primary, #2f4553)"
                _hover={{
                  bg: "#213743",
                  borderColor: "#3b82f6"
                }}
              >
                إلغاء
              </Button>
              <Button
                leftIcon={<FiSave />}
                h="48px"
                px="8"
                fontWeight="600"
                borderRadius="xl"
                bg="#3b82f6"
                color="white"
                _hover={{
                  bg: "#2563eb"
                }}
                onClick={async () => {
                  console.log('🔥 Save button clicked!');
                  console.log('🔥 Form values:', watch());
                  console.log('🔥 Form errors:', errors);
                  
                  // Get form data manually
                  const formData = watch();
                  console.log('🔥 AC-No. value in form:', formData.ac_no);
                  console.log('🔥 Calling handleEditEmployee with:', formData);
                  
                  // Call handleEditEmployee directly
                  await handleEditEmployee(formData);
                }}
              >
                حفظ التعديلات
              </Button>
              <Button
                leftIcon={<FiTrash2 />}
                h="48px"
                px="8"
                fontWeight="600"
                borderRadius="xl"
                bg="#dc2626"
                color="white"
                _hover={{
                  bg: "#b91c1c"
                }}
                onClick={() => {
                  const employeeName = selectedEmployee?.name_ar || selectedEmployee?.name || 'هذا الموظف';
                  const confirmMessage = `⚠️ تحذير: حذف الموظف نهائياً\n\nالموظف: ${employeeName}\nالكود: ${selectedEmployee?.employee_code || 'غير محدد'}\n\nهذا الإجراء سيحذف:\n• بيانات الموظف من قاعدة البيانات\n• جميع سجلات الحضور والانصراف\n• جميع البيانات المرتبطة بالموظف\n\n⚠️ لا يمكن التراجع عن هذا الإجراء!\n\nهل أنت متأكد من المتابعة؟`;
                  
                  if (window.confirm(confirmMessage)) {
                    handleDeleteEmployee(selectedEmployee);
                    handleEditClose();
                  }
                }}
              >
                حذف الموظف
              </Button>
            </HStack>
          </ModalFooter>
        </ModalContent>
      </Modal>

      {/* Fullscreen Table Modal */}
      <Modal isOpen={isFullscreen} onClose={toggleFullscreen} size="full">
        <ModalOverlay bg="blackAlpha.600" backdropFilter="blur(10px)" />
        <ModalContent maxW="100vw" maxH="100vh" m="0" borderRadius="0">
          <ModalHeader 
            bg="linear-gradient(135deg, #667eea 0%, #764ba2 100%)"
            color="white"
            display="flex"
            justifyContent="space-between"
            alignItems="center"
          >
            <Text fontSize="xl" fontWeight="bold">
              جدول الموظفين - عرض ملء الشاشة
            </Text>
            <IconButton
              icon={<FiMinimize />}
              variant="ghost"
              color="white"
              _hover={{ bg: "whiteAlpha.200" }}
              onClick={toggleFullscreen}
              aria-label="خروج من ملء الشاشة"
            />
          </ModalHeader>
          <ModalBody p="0" overflow="hidden">
            {/* Search and Filters Bar - Single Row */}
            <Box p="4" bg="gray.50" borderBottom="1px" borderColor="gray.200">
              <VStack spacing="3" align="stretch">
                {/* Single Row: Search + Combined Filter + Actions */}
                <HStack spacing="3" align="end" wrap="wrap">
                  {/* Search Bar */}
                  <Box flex="1" minW="200px">
                    <Text fontSize="sm" fontWeight="medium" mb="1" color="gray.600">
                      البحث
                    </Text>
                    <InputGroup>
                      <Input
                        placeholder="البحث في الموظفين..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        bg="white"
                        border="1px solid"
                        borderColor="gray.300"
                        className="stake-input"
                        pr="12"
                        _focus={{
                          borderColor: "var(--stake-border-accent)",
                          boxShadow: "0 0 0 1px var(--stake-border-accent)",
                        }}
                        _hover={{
                          borderColor: "var(--stake-border-accent)"
                        }}
                      />
                      <InputRightElement pointerEvents="none">
                        <FiSearch className="stake-text-secondary" />
                      </InputRightElement>
                    </InputGroup>
                  </Box>

                  {/* Combined Filter */}
                  <Box
                    display="flex"
                    alignItems="center"
                    gap="2"
                    minW="250px"
                  >
                    {/* Filter Type Dropdown */}
                    <Menu>
                      <MenuButton
                        as={Button}
                        rightIcon={<FiChevronDown />}
                        h="44px"
                        flex="1"
                        borderRadius="lg"
                        border="none"
                        boxShadow="none"
                        className="stake-input"
                        _focus={{
                          borderColor: "transparent",
                          boxShadow: "none"
                        }}
                        _hover={{
                          borderColor: "transparent",
                          boxShadow: "none"
                        }}
                      >
                        {selectedFilterType ? 
                          (selectedFilterType === 'salaryType' ? 'نوع الراتب' :
                           selectedFilterType === 'department' ? 'القسم' :
                           selectedFilterType === 'costCenter' ? 'مركز التكلفة' : 'نوع الفلتر') :
                          'نوع الفلتر'
                        }
                      </MenuButton>
                      <MenuList className="stake-card" bg="var(--stake-bg-primary, #0f212e)" border="1px solid #2f4553" boxShadow="0 12px 24px rgba(0,0,0,0.35)" borderRadius="12px">
                        <MenuItem icon={<FiDollarSign />} onClick={() => handleFilterTypeSelect('salaryType')}>
                          نوع الراتب
                        </MenuItem>
                        <MenuItem icon={<FiBriefcase />} onClick={() => handleFilterTypeSelect('department')}>
                          القسم
                        </MenuItem>
                        <MenuItem icon={<FiBriefcase />} onClick={() => handleFilterTypeSelect('costCenter')}>
                          مركز التكلفة
                        </MenuItem>
                      </MenuList>
                    </Menu>

                    {/* Separator */}
                    <Box w="1px" bg="var(--stake-border-primary)" h="20px" />

                    {/* Filter Value Dropdown */}
                    <Menu>
                      <MenuButton
                        as={Button}
                        rightIcon={<FiChevronDown />}
                        h="44px"
                        flex="1"
                        borderRadius="lg"
                        border="none"
                        boxShadow="none"
                        className="stake-input"
                        _focus={{
                          borderColor: "transparent",
                          boxShadow: "none"
                        }}
                        _hover={{
                          borderColor: "transparent",
                          boxShadow: "none"
                        }}
                        isDisabled={!selectedFilterType}
                      >
                        {selectedFilterType === 'salaryType' && salaryTypeFilter ? 
                          (salaryTypeFilter === 'Monthly' ? 'شهري' : 'أسبوعي') :
                        selectedFilterType === 'department' && departmentFilter ? departmentFilter :
                        selectedFilterType === 'costCenter' && costCenterFilter ? costCenterFilter :
                        'اختر القيمة'
                        }
                      </MenuButton>
                      <MenuList className="stake-card" bg="var(--stake-bg-primary, #0f212e)" border="1px solid #2f4553" boxShadow="0 12px 24px rgba(0,0,0,0.35)" borderRadius="12px">
                        {selectedFilterType === 'salaryType' && (
                          <>
                            <MenuItem icon={<FiDollarSign />} onClick={() => setSalaryTypeFilter('Monthly')}>شهري</MenuItem>
                            <MenuItem icon={<FiDollarSign />} onClick={() => setSalaryTypeFilter('Weekly')}>أسبوعي</MenuItem>
                          </>
                        )}
                        {selectedFilterType === 'department' && (
                          <>
                            {departments.map(dept => (
                              <MenuItem key={dept.id} icon={<FiBriefcase />} onClick={() => setDepartmentFilter(dept.name)}>
                                {dept.description || dept.name}
                              </MenuItem>
                            ))}
                          </>
                        )}
                        {selectedFilterType === 'costCenter' && (
                          <>
                            {costCenters.map(center => (
                              <MenuItem key={center.id} icon={<FiBriefcase />} onClick={() => setCostCenterFilter(center.name)}>
                                {center.name}
                              </MenuItem>
                            ))}
                          </>
                        )}
                      </MenuList>
                    </Menu>
                  </Box>

                  {/* Action Buttons */}
                  <HStack spacing="2">
                    <IconButton
                      icon={<FiX />}
                      variant="outline"
                      colorScheme="red"
                      onClick={clearFilters}
                      w="44px"
                      h="44px"
                      className="stake-input"
                      borderRadius="xl"
                      aria-label="مسح الفلاتر"
                      _hover={{
                        bg: "var(--stake-bg-hover)",
                        borderColor: "var(--stake-border-accent)"
                      }}
                    />
                    <Tooltip 
                      label="تصدير البيانات"
                      bg="var(--stake-bg-secondary)"
                      color="var(--stake-text-primary)"
                      borderColor="var(--stake-border-primary)"
                    >
                      <IconButton
                        icon={<FiDownload />}
                        variant="outline"
                        colorScheme="green"
                        onClick={() => {
                          toast({
                            title: "تصدير البيانات",
                            description: "سيتم إضافة ميزة التصدير قريباً",
                            status: "info",
                            duration: 3000,
                            isClosable: true,
                          });
                        }}
                        aria-label="تصدير البيانات"
                      />
                    </Tooltip>
                  </HStack>
                </HStack>

                {/* Bulk Actions */}
                {selectedEmployees.length > 0 && (
                  <HStack spacing="3" p="3" bg="blue.50" borderRadius="lg" border="1px solid" borderColor="blue.200">
                    <Text fontSize="sm" fontWeight="medium" color="blue.700">
                      تم اختيار {selectedEmployees.length} موظف
                    </Text>
                    <HStack spacing="2">
                      <Button
                        bg="blue.500"
                        color="white"
                        _hover={{ bg: "blue.600" }}
                        _active={{ bg: "blue.700" }}
                        leftIcon={<FiEdit />}
                        onClick={handleBulkEdit}
                      >
                        تعديل الكل
                      </Button>
                      <Button
                        bg="red.500"
                        color="white"
                        _hover={{ bg: "red.600" }}
                        _active={{ bg: "red.700" }}
                        leftIcon={<FiTrash2 />}
                        onClick={handleBulkDelete}
                      >
                        حذف الكل
                      </Button>
                    </HStack>
                  </HStack>
                )}

                {/* Results Count and Pagination Info */}
                <HStack justify="space-between" align="center">
                  <Text fontSize="sm" color="gray.600">
                    عرض {filteredEmployees.length} من أصل {employees.length} موظف
                  </Text>
                  {totalPages > 1 && !showAllContent && (
                    <HStack spacing="2">
                      <Button
                        variant="outline"
                        onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
                        isDisabled={currentPage === 1}
                      >
                        السابق
                      </Button>
                      <Text fontSize="sm" color="gray.600">
                        صفحة {currentPage} من {totalPages}
                      </Text>
                      <Button
                        variant="outline"
                        onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
                        isDisabled={currentPage === totalPages}
                      >
                        التالي
                      </Button>
                    </HStack>
                  )}
                </HStack>
              </VStack>
            </Box>

            <TableContainer maxH="calc(100vh - 280px)" overflowY="auto">
              <Table variant="simple" >
                <Thead position="sticky" top="0" zIndex="10" bg="var(--stake-bg-primary)" boxShadow="var(--stake-shadow-sm)">
                  <Tr>
                    <Th>
                      <Checkbox
                        isChecked={selectedRowKeys.length === paginatedEmployees.length && paginatedEmployees.length > 0}
                        isIndeterminate={selectedRowKeys.length > 0 && selectedRowKeys.length < paginatedEmployees.length}
                        onChange={(e) => {
                          if (e.target.checked) {
                            const allKeys = paginatedEmployees.map(emp => emp.id);
                            setSelectedRowKeys(allKeys);
                            setSelectedEmployees(paginatedEmployees);
                          } else {
                            setSelectedRowKeys([]);
                            setSelectedEmployees([]);
                          }
                        }}
                      />
                    </Th>
                    <Th>
                      <EnglishKeyTooltip englishKey="code">
                        الكود
                      </EnglishKeyTooltip>
                    </Th>
                    <Th>
                      <EnglishKeyTooltip englishKey="name">
                        الاسم
                      </EnglishKeyTooltip>
                    </Th>
                    <Th>
                      <EnglishKeyTooltip englishKey="name_ar">
                        الاسم العربي
                      </EnglishKeyTooltip>
                    </Th>
                    <Th>
                      <EnglishKeyTooltip englishKey="base_salary">
                        الراتب الأساسي
                      </EnglishKeyTooltip>
                    </Th>
                    <Th>
                      <EnglishKeyTooltip englishKey="salary_type">
                        نوع الراتب
                      </EnglishKeyTooltip>
                    </Th>
                    <Th>
                      <EnglishKeyTooltip englishKey="insured">
                        مؤمن
                      </EnglishKeyTooltip>
                    </Th>
                    <Th>
                      <EnglishKeyTooltip englishKey="department">
                        القسم
                      </EnglishKeyTooltip>
                    </Th>
                    <Th>
                      <EnglishKeyTooltip englishKey="cost_center">
                        مركز التكلفة
                      </EnglishKeyTooltip>
                    </Th>
                    <Th>
                      <EnglishKeyTooltip englishKey="location">
                        الموقع
                      </EnglishKeyTooltip>
                    </Th>
                    <Th>
                      <EnglishKeyTooltip englishKey="position">
                        المنصب
                      </EnglishKeyTooltip>
                    </Th>
                    <Th>
                      <EnglishKeyTooltip englishKey="hire_date">
                        تاريخ التوظيف
                      </EnglishKeyTooltip>
                    </Th>
                  </Tr>
                </Thead>
                <Tbody>
                  {paginatedEmployees.map((employee) => (
                    <Tr 
                      key={employee.id}
                      onDoubleClick={() => handleViewEmployee(employee)}
                      cursor="pointer"
                      _hover={{ bg: "var(--stake-bg-hover)" }}
                    >
                      <Td>
                        <Checkbox
                          isChecked={selectedRowKeys.includes(employee.id)}
                          onChange={(e) => {
                            if (e.target.checked) {
                              setSelectedRowKeys([...selectedRowKeys, employee.id]);
                              setSelectedEmployees([...selectedEmployees, employee]);
                            } else {
                              setSelectedRowKeys(selectedRowKeys.filter(key => key !== employee.id));
                              setSelectedEmployees(selectedEmployees.filter(emp => emp.id !== employee.id));
                            }
                          }}
                        />
                      </Td>
                      <Td fontWeight="semibold" color="blue.600">
                        {employee.employee_code}
                      </Td>
                      <Td>{employee.name}</Td>
                      <Td fontWeight="medium">{employee.name_ar}</Td>
                      <Td>
                        <Text fontWeight="semibold" color="green.600">
                          {formatCurrency(employee.base_salary || 0)}
                        </Text>
                      </Td>
                      <Td>
                        <Badge
                          colorScheme={
                            employee.salary_type === 'Monthly' ? 'blue' : 'purple'
                          }
                          variant="subtle"
                        >
                          {employee.salary_type === 'Monthly' ? 'شهري' : 'أسبوعي'}
                        </Badge>
                      </Td>
                      <Td>
                        <Badge
                          colorScheme={employee.is_insured ? 'green' : 'red'}
                          variant="subtle"
                        >
                          {employee.is_insured ? 'نعم' : 'لا'}
                        </Badge>
                      </Td>
                      <Td>{employee.department_description || employee.department || '-'}</Td>
                      <Td>{employee.cost_center}</Td>
                      <Td>{employee.location}</Td>
                      <Td>{employee.position}</Td>
                      <Td>{employee.hire_date}</Td>
                    </Tr>
                  ))}
                </Tbody>
              </Table>
            </TableContainer>
          </ModalBody>
        </ModalContent>
      </Modal>

      {/* مودال التعديل الجماعي */}
      <Modal isOpen={isBulkEditOpen} onClose={onBulkEditClose} size="xl">
        <ModalOverlay />
        <ModalContent borderRadius="3xl" overflow="hidden">
          <ModalHeader 
            bg="var(--stake-bg-primary)" 
            borderBottom="1px solid" 
            borderColor="var(--stake-border)"
            position="relative"
          >
            <HStack spacing="3" align="center">
              <Icon as={FiEdit} color="blue.400" boxSize="5" />
              <Text fontSize="lg" fontWeight="semibold" color="var(--stake-text-primary)">
                تعديل {selectedEmployees.length} موظف
              </Text>
            </HStack>
            <ModalCloseButton 
              position="absolute" 
              top="4" 
              right="4" 
              color="var(--stake-text-secondary)"
              _hover={{ color: "var(--stake-text-primary)" }}
            />
          </ModalHeader>
          <ModalBody>
            <VStack spacing="4" align="stretch">
              <Alert status="info" borderRadius="lg">
                <AlertIcon />
                <AlertDescription>
                  سيتم تطبيق التغييرات على {selectedEmployees.length} موظف. اترك الحقول فارغة إذا كنت لا تريد تغييرها.
                </AlertDescription>
              </Alert>
              
              <SimpleGrid columns={{ base: 1, md: 2 }} spacing="4">
                <Box>
                  <FormLabel>نوع الراتب</FormLabel>
                  <Select
                    placeholder="اختر نوع الراتب"
                    value={bulkEditForm.salary_type}
                    onChange={(e) => setBulkEditForm({...bulkEditForm, salary_type: e.target.value})}
                    bg="white"
                    border="1px solid"
                    borderColor="gray.300"
                    className="stake-input"
                    _focus={{ borderColor: "var(--stake-border-accent)", boxShadow: "0 0 0 1px var(--stake-border-accent)" }}
                    _hover={{ borderColor: "var(--stake-border-accent)" }}
                  >
<option value="Monthly" style={{background: '#1a2c38', color: 'white'}}>شهري</option>
                                <option value="Weekly" style={{background: '#1a2c38', color: 'white'}}>أسبوعي</option>
                  </Select>
                </Box>
                
                <Box>
                  <FormLabel>القسم</FormLabel>
                  <Select
                    placeholder="اختر القسم"
                    bg="white"
                    border="1px solid"
                    borderColor="gray.300"
                    _focus={{ borderColor: "blue.500", boxShadow: "0 0 0 1px #3182ce" }}
                  >
                    {departments.map((dept) => (
                      <option key={dept.id} value={dept.name}>
                        {dept.description || dept.name}
                      </option>
                    ))}
                  </Select>
                </Box>
                
                <Box>
                  <FormLabel>مركز التكلفة</FormLabel>
                  <Select
                    placeholder="اختر مركز التكلفة"
                    bg="white"
                    border="1px solid"
                    borderColor="gray.300"
                    _focus={{ borderColor: "blue.500", boxShadow: "0 0 0 1px #3182ce" }}
                  >
                    {costCenters.map((center) => (
                      <option key={center.id} value={center.name}>
                        {center.name}
                      </option>
                    ))}
                  </Select>
                </Box>
                
                <Box>
                  <FormLabel>المنصب</FormLabel>
                  <Input
                    placeholder="المنصب"
                    value={bulkEditForm.position}
                    onChange={(e) => setBulkEditForm({...bulkEditForm, position: e.target.value})}
                    bg="white"
                    border="1px solid"
                    borderColor="gray.300"
                    _focus={{ borderColor: "blue.500", boxShadow: "0 0 0 1px #3182ce" }}
                  />
                </Box>
                
                <Box>
                  <FormLabel>الحالة</FormLabel>
                  <Select
                    placeholder="اختر الحالة"
                    bg="white"
                    border="1px solid"
                    borderColor="gray.300"
                    _focus={{ borderColor: "blue.500", boxShadow: "0 0 0 1px #3182ce" }}
                  >
                    <option value="active">نشط</option>
                    <option value="inactive">غير نشط</option>
                  </Select>
                </Box>
                
                <Box>
                  <FormLabel>الراتب الأساسي</FormLabel>
                  <Input
                    type="number"
                    placeholder="0"
                    value={bulkEditForm.base_salary}
                    onChange={(e) => setBulkEditForm({...bulkEditForm, base_salary: e.target.value})}
                    bg="white"
                    border="1px solid"
                    borderColor="gray.300"
                    _focus={{ borderColor: "blue.500", boxShadow: "0 0 0 1px #3182ce" }}
                  />
                </Box>
                
                <Box>
                  <FormLabel>الموقع</FormLabel>
                  <Input
                    placeholder="الموقع"
                    value={bulkEditForm.location}
                    onChange={(e) => setBulkEditForm({...bulkEditForm, location: e.target.value})}
                    bg="white"
                    border="1px solid"
                    borderColor="gray.300"
                    _focus={{ borderColor: "blue.500", boxShadow: "0 0 0 1px #3182ce" }}
                  />
                </Box>
              </SimpleGrid>
            </VStack>
          </ModalBody>
          <ModalFooter 
            bg="var(--stake-bg-secondary)" 
            borderTop="1px solid" 
            borderColor="var(--stake-border)"
            py="4"
            px="6"
          >
            <HStack spacing="3" w="full" justify="flex-end">
              <Button 
                variant="outline" 
                onClick={onBulkEditClose}
                borderColor="var(--stake-border)"
                color="var(--stake-text-secondary)"
                _hover={{ 
                  borderColor: "var(--stake-border-accent)", 
                  color: "var(--stake-text-primary)",
                  bg: "var(--stake-bg-hover)"
                }}
              >
                إلغاء
              </Button>
              <Button
                colorScheme="blue"
                onClick={() => handleBulkEditSubmit(bulkEditForm)}
                bg="blue.500"
                color="white"
                _hover={{ bg: "blue.600" }}
                _active={{ bg: "blue.700" }}
                leftIcon={<FiSave />}
              >
                تطبيق التغييرات
              </Button>
            </HStack>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Box>
  );
};

export default PremiumEmployees;
