import React, { useEffect, useState } from 'react';
import { getApiUrl } from '../utils/apiUrlHelper';
import {
  Box,
  Card,
  CardHeader,
  CardBody,
  Heading,
  Text,
  VStack,
  HStack,
  Grid,
  GridItem,
  SimpleGrid,
  FormControl,
  FormLabel,
  Input,
  Slider,
  SliderTrack,
  SliderFilledTrack,
  SliderThumb,
  Switch as CSwitch,
  Button,
  useToast,
  Divider,
  Icon,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalCloseButton,
  ModalBody,
  Badge,
  Tooltip
} from '@chakra-ui/react';
import { SaveOutlined, FontSizeOutlined, BgColorsOutlined, CheckCircleOutlined } from '@ant-design/icons';
import { useSettings } from '../contexts/SettingsContext';
import { FiCheck } from 'react-icons/fi';

const NewAppearanceSettings = () => {
  const toast = useToast();
  const { updateSettings, reloadSettings } = useSettings();

  const [loading, setLoading] = useState(false);
  const [tempSettings, setTempSettings] = useState({});

  // Dark theme tokens
  const cardBg = '#0f212e';
  const cardBorder = '#3e5665';
  const headerBg = '#102a3a';
  const headerText = '#ffffff';
  const subText = '#a0aec0';
  const inputBg = '#0f212e';
  const inputText = '#e2e8f0';
  const inputBorder = '#3e5665';

  const [isSystemFontModalOpen, setIsSystemFontModalOpen] = useState(false);
  const [isTableFontModalOpen, setIsTableFontModalOpen] = useState(false);

  const arabicFonts = [
    { value: 'Cairo', label: 'Cairo', preview: 'نظام إدارة الرواتب' },
    { value: 'Tajawal', label: 'Tajawal', preview: 'نظام إدارة الرواتب' },
    { value: 'Amiri', label: 'Amiri', preview: 'نظام إدارة الرواتب' },
    { value: 'Noto Sans Arabic', label: 'Noto Sans Arabic', preview: 'نظام إدارة الرواتب' },
    { value: 'Changa', label: 'Changa', preview: 'نظام إدارة الرواتب' },
    { value: 'Lateef', label: 'Lateef', preview: 'نظام إدارة الرواتب' },
    { value: 'Scheherazade New', label: 'Scheherazade New', preview: 'نظام إدارة الرواتب' },
    { value: 'Markazi Text', label: 'Markazi Text', preview: 'نظام إدارة الرواتب' },
    { value: 'Harmattan', label: 'Harmattan', preview: 'نظام إدارة الرواتب' },
    { value: 'Lalezar', label: 'Lalezar', preview: 'نظام إدارة الرواتب' },
    { value: 'Mada', label: 'Mada', preview: 'نظام إدارة الرواتب' },
    { value: 'Mirza', label: 'Mirza', preview: 'نظام إدارة الرواتب' },
    { value: 'Rasa', label: 'Rasa', preview: 'نظام إدارة الرواتب' },
    { value: 'Aref Ruqaa', label: 'Aref Ruqaa', preview: 'نظام إدارة الرواتب' },
    { value: 'Kufam', label: 'Kufam' },
    { value: 'Lemonada', label: 'Lemonada' },
    { value: 'Baloo Bhaijaan 2', label: 'Baloo Bhaijaan 2' },
    { value: 'Readex Pro', label: 'Readex Pro' },
    { value: 'IBM Plex Sans Arabic', label: 'IBM Plex Sans Arabic' }
  ];

  // القوالب المتاحة
  const colorThemes = [
    {
      id: 'dark-ocean',
      name: 'Dark Ocean',
      nameAr: 'المحيط الداكن',
      icon: '🌊',
      description: 'الثيم الحالي - أزرق داكن احترافي',
      colors: {
        bgPrimary: '#0f212e',
        bgSecondary: '#182935',
        bgCard: '#1b2b38',
        bgHover: '#243442',
        borderPrimary: '#3e5665',
        textPrimary: '#ffffff',
        textSecondary: '#a0aec0',
        accent: '#1475e1',
        success: '#22c55e',
        error: '#ef4444',
        warning: '#f59e0b'
      }
    },
    {
      id: 'soft-light',
      name: 'Soft Light',
      nameAr: 'الضوء الناعم',
      icon: '☀️',
      description: 'ثيم فاتح مريح للعين',
      colors: {
        bgPrimary: '#f8fafc',
        bgSecondary: '#f1f5f9',
        bgCard: '#ffffff',
        bgHover: '#e2e8f0',
        borderPrimary: '#e2e8f0',
        textPrimary: '#1e293b',
        textSecondary: '#64748b',
        accent: '#6366f1',
        success: '#16a34a',
        error: '#dc2626',
        warning: '#d97706'
      }
    },
    {
      id: 'modern-gradient',
      name: 'Modern Gradient',
      nameAr: 'التدرج العصري',
      icon: '🌌',
      description: 'عصري بتدرجات بنفسجية ووردية',
      colors: {
        bgPrimary: '#1e1e2f',
        bgSecondary: '#252538',
        bgCard: '#2d2d44',
        bgHover: '#3a3a55',
        borderPrimary: 'rgba(139, 92, 246, 0.2)',
        textPrimary: '#ffffff',
        textSecondary: '#a5b4fc',
        accent: '#8b5cf6',
        accentSecondary: '#ec4899',
        success: '#10b981',
        error: '#f43f5e',
        warning: '#fb923c'
      }
    },
    {
      id: 'emerald-dark',
      name: 'Emerald Dark',
      nameAr: 'الزمرد الداكن',
      icon: '💎',
      description: 'أخضر زمردي داكن وأنيق',
      colors: {
        bgPrimary: '#0c1f1f',
        bgSecondary: '#132626',
        bgCard: '#1a3333',
        bgHover: '#234545',
        borderPrimary: '#1f4040',
        textPrimary: '#ffffff',
        textSecondary: '#6ee7b7',
        accent: '#10b981',
        success: '#10b981',
        error: '#f87171',
        warning: '#fbbf24'
      }
    }
  ];

  const [selectedTheme, setSelectedTheme] = useState('dark-ocean');

  const loadAppearanceSettings = async () => {
    try {
      setLoading(true);
      const response = await fetch(getApiUrl('/api/comprehensive_settings_api.php?action=get_settings_by_category&category=appearance'));
      const data = await response.json();
      if (data.success) {
        const s = {};
        data.settings.forEach(setting => { s[setting.setting_key] = setting.setting_value; });
        const loaded = {
          fontFamily: s.font_family || 'Cairo',
          tableFontFamily: s.table_font_family || 'Cairo',
          tableFontSize: parseInt(s.table_font_size) || 14,
          tableFontWeight: parseInt(s.table_font_weight) || 600,
          showEnglishKeys: s.show_english_keys === 'true' || s.show_english_keys === '1'
        };
        setTempSettings(loaded);
        if (loaded.fontFamily) applyFont(loaded.fontFamily);
        applyTableSettings(loaded);
        
        // تحميل القالب المحفوظ
        if (s.color_theme) {
          setSelectedTheme(s.color_theme);
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  // تطبيق قالب الألوان
  const applyColorTheme = (themeId) => {
    const theme = colorThemes.find(t => t.id === themeId);
    if (!theme) return;

    const root = document.documentElement;
    const colors = theme.colors;
    
    // تحديد ما إذا كان القالب فاتحاً أو داكناً
    const isLightTheme = themeId === 'soft-light';
    
    // إضافة/إزالة class للقالب الفاتح
    if (isLightTheme) {
      document.body.classList.add('light-theme');
      document.body.classList.remove('dark-theme');
      document.body.setAttribute('data-theme', 'light');
    } else {
      document.body.classList.add('dark-theme');
      document.body.classList.remove('light-theme');
      document.body.setAttribute('data-theme', 'dark');
    }

    // تطبيق الألوان على متغيرات CSS الأساسية
    root.style.setProperty('--stake-bg-primary', colors.bgPrimary);
    root.style.setProperty('--stake-bg-secondary', colors.bgSecondary);
    root.style.setProperty('--stake-bg-card', colors.bgCard);
    root.style.setProperty('--stake-bg-tertiary', colors.bgSecondary);
    root.style.setProperty('--stake-bg-hover', colors.bgHover || colors.bgCard);
    root.style.setProperty('--stake-border-primary', colors.borderPrimary);
    root.style.setProperty('--stake-border-secondary', colors.borderPrimary);
    root.style.setProperty('--stake-text-primary', colors.textPrimary);
    root.style.setProperty('--stake-text-secondary', colors.textSecondary);
    root.style.setProperty('--stake-text-muted', colors.textSecondary);
    root.style.setProperty('--stake-primary', colors.accent);
    root.style.setProperty('--stake-success', colors.success);
    root.style.setProperty('--stake-error', colors.error);
    root.style.setProperty('--stake-warning', colors.warning);
    
    // تطبيق لون النص على body
    document.body.style.color = colors.textPrimary;
    
    // متغيرات إضافية للتوافق
    root.style.setProperty('--color-grey-700', colors.bgPrimary);
    root.style.setProperty('--color-grey-600', colors.bgSecondary);
    root.style.setProperty('--color-grey-500', colors.bgCard);
    root.style.setProperty('--color-grey-400', colors.borderPrimary);
    root.style.setProperty('--color-grey-300', colors.borderPrimary);
    root.style.setProperty('--color-grey-200', colors.textSecondary);
    root.style.setProperty('--color-grey-100', colors.textPrimary);
    root.style.setProperty('--color-white', colors.textPrimary);
    root.style.setProperty('--color-blue-500', colors.accent);

    // تطبيق الخلفية على body و html
    document.body.style.background = colors.bgPrimary;
    document.body.style.backgroundColor = colors.bgPrimary;
    root.style.background = colors.bgPrimary;
    
    // تطبيق الألوان على الـ root element
    const rootEl = document.getElementById('root');
    if (rootEl) {
      rootEl.style.background = colors.bgPrimary;
    }

    // تطبيق الألوان على Sidebar
    const sidebars = document.querySelectorAll('.stake-sidebar');
    sidebars.forEach(sidebar => {
      sidebar.style.background = `linear-gradient(90deg, ${colors.bgPrimary} 0%, ${colors.bgSecondary} 100%)`;
      sidebar.style.borderColor = colors.borderPrimary;
    });

    // تطبيق الألوان على Header
    const headers = document.querySelectorAll('.stake-header');
    headers.forEach(header => {
      header.style.background = `linear-gradient(358deg, ${colors.bgPrimary} 0%, ${colors.bgSecondary} 100%)`;
      header.style.borderColor = colors.borderPrimary;
    });

    // تطبيق الألوان على البطاقات
    const cards = document.querySelectorAll('.chakra-card, .stake-card');
    cards.forEach(card => {
      card.style.background = colors.bgCard;
      card.style.borderColor = colors.borderPrimary;
    });

    // تطبيق على الصفحة الرئيسية
    const mainContent = document.querySelectorAll('.stake-main-content, [class*="chakra-box"]');
    mainContent.forEach(el => {
      if (el.style && el.style.minHeight === '85vh') {
        el.style.background = colors.bgPrimary;
      }
    });

    // إضافة CSS ديناميكي للتأكد من تطبيق الألوان
    let styleEl = document.getElementById('dynamic-theme-styles');
    if (!styleEl) {
      styleEl = document.createElement('style');
      styleEl.id = 'dynamic-theme-styles';
      document.head.appendChild(styleEl);
    }
    
    styleEl.textContent = `
      /* Dynamic Theme Styles */
      body, html, #root {
        background: ${colors.bgPrimary} !important;
      }
      
      .stake-sidebar {
        background: linear-gradient(180deg, ${colors.bgPrimary} 0%, ${colors.bgSecondary} 100%) !important;
        border-color: ${colors.borderPrimary} !important;
      }
      
      .stake-sidebar .chakra-button,
      .stake-sidebar .chakra-iconbutton {
        color: ${colors.textSecondary} !important;
      }
      
      .stake-sidebar .chakra-button:hover,
      .stake-sidebar .chakra-iconbutton:hover {
        background: ${colors.bgCard} !important;
        color: ${colors.textPrimary} !important;
      }
      
      .stake-sidebar .chakra-button[aria-current="page"],
      .stake-sidebar .chakra-iconbutton[aria-current="page"] {
        background: ${colors.bgCard} !important;
        color: ${colors.textPrimary} !important;
      }
      
      .stake-header {
        background: linear-gradient(358deg, ${colors.bgPrimary} 0%, ${colors.bgSecondary} 100%) !important;
        border-color: ${colors.borderPrimary} !important;
      }
      
      .stake-header .chakra-button,
      .stake-header .chakra-iconbutton {
        color: ${colors.textPrimary} !important;
      }
      
      .stake-header .chakra-button:hover,
      .stake-header .chakra-iconbutton:hover {
        background: ${colors.bgCard} !important;
        color: ${colors.accent} !important;
      }
      
      .chakra-card {
        background: ${colors.bgCard} !important;
        border-color: ${colors.borderPrimary} !important;
      }
      
      .chakra-modal__content {
        background: ${colors.bgCard} !important;
        border-color: ${colors.borderPrimary} !important;
      }
      
      .chakra-modal__header {
        background: ${colors.bgSecondary} !important;
        color: ${colors.textPrimary} !important;
      }
      
      .chakra-modal__body {
        background: ${colors.bgCard} !important;
        color: ${colors.textPrimary} !important;
      }
      
      .chakra-menu__menu-list {
        background: ${colors.bgPrimary} !important;
        border-color: ${colors.borderPrimary} !important;
      }
      
      .chakra-menu__menuitem {
        color: ${colors.textPrimary} !important;
      }
      
      .chakra-menu__menuitem:hover {
        background: ${colors.bgSecondary} !important;
      }
      
      .stake-table th {
        background: linear-gradient(358deg, ${colors.bgPrimary} 0%, ${colors.bgSecondary} 100%) !important;
        color: ${colors.textPrimary} !important;
      }
      
      .stake-table td {
        background: ${colors.bgCard} !important;
        color: ${colors.textSecondary} !important;
        border-color: ${colors.borderPrimary} !important;
      }
      
      .stake-table tr:hover td {
        background: ${colors.bgSecondary} !important;
      }
      
      .chakra-input, .chakra-select, .chakra-textarea {
        background: ${colors.bgPrimary} !important;
        border-color: ${colors.borderPrimary} !important;
        color: ${colors.textPrimary} !important;
      }
      
      .chakra-input:focus, .chakra-select:focus, .chakra-textarea:focus {
        border-color: ${colors.accent} !important;
      }
      
      /* Dashboard specific */
      [class*="PremiumDashboard"] > div,
      .dashboard-page {
        background: ${colors.bgPrimary} !important;
      }
    `;
    
    setSelectedTheme(themeId);
    setTempSettings(s => ({ ...s, colorTheme: themeId }));
    
    // إرسال حدث لتحديث المكونات الأخرى
    window.dispatchEvent(new CustomEvent('themeChanged', { detail: { themeId, colors } }));
  };

  // حفظ القالب مع الإعدادات الأخرى
  const handleThemeSelect = (themeId) => {
    applyColorTheme(themeId);
    toast({
      title: `تم اختيار قالب "${colorThemes.find(t => t.id === themeId)?.nameAr}"`,
      description: 'اضغط "حفظ إعدادات المظهر" لحفظ التغييرات',
      status: 'info',
      duration: 3000,
    });
  };

  useEffect(() => { 
    loadAppearanceSettings();
  }, []);

  // تطبيق القالب عند تغييره
  useEffect(() => {
    if (selectedTheme) {
      applyColorTheme(selectedTheme);
    }
  }, []);

  const applyFont = (fontFamily) => {
    document.documentElement.style.setProperty('--font-family', `'${fontFamily}', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif`);
    document.body.style.fontFamily = `'${fontFamily}', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif`;
    const root = document.getElementById('root');
    if (root) root.style.fontFamily = `'${fontFamily}', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif`;
  };

  const applyTableSettings = (s) => {
    if (s.tableFontFamily) document.documentElement.style.setProperty('--table-font-family', `'${s.tableFontFamily}', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif`);
    if (s.tableFontSize) document.documentElement.style.setProperty('--table-font-size', `${s.tableFontSize}px`);
    if (s.tableFontWeight) document.documentElement.style.setProperty('--table-font-weight', s.tableFontWeight);
    if (s.showEnglishKeys !== undefined) window.dispatchEvent(new CustomEvent('englishKeysToggled', { detail: { showEnglishKeys: s.showEnglishKeys } }));
  };

  const saveSettings = async () => {
    // السماح بالحفظ إذا كان هناك قالب محدد حتى لو لم تكن هناك تغييرات أخرى
    if ((!tempSettings || Object.keys(tempSettings).length === 0) && !selectedTheme) {
      toast({ title: 'لا توجد تغييرات للحفظ', status: 'info' });
      return;
    }
    setLoading(true);
    try {
      if (tempSettings.fontFamily) applyFont(tempSettings.fontFamily);
      applyTableSettings(tempSettings);
      if (selectedTheme) applyColorTheme(selectedTheme);

      const settingsToUpdate = Object.entries({ ...tempSettings, colorTheme: selectedTheme }).map(([key, value]) => {
        let dbKey = key.replace(/([A-Z])/g, '_$1').toLowerCase();
        if (key === 'showEnglishKeys') dbKey = 'show_english_keys';
        if (key === 'colorTheme') dbKey = 'color_theme';
        return { key: dbKey, value: value, category: 'appearance' };
      });

      const response = await fetch(getApiUrl('/api/comprehensive_settings_api.php'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'update_multiple_settings', settings: settingsToUpdate, category: 'appearance' })
      });
      const data = await response.json();
      if (data.success) {
        toast({ title: 'تم حفظ إعدادات المظهر', status: 'success' });
        updateSettings(tempSettings);
        window.dispatchEvent(new CustomEvent('themeUpdated', { detail: tempSettings }));
        await reloadSettings();
      } else {
        throw new Error(data.message || 'فشل الحفظ');
      }
    } catch (e) {
      console.error(e);
      toast({ title: 'فشل في حفظ الإعدادات', status: 'error' });
    } finally {
      setLoading(false);
    }
  };

  const currentFontLabel = (val) => arabicFonts.find(f => f.value === val)?.label || 'Cairo';

  return (
    <Box>
      <VStack align="stretch" spacing={6}>
        {/* Color Themes Section */}
        <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
          <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
            <HStack spacing="3">
              <Icon as={BgColorsOutlined} color="purple.300" />
              <Heading size="sm" color={headerText}>القوالب المتاحة</Heading>
              <Badge colorScheme="purple" fontSize="xs">جديد</Badge>
            </HStack>
          </CardHeader>
          <CardBody bg="var(--stake-bg-secondary, #1b2b38)">
            <Text color={subText} mb="4" fontSize="sm">
              اختر قالب الألوان المناسب للنظام. يمكنك معاينة كل قالب قبل تطبيقه.
            </Text>
            <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={4}>
              {colorThemes.map((theme) => (
                <Box
                  key={theme.id}
                  position="relative"
                  borderRadius="xl"
                  overflow="hidden"
                  border="2px solid"
                  borderColor={selectedTheme === theme.id ? theme.colors.accent : cardBorder}
                  cursor="pointer"
                  transition="all 0.3s ease"
                  _hover={{ 
                    transform: 'translateY(-4px)', 
                    boxShadow: `0 12px 24px rgba(0,0,0,0.3)`,
                    borderColor: theme.colors.accent
                  }}
                  onClick={() => handleThemeSelect(theme.id)}
                >
                  {/* Theme Preview */}
                  <Box 
                    bg={theme.colors.bgPrimary} 
                    p="3"
                    minH="140px"
                  >
                    {/* Mini Dashboard Preview */}
                    <Box 
                      bg={theme.colors.bgSecondary} 
                      borderRadius="lg" 
                      p="2" 
                      mb="2"
                    >
                      <Text 
                        color={theme.colors.textPrimary} 
                        fontSize="xs" 
                        fontWeight="bold"
                        mb="2"
                      >
                        إحصائيات
                      </Text>
                      <HStack spacing="2">
                        <Box 
                          bg={theme.colors.bgCard} 
                          borderRadius="md" 
                          p="2" 
                          flex="1"
                          border="1px solid"
                          borderColor={theme.colors.borderPrimary}
                        >
                          <Box 
                            w="20px" 
                            h="20px" 
                            borderRadius="full" 
                            bg={`${theme.colors.success}30`}
                            display="flex"
                            alignItems="center"
                            justifyContent="center"
                            mx="auto"
                            mb="1"
                          >
                            <Text fontSize="8px" color={theme.colors.success}>✓</Text>
                          </Box>
                          <Text color={theme.colors.textPrimary} fontSize="10px" textAlign="center" fontWeight="bold">12</Text>
                        </Box>
                        <Box 
                          bg={theme.colors.bgCard} 
                          borderRadius="md" 
                          p="2" 
                          flex="1"
                          border="1px solid"
                          borderColor={theme.colors.borderPrimary}
                        >
                          <Box 
                            w="20px" 
                            h="20px" 
                            borderRadius="full" 
                            bg={`${theme.colors.error}30`}
                            display="flex"
                            alignItems="center"
                            justifyContent="center"
                            mx="auto"
                            mb="1"
                          >
                            <Text fontSize="8px" color={theme.colors.error}>✗</Text>
                          </Box>
                          <Text color={theme.colors.textPrimary} fontSize="10px" textAlign="center" fontWeight="bold">3</Text>
                        </Box>
                        <Box 
                          bg={theme.colors.bgCard} 
                          borderRadius="md" 
                          p="2" 
                          flex="1"
                          border="1px solid"
                          borderColor={theme.colors.borderPrimary}
                        >
                          <Box 
                            w="20px" 
                            h="20px" 
                            borderRadius="full" 
                            bg={`${theme.colors.warning}30`}
                            display="flex"
                            alignItems="center"
                            justifyContent="center"
                            mx="auto"
                            mb="1"
                          >
                            <Text fontSize="8px" color={theme.colors.warning}>⏰</Text>
                          </Box>
                          <Text color={theme.colors.textPrimary} fontSize="10px" textAlign="center" fontWeight="bold">2</Text>
                        </Box>
                      </HStack>
                    </Box>
                    
                    {/* Mini Button Preview */}
                    <HStack spacing="2">
                      <Box 
                        bg={theme.colors.accent} 
                        borderRadius="md" 
                        px="3" 
                        py="1"
                        flex="1"
                      >
                        <Text color="white" fontSize="8px" textAlign="center" fontWeight="bold">زر</Text>
                      </Box>
                      <Box 
                        bg="transparent" 
                        border="1px solid"
                        borderColor={theme.colors.borderPrimary}
                        borderRadius="md" 
                        px="3" 
                        py="1"
                        flex="1"
                      >
                        <Text color={theme.colors.textSecondary} fontSize="8px" textAlign="center">زر</Text>
                      </Box>
                    </HStack>
                  </Box>
                  
                  {/* Theme Info */}
                  <Box bg={theme.colors.bgSecondary} p="3" borderTop="1px solid" borderColor={theme.colors.borderPrimary}>
                    <HStack justify="space-between" align="center">
                      <VStack align="start" spacing="0">
                        <HStack>
                          <Text fontSize="lg">{theme.icon}</Text>
                          <Text color={theme.colors.textPrimary} fontWeight="bold" fontSize="sm">
                            {theme.nameAr}
                          </Text>
                        </HStack>
                        <Text color={theme.colors.textSecondary} fontSize="xs">
                          {theme.name}
                        </Text>
                      </VStack>
                      {selectedTheme === theme.id && (
                        <Box 
                          bg={theme.colors.accent} 
                          borderRadius="full" 
                          p="1"
                        >
                          <Icon as={FiCheck} color="white" boxSize="3" />
                        </Box>
                      )}
                    </HStack>
                  </Box>
                  
                  {/* Selected Indicator */}
                  {selectedTheme === theme.id && (
                    <Box
                      position="absolute"
                      top="2"
                      right="2"
                      bg={theme.colors.accent}
                      color="white"
                      fontSize="xs"
                      fontWeight="bold"
                      px="2"
                      py="1"
                      borderRadius="md"
                    >
                      مُفعّل
                    </Box>
                  )}
                </Box>
              ))}
            </SimpleGrid>
            
            {/* Color Palette Display */}
            <Box mt="6" p="4" bg="var(--stake-bg-card, #0b1a24)" borderRadius="xl" border="1px solid" borderColor={cardBorder}>
              <Text color={inputText} fontWeight="semibold" mb="3">لوحة ألوان القالب المختار</Text>
              <HStack spacing="3" flexWrap="wrap">
                {selectedTheme && colorThemes.find(t => t.id === selectedTheme) && 
                  Object.entries(colorThemes.find(t => t.id === selectedTheme).colors).map(([key, color]) => (
                    <Tooltip key={key} label={`${key}: ${color}`} placement="top">
                      <Box
                        w="40px"
                        h="40px"
                        bg={color}
                        borderRadius="lg"
                        border="2px solid"
                        borderColor="rgba(255,255,255,0.2)"
                        cursor="pointer"
                        transition="transform 0.2s"
                        _hover={{ transform: 'scale(1.1)' }}
                        onClick={() => {
                          navigator.clipboard.writeText(color);
                          toast({ title: `تم نسخ: ${color}`, status: 'success', duration: 1500 });
                        }}
                      />
                    </Tooltip>
                  ))
                }
              </HStack>
            </Box>
          </CardBody>
        </Card>

        {/* Font Settings */}
        <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
          <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
            <HStack spacing="3">
              <Icon as={FontSizeOutlined} color="blue.300" />
              <Heading size="sm" color={headerText}>إعدادات الخط العام</Heading>
            </HStack>
          </CardHeader>
          <CardBody bg="var(--stake-bg-secondary, #1b2b38)">
            <Grid templateColumns={{ base: '1fr', lg: '1fr 1fr' }} gap={6}>
              <GridItem>
                <FormControl>
                  <FormLabel color={subText}>خط النظام العام</FormLabel>
                  <Button onClick={() => setIsSystemFontModalOpen(true)} bg={inputBg} color={inputText} border="1px solid" borderColor={inputBorder} _hover={{ bg: 'rgba(255,255,255,0.06)' }}>
                    {currentFontLabel(tempSettings.fontFamily || 'Cairo')}
                  </Button>
                </FormControl>
              </GridItem>
              <GridItem>
                <FormControl>
                  <FormLabel color={subText}>معاينة الخط</FormLabel>
                  <Box mt="2" p="4" border="1px solid" borderColor={cardBorder} borderRadius="md" bg="var(--stake-bg-card, #0b1a24)" textAlign="center"
                    style={{ fontFamily: `'${tempSettings.fontFamily || 'Cairo'}', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif` }}>
                    <Text color={inputText}>مرحباً بك في نظام إدارة الرواتب والأجور</Text>
                    <Text color={subText}>Welcome to TimePay Management System</Text>
                  </Box>
                </FormControl>
              </GridItem>
            </Grid>
          </CardBody>
        </Card>

        {/* Table Settings */}
        <Card bg={cardBg} border="1px solid" borderColor={cardBorder} borderRadius="2xl" overflow="hidden">
          <CardHeader bg={headerBg} borderBottom="1px solid" borderColor={cardBorder}>
            <Heading size="sm" color={headerText}>إعدادات الجداول</Heading>
          </CardHeader>
          <CardBody bg="var(--stake-bg-secondary, #1b2b38)">
            <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing={4}>
              <FormControl>
                <FormLabel color={subText}>اسم الخط</FormLabel>
                <Button onClick={() => setIsTableFontModalOpen(true)} bg={inputBg} color={inputText} border="1px solid" borderColor={inputBorder} _hover={{ bg: 'rgba(255,255,255,0.06)' }}>
                  {tempSettings.tableFontFamily === 'system' ? 'خط النظام العام' : currentFontLabel(tempSettings.tableFontFamily || 'Cairo')}
                </Button>
              </FormControl>
              <FormControl>
                <FormLabel color={subText}>مقاس الخط: {tempSettings.tableFontSize || 14}px</FormLabel>
                <Slider 
                  min={10} 
                  max={50} 
                  value={tempSettings.tableFontSize || 14} 
                  onChange={(v) => setTempSettings(s => ({ ...s, tableFontSize: v }))}
                  colorScheme="blue"
                >
                  <SliderTrack bg="gray.600">
                    <SliderFilledTrack bg="blue.400" />
                  </SliderTrack>
                  <SliderThumb bg="blue.400" />
                </Slider>
              </FormControl>
              <FormControl>
                <FormLabel color={subText}>وزن الخط: {tempSettings.tableFontWeight || 600}</FormLabel>
                <Slider 
                  min={100} 
                  max={900} 
                  step={100} 
                  value={tempSettings.tableFontWeight || 600} 
                  onChange={(v) => setTempSettings(s => ({ ...s, tableFontWeight: v }))}
                  colorScheme="blue"
                >
                  <SliderTrack bg="gray.600">
                    <SliderFilledTrack bg="blue.400" />
                  </SliderTrack>
                  <SliderThumb bg="blue.400" />
                </Slider>
              </FormControl>
              <FormControl display="flex" alignItems="center">
                <FormLabel mb="0" color={subText}>إظهار المفاتيح الإنجليزية</FormLabel>
                <CSwitch 
                  isChecked={tempSettings.showEnglishKeys !== undefined ? tempSettings.showEnglishKeys : true} 
                  onChange={(e) => setTempSettings(s => ({ ...s, showEnglishKeys: e.target.checked }))}
                  colorScheme="blue"
                />
              </FormControl>
            </SimpleGrid>

            <Divider my="4" borderColor={cardBorder} />
            <Text color={inputText} fontWeight="semibold">معاينة تنسيق الجدول</Text>
            <Box mt="2" border="1px solid" borderColor={cardBorder} borderRadius="md" overflow="hidden">
              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                <thead>
                  <tr style={{ backgroundColor: '#102a3a' }}>
                    {['اسم الموظف', 'الراتب الأساسي', 'القسم'].map((h, idx) => (
                      <th key={idx} style={{ padding: '12px 8px', color: '#e2e8f0', textAlign: 'right', borderBottom: `1px solid ${cardBorder}`, fontFamily: tempSettings.tableFontFamily === 'system' ? `'${tempSettings.fontFamily || 'Cairo'}'` : `'${tempSettings.tableFontFamily || 'Cairo'}'`, fontSize: `${tempSettings.tableFontSize || 14}px`, fontWeight: tempSettings.tableFontWeight || 600 }}>
                        {h}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {[
                    ['أحمد محمد علي', '5,000 ج.م.', 'المحاسبة'],
                    ['فاطمة أحمد حسن', '4,500 ج.م.', 'الموارد البشرية']
                  ].map((row, i) => (
                    <tr key={i} style={{ backgroundColor: i % 2 ? '#0f212e' : '#0b1a24' }}>
                      {row.map((cell, j) => (
                        <td key={j} style={{ padding: '10px 8px', color: '#e2e8f0', borderBottom: `1px solid ${cardBorder}`, fontFamily: tempSettings.tableFontFamily === 'system' ? `'${tempSettings.fontFamily || 'Cairo'}'` : `'${tempSettings.tableFontFamily || 'Cairo'}'`, fontSize: `${tempSettings.tableFontSize || 14}px`, fontWeight: 400 }}>
                          {cell}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </Box>
          </CardBody>
        </Card>

        {/* Save Button */}
        <HStack justify="center" bg="var(--stake-bg-card, #0b1a24)" p="4" borderRadius="xl">
          <Button onClick={saveSettings} isLoading={loading} leftIcon={<Icon as={SaveOutlined} />} bg="var(--stake-primary, #1475e1)" _hover={{ bg: '#0e63c2' }} color="white">
            {loading ? 'جاري الحفظ...' : 'حفظ إعدادات المظهر'}
          </Button>
        </HStack>
      </VStack>

      {/* System Font Modal */}
      <Modal isOpen={isSystemFontModalOpen} onClose={() => setIsSystemFontModalOpen(false)} size="full">
        <ModalOverlay bg="rgba(0,0,0,0.7)" />
        <ModalContent bg={cardBg}>
          <ModalHeader color={headerText}>اختر خط النظام العام</ModalHeader>
          <ModalCloseButton color={headerText} />
          <ModalBody>
            <Box maxH="80vh" overflowY="auto" border="1px solid" borderColor={cardBorder} borderRadius="lg" p="4"
              sx={{
                '::-webkit-scrollbar': { width: '10px' },
                '::-webkit-scrollbar-track': { background: '#0b1a24', borderRadius: '8px' },
                '::-webkit-scrollbar-thumb': { background: '#3e5665', borderRadius: '8px' },
                '::-webkit-scrollbar-thumb:hover': { background: '#4f6f81' }
              }}
            >
              <VStack align="stretch" spacing={3}>
                {arabicFonts.map(f => (
                  <Box
                    key={f.value}
                    p="4"
                    bg={cardBg}
                    border="1px solid"
                    borderColor={cardBorder}
                    borderRadius="lg"
                    cursor="pointer"
                    _hover={{ bg: 'rgba(255,255,255,0.06)' }}
                    onClick={() => { setTempSettings(s => ({ ...s, fontFamily: f.value })); setIsSystemFontModalOpen(false); }}
                  >
                    <HStack justify="space-between" align="center" spacing={4}>
                      <Text fontWeight="bold" color={headerText} fontSize="lg" minW="150px">
                        {f.label}
                      </Text>
                      <Text 
                        fontFamily={f.value}
                        color={inputText}
                        fontSize="xl"
                        lineHeight="1.6"
                        flex="1"
                        textAlign="right"
                      >
                        {f.preview || 'نظام إدارة الرواتب'}
                      </Text>
                    </HStack>
                  </Box>
                ))}
              </VStack>
            </Box>
          </ModalBody>
        </ModalContent>
      </Modal>

      {/* Table Font Modal */}
      <Modal isOpen={isTableFontModalOpen} onClose={() => setIsTableFontModalOpen(false)} size="full">
        <ModalOverlay bg="rgba(0,0,0,0.7)" />
        <ModalContent bg={cardBg}>
          <ModalHeader color={headerText}>اختر خط الجداول</ModalHeader>
          <ModalCloseButton color={headerText} />
          <ModalBody>
            <Box maxH="80vh" overflowY="auto" border="1px solid" borderColor={cardBorder} borderRadius="lg" p="4"
              sx={{
                '::-webkit-scrollbar': { width: '10px' },
                '::-webkit-scrollbar-track': { background: '#0b1a24', borderRadius: '8px' },
                '::-webkit-scrollbar-thumb': { background: '#3e5665', borderRadius: '8px' },
                '::-webkit-scrollbar-thumb:hover': { background: '#4f6f81' }
              }}
            >
              <VStack align="stretch" spacing={3}>
                <Box
                  p="4"
                  bg={cardBg}
                  border="1px solid"
                  borderColor={cardBorder}
                  borderRadius="lg"
                  cursor="pointer"
                  _hover={{ bg: 'rgba(255,255,255,0.06)' }}
                  onClick={() => { setTempSettings(s => ({ ...s, tableFontFamily: 'system' })); setIsTableFontModalOpen(false); }}
                >
                  <HStack justify="space-between" align="center" spacing={4}>
                    <Text fontWeight="bold" color={headerText} fontSize="lg" minW="150px">
                      خط النظام العام
                    </Text>
                    <Text 
                      color={inputText}
                      fontSize="xl"
                      lineHeight="1.6"
                      flex="1"
                      textAlign="right"
                    >
                      نظام إدارة الرواتب
                    </Text>
                  </HStack>
                </Box>
                {arabicFonts.map(f => (
                  <Box
                    key={f.value}
                    p="4"
                    bg={cardBg}
                    border="1px solid"
                    borderColor={cardBorder}
                    borderRadius="lg"
                    cursor="pointer"
                    _hover={{ bg: 'rgba(255,255,255,0.06)' }}
                    onClick={() => { setTempSettings(s => ({ ...s, tableFontFamily: f.value })); setIsTableFontModalOpen(false); }}
                  >
                    <HStack justify="space-between" align="center" spacing={4}>
                      <Text fontWeight="bold" color={headerText} fontSize="lg" minW="150px">
                        {f.label}
                      </Text>
                      <Text 
                        fontFamily={f.value}
                        color={inputText}
                        fontSize="xl"
                        lineHeight="1.6"
                        flex="1"
                        textAlign="right"
                      >
                        {f.preview || 'نظام إدارة الرواتب'}
                      </Text>
                    </HStack>
                  </Box>
                ))}
              </VStack>
            </Box>
          </ModalBody>
        </ModalContent>
      </Modal>
    </Box>
  );
};

export default NewAppearanceSettings;
