import React, { useState } from 'react';
import { getApiUrl } from '../utils/apiUrlHelper';
import {
  Box,
  Heading,
  Text,
  HStack,
  VStack,
  SimpleGrid,
  Button,
  Icon,
  useToast,
  Card,
  CardBody,
  CardHeader,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  TableContainer,
  Badge,
  Progress,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalCloseButton,
  ModalBody,
  ModalFooter,
  FormControl,
  FormLabel,
  Input,
  Select,
  Textarea,
  Center,
  Divider,
  Stat,
  StatLabel,
  StatNumber,
  StatHelpText,
  StatArrow,
  Flex,
  Spacer,
  IconButton,
  Tooltip,
} from '@chakra-ui/react';
import { 
  FiUpload, 
  FiFileText, 
  FiCheckCircle, 
  FiAlertCircle,
  FiRefreshCw,
  FiDownload,
  FiEye,
  FiFile,
  FiDatabase,
  FiUsers,
  FiCalendar,
  FiClock,
  FiX
} from 'react-icons/fi';
import * as XLSX from 'xlsx';

const FingerprintImportTab = () => {
  const toast = useToast();
  const [loading, setLoading] = useState(false);
  const [importProgress, setImportProgress] = useState(0);
  const [importResult, setImportResult] = useState(null);
  const [previewData, setPreviewData] = useState([]);
  const [showPreview, setShowPreview] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [csvData, setCsvData] = useState('');

  // خريطة عناوين الأعمدة إلى مفاتيح النظام القياسية
  const headerMap = {
    'AC-No.': 'ac_no',
    'AC-No': 'ac_no',
    'AC No': 'ac_no',
    'ac_no': 'ac_no',
    'Name': 'name',
    'Employee Name': 'name',
    'employee_name': 'name',
    'Date': 'date',
    'Clock In': 'clock_in',
    'Clock Out': 'clock_out',
    'Late': 'late',
    'Early': 'early',
    'Absent': 'absent',
    'OT Time': 'ot_time',
    'Work Time': 'work_time',
    'Department': 'department',
    'week': 'week',
    'Week': 'week'
  };

  const normalizeHeader = (h) => {
    const key = (h || '').toString().trim();
    return headerMap[key] || key.toLowerCase();
  };

  const toTsvFromRows = (rows, orderedKeys) => {
    const headerLine = orderedKeys.join('\t');
    const dataLines = rows.map(row => orderedKeys.map(k => (row[k] ?? '')).join('\t'));
    return [headerLine, ...dataLines].join('\n');
  };

  const handleFileUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    setSelectedFile(file);
    
    try {
      const lowerName = file.name.toLowerCase();
      if (lowerName.endsWith('.xls') || lowerName.endsWith('.xlsx')) {
        // قراءة ملف اكسل واستخراج البيانات
        const arrayBuffer = await file.arrayBuffer();
        const workbook = XLSX.read(arrayBuffer, { type: 'array' });
        const firstSheetName = workbook.SheetNames[0];
        const sheet = workbook.Sheets[firstSheetName];
        const aoa = XLSX.utils.sheet_to_json(sheet, { header: 1, raw: false });

        if (!aoa || aoa.length === 0) {
          setPreviewData([]);
          setCsvData('');
        } else {
          const rawHeaders = aoa[0];
          const dataRows = aoa.slice(1).filter(r => r && r.some(c => (c ?? '').toString().trim() !== ''));

          const normalizedRows = dataRows.map((row, index) => {
            const obj = {};
            rawHeaders.forEach((h, i) => {
              const key = normalizeHeader(h);
              obj[key] = (row[i] ?? '').toString().trim();
            });
            obj.key = index;
            return obj;
          });

          // ترتيب الأعمدة حسب أعمدة الجدول المستخدمة في المعاينة
          const orderedKeys = ['ac_no','name','date','clock_in','clock_out','late','early','absent','ot_time','work_time','department','week'];
          setPreviewData(normalizedRows.map(r => {
            const o = {};
            orderedKeys.forEach(k => { 
              o[k] = r[k] ?? '';
            });
            return o;
          }));

          // بناء نص TSV ليرسَل إلى الـ API
          const tsv = toTsvFromRows(normalizedRows, orderedKeys);
          setCsvData(tsv);
        }
      } else {
        // ملفات CSV أو نصية
        const data = await file.text();
        setCsvData(data);
        await parseAndPreviewData(data);
      }
      toast({
        title: 'تم رفع الملف',
        description: 'تم رفع الملف بنجاح ويمكنك معاينة البيانات',
        status: 'success',
        duration: 3000,
      });
    } catch (error) {
      toast({
        title: 'خطأ في رفع الملف',
        description: error.message,
        status: 'error',
        duration: 3000,
      });
    }
  };

  const parseAndPreviewData = async (data) => {
    try {
      const lines = data.split('\n').filter(line => line.trim());
      if (lines.length === 0) {
        setPreviewData([]);
        return;
      }
      const delimiter = lines[0].includes('\t') ? '\t' : ',';
      const rawHeaders = lines[0].split(delimiter).map(h => h.trim());
      const headers = rawHeaders.map(normalizeHeader);

      const parsedData = lines.slice(1).map((line, index) => {
        const values = line.split(delimiter).map(v => v.trim());
        const row = {};
        headers.forEach((header, i) => {
          row[header] = values[i] || '';
        });
        row.key = index;
        return row;
      });

      const orderedKeys = ['ac_no','name','date','clock_in','clock_out','late','early','absent','ot_time','work_time','department','week'];
      setPreviewData(parsedData.map(r => {
        const o = {};
        orderedKeys.forEach(k => { 
          o[k] = r[k] ?? '';
        });
        return o;
      }));
    } catch (error) {
      toast({
        title: 'خطأ في تحليل البيانات',
        description: error.message,
        status: 'error',
        duration: 3000,
      });
    }
  };

  const handleImport = async () => {
    try {
      setLoading(true);
      setImportProgress(0);
      
      // محاكاة تقدم الاستيراد
      const progressInterval = setInterval(() => {
        setImportProgress(prev => {
          if (prev >= 90) {
            clearInterval(progressInterval);
            return 90;
          }
          return prev + 10;
        });
      }, 200);

      const response = await fetch(getApiUrl('/api/import_fingerprint_data.php'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          action: 'import_csv_data',
          csv_data: csvData,
          file_name: selectedFile?.name || 'imported_data.csv'
        })
      });

      const result = await response.json();
      clearInterval(progressInterval);
      setImportProgress(100);

      if (result.success) {
        setImportResult(result);
        toast({
          title: 'تم الاستيراد بنجاح',
          description: `تم استيراد ${result.imported_count} سجل بنجاح`,
          status: 'success',
          duration: 5000,
        });
        setCsvData('');
        setPreviewData([]);
        setSelectedFile(null);
      } else {
        toast({
          title: 'فشل في الاستيراد',
          description: result.message,
          status: 'error',
          duration: 5000,
        });
      }
    } catch (error) {
      setImportProgress(0);
      toast({
        title: 'خطأ في استيراد البيانات',
        description: error.message,
        status: 'error',
        duration: 5000,
      });
    } finally {
      setLoading(false);
    }
  };

  const downloadTemplate = () => {
    const templateData = [
      ['ac_no', 'name', 'date', 'clock_in', 'clock_out', 'late', 'early', 'absent', 'ot_time', 'work_time', 'department', 'week'],
      ['1001', 'أحمد محمد', '2024-01-01', '08:00', '17:00', '0', '0', '0', '0', '8', 'IT', 'الاثنين']
    ];
    
    const ws = XLSX.utils.aoa_to_sheet(templateData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Template');
    XLSX.writeFile(wb, 'fingerprint_template.xlsx');
    
    toast({
      title: 'تم تحميل القالب',
      description: 'تم تحميل قالب البيانات بنجاح',
      status: 'success',
      duration: 3000,
    });
  };

  const columns = [
    { key: 'ac_no', label: 'كود البصمة' },
    { key: 'name', label: 'اسم الموظف' },
    { key: 'date', label: 'التاريخ' },
    { key: 'clock_in', label: 'وقت الدخول' },
    { key: 'clock_out', label: 'وقت الخروج' },
    { key: 'late', label: 'التأخير' },
    { key: 'early', label: 'الانصراف المبكر' },
    { key: 'absent', label: 'الغياب' },
    { key: 'ot_time', label: 'الساعات الإضافية' },
    { key: 'work_time', label: 'ساعات العمل' },
    { key: 'department', label: 'القسم' },
    { key: 'week', label: 'اليوم' },
  ];

  return (
    <Box className="stake-card" overflow="hidden">
      <Box p="6">
        {/* Header Section */}
        <Box mb="8">
          <HStack spacing="8" align="flex-start">
            <VStack align="flex-start" spacing="2" flex="1" minW="300px">
              <Heading size="lg" className="stake-heading-3">
                استيراد بيانات البصمة
              </Heading>
              <Text color="gray.600" fontSize="lg">
                استيراد بيانات الحضور والانصراف من ملفات Excel أو CSV
              </Text>
            </VStack>
            
            {/* Action Buttons */}
            <HStack spacing="3">
              <Button
                leftIcon={<FiDownload />}
                className="stake-btn-secondary"
                size="md"
                borderRadius="xl"
                onClick={downloadTemplate}
              >
                تحميل القالب
              </Button>
              
              <Button
                leftIcon={<FiRefreshCw />}
                className="stake-btn"
                size="md"
                borderRadius="xl"
                onClick={() => {
                  setCsvData('');
                  setPreviewData([]);
                  setSelectedFile(null);
                  setImportResult(null);
                  setImportProgress(0);
                }}
              >
                إعادة تعيين
              </Button>
            </HStack>
          </HStack>
        </Box>

        {/* Stats Overview */}
        <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing="6" mb="8">
          <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
            <CardBody p="6">
              <VStack align="flex-start" spacing="2">
                <Text className="stake-text-secondary" fontSize="sm" fontWeight="500">إجمالي السجلات</Text>
                <Text color="white" fontSize="2xl" fontWeight="bold">{previewData.length}</Text>
                <Text className="stake-text-secondary" fontSize="xs">في المعاينة</Text>
              </VStack>
            </CardBody>
          </Card>

          <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
            <CardBody p="6">
              <VStack align="flex-start" spacing="2">
                <Text className="stake-text-secondary" fontSize="sm" fontWeight="500">الملف المحدد</Text>
                <Text color="white" fontSize="lg" fontWeight="600" noOfLines={1}>
                  {selectedFile ? selectedFile.name : 'لا يوجد'}
                </Text>
                <Text className="stake-text-secondary" fontSize="xs">
                  {selectedFile ? `${(selectedFile.size / 1024).toFixed(1)} KB` : 'اختر ملف'}
                </Text>
              </VStack>
            </CardBody>
          </Card>

          <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
            <CardBody p="6">
              <VStack align="flex-start" spacing="2">
                <Text className="stake-text-secondary" fontSize="sm" fontWeight="500">حالة الاستيراد</Text>
                <Text color={importResult ? "green.400" : "gray.400"} fontSize="lg" fontWeight="600">
                  {importResult ? 'مكتمل' : 'في الانتظار'}
                </Text>
                <Text className="stake-text-secondary" fontSize="xs">
                  {importResult ? `${importResult.imported_count} سجل` : 'لم يتم الاستيراد'}
                </Text>
              </VStack>
            </CardBody>
          </Card>

          <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
            <CardBody p="6">
              <VStack align="flex-start" spacing="2">
                <Text className="stake-text-secondary" fontSize="sm" fontWeight="500">التقدم</Text>
                <Text color="white" fontSize="lg" fontWeight="bold">{importProgress}%</Text>
                <Progress value={importProgress} size="sm" colorScheme="blue" w="full" />
              </VStack>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* Upload Section */}
        <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)" mb="8">
          <CardHeader>
            <HStack spacing="4">
              <Icon as={FiUpload} boxSize="6" color="blue.400" />
              <VStack align="flex-start" spacing="1">
                <Heading size="md" color="white">رفع ملف البيانات</Heading>
                <Text className="stake-text-secondary" fontSize="sm">
                  اختر ملف Excel أو CSV يحتوي على بيانات الحضور والانصراف
                </Text>
              </VStack>
            </HStack>
          </CardHeader>
          <CardBody>
            <VStack spacing="6">
              <FormControl>
                <FormLabel color="white" mb="3">اختر الملف</FormLabel>
                <Input
                  type="file"
                  accept=".csv,.xlsx,.xls"
                  onChange={handleFileUpload}
                  className="stake-input"
                  borderRadius="xl"
                  border="2px solid"
                  borderColor="var(--stake-border-primary)"
                  bg="white"
                  color="black"
                  _focus={{
                    borderColor: "var(--stake-border-accent)",
                    boxShadow: "0 0 0 3px rgba(20, 117, 225, 0.1)"
                  }}
                  _hover={{
                    borderColor: "var(--stake-border-accent)"
                  }}
                />
              </FormControl>

              {selectedFile && (
                <Alert status="success" borderRadius="xl" bg="green.50" border="1px solid" borderColor="green.200">
                  <AlertIcon color="green.500" />
                  <Box>
                    <AlertTitle color="green.800">تم رفع الملف بنجاح!</AlertTitle>
                    <AlertDescription color="green.700">
                      {selectedFile.name} - {(selectedFile.size / 1024).toFixed(1)} KB
                    </AlertDescription>
                  </Box>
                </Alert>
              )}

              {previewData.length > 0 && (
                <HStack spacing="3" w="full" justify="center">
                  <Button
                    leftIcon={<FiEye />}
                    className="stake-btn-secondary"
                    size="md"
                    borderRadius="xl"
                    onClick={() => setShowPreview(true)}
                  >
                    معاينة البيانات
                  </Button>
                  
                  <Button
                    leftIcon={<FiUpload />}
                    className="stake-btn-success"
                    size="md"
                    borderRadius="xl"
                    onClick={handleImport}
                    isLoading={loading}
                    loadingText="جاري الاستيراد..."
                  >
                    استيراد البيانات
                  </Button>
                </HStack>
              )}
            </VStack>
          </CardBody>
        </Card>

        {/* Import Progress */}
        {loading && (
          <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)" mb="8">
            <CardBody p="6">
              <VStack spacing="4">
                <HStack spacing="3">
                  <Icon as={FiRefreshCw} boxSize="5" color="blue.400" className={loading ? "animate-spin" : ""} />
                  <Text color="white" fontSize="lg" fontWeight="600">جاري استيراد البيانات...</Text>
                </HStack>
                <Progress 
                  value={importProgress} 
                  size="lg" 
                  colorScheme="blue" 
                  borderRadius="full"
                  w="full"
                />
                <Text className="stake-text-secondary" fontSize="sm">{importProgress}% مكتمل</Text>
              </VStack>
            </CardBody>
          </Card>
        )}

        {/* Import Result */}
        {importResult && (
          <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
            <CardBody p="6">
              <VStack spacing="4">
                <HStack spacing="3">
                  <Icon as={FiCheckCircle} boxSize="6" color="green.400" />
                  <VStack align="flex-start" spacing="1">
                    <Heading size="md" color="white">تم الاستيراد بنجاح</Heading>
                    <Text className="stake-text-secondary" fontSize="sm">
                      تم استيراد {importResult.imported_count} سجل بنجاح
                    </Text>
                  </VStack>
                </HStack>
                
                <SimpleGrid columns={{ base: 1, md: 3 }} spacing="4" w="full">
                  <Box p="4" bg="var(--stake-bg-secondary, #182935)" borderRadius="lg" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
                    <VStack spacing="2">
                      <Text color="green.400" fontSize="2xl" fontWeight="bold">{importResult.imported_count}</Text>
                      <Text className="stake-text-secondary" fontSize="sm">سجلات مستوردة</Text>
                    </VStack>
                  </Box>
                  <Box p="4" bg="var(--stake-bg-secondary, #182935)" borderRadius="lg" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
                    <VStack spacing="2">
                      <Text color="blue.400" fontSize="2xl" fontWeight="bold">{importResult.updated_count || 0}</Text>
                      <Text className="stake-text-secondary" fontSize="sm">سجلات محدثة</Text>
                    </VStack>
                  </Box>
                  <Box p="4" bg="var(--stake-bg-secondary, #182935)" borderRadius="lg" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
                    <VStack spacing="2">
                      <Text color="orange.400" fontSize="2xl" fontWeight="bold">{importResult.skipped_count || 0}</Text>
                      <Text className="stake-text-secondary" fontSize="sm">سجلات متجاهلة</Text>
                    </VStack>
                  </Box>
                </SimpleGrid>
              </VStack>
            </CardBody>
          </Card>
        )}
      </Box>

      {/* Preview Modal */}
      <Modal isOpen={showPreview} onClose={() => setShowPreview(false)} size="6xl">
        <ModalOverlay bg="rgba(0, 0, 0, 0.7)" backdropFilter="blur(8px)" />
        <ModalContent 
          bg="var(--stake-bg-primary)" 
          border="none" 
          borderRadius="3xl" 
          boxShadow="0 25px 50px -12px rgba(0, 0, 0, 0.25)" 
          overflow="hidden"
        >
          <ModalHeader 
            bg="var(--stake-bg-primary, #0f212e)" 
            color="white"
            borderRadius="24px 24px 0 0" 
            p="4" 
            position="relative" 
            boxShadow="0 4px 20px rgba(0, 0, 0, 0.4)"
          >
            <HStack justify="space-between" align="center" w="100%">
              <HStack spacing="3">
                <Icon as={FiEye} boxSize="5" />
                <Text fontSize="md" fontWeight="bold">معاينة البيانات</Text>
              </HStack>
              <ModalCloseButton 
                color="white"
                bg="rgba(255, 255, 255, 0.1)"
                borderRadius="full"
                size="md"
                _hover={{
                  bg: "rgba(255, 255, 255, 0.2)",
                  transform: "scale(1.1)"
                }}
                _active={{
                  transform: "scale(0.95)"
                }}
              />
            </HStack>
          </ModalHeader>
          
          <ModalBody p="8">
            <TableContainer maxH="60vh" overflowY="auto" className="stake-table main-content">
              <Table variant="simple" size="md" className="stake-table main-content">
                <Thead position="sticky" top="0" bg="var(--stake-bg-primary)" zIndex="1" boxShadow="var(--stake-shadow-sm)">
                  <Tr>
                    {columns.map((col) => (
                      <Th key={col.key}>
                        <Text color="var(--stake-text-primary)" fontWeight="600">{col.label}</Text>
                      </Th>
                    ))}
                  </Tr>
                </Thead>
                <Tbody>
                  {previewData.map((row, index) => (
                    <Tr key={index} _hover={{ bg: "rgba(255, 255, 255, 0.05)" }}>
                      {columns.map((col) => (
                        <Td key={col.key}>
                          <Text color="var(--stake-text-secondary)" fontSize="sm">
                            {row[col.key] || '-'}
                          </Text>
                        </Td>
                      ))}
                    </Tr>
                  ))}
                </Tbody>
              </Table>
            </TableContainer>
          </ModalBody>
          
          <ModalFooter 
            bg="var(--stake-bg-primary, #0f212e)"
            borderRadius="0 0 24px 24px"
            p="4"
            boxShadow="0 -4px 20px rgba(0, 0, 0, 0.4)"
          >
            <HStack spacing="4" w="full" justify="flex-end">
              <Button 
                variant="ghost" 
                onClick={() => setShowPreview(false)}
                color="white"
                _hover={{ bg: "rgba(255, 255, 255, 0.1)" }}
                borderRadius="xl"
              >
                إغلاق
              </Button>
              <Button 
                leftIcon={<FiUpload />}
                className="stake-btn-success"
                onClick={() => {
                  setShowPreview(false);
                  handleImport();
                }}
                isLoading={loading}
                borderRadius="xl"
              >
                استيراد البيانات
              </Button>
            </HStack>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Box>
  );
};

export default FingerprintImportTab;