import React, { useState, useEffect } from 'react';
import { getApiUrl } from '../utils/apiUrlHelper';
import dayjs from 'dayjs';
import { useLocation, useNavigate } from 'react-router-dom';
import {
  Box,
  Flex,
  VStack,
  HStack,
  Text,
  Heading,
  Button,
  IconButton,
  Avatar,
  Badge,
  Tooltip,
  useDisclosure,
  Drawer,
  DrawerBody,
  DrawerHeader,
  DrawerOverlay,
  DrawerContent,
  DrawerCloseButton,
  Menu,
  MenuButton,
  MenuList,
  MenuItem,
  MenuDivider,
  useColorModeValue,
  useToast,
  Image,
  Divider,
  Circle,
  Icon,
  Container,
  Spacer,
  Show,
  Hide,
  Stack,
  useBreakpointValue,
  Card,
  CardBody,
  SimpleGrid,
  Modal,
  ModalOverlay,
  ModalContent,
  ModalHeader,
  ModalFooter,
  ModalBody,
  ModalCloseButton,
  FormControl,
  FormLabel,
  Input,
} from '@chakra-ui/react';
import {
  FiMenu,
  FiBell,
  FiUser,
  FiLogOut,
  FiSettings,
  FiChevronDown,
  FiChevronLeft,
  FiChevronRight,
  FiHome,
  FiUsers,
  FiBriefcase,
  FiCalendar,
  FiDollarSign,
  FiZap,
  FiShield,
  FiHeadphones,
  FiBarChart,
  FiPieChart,
  FiActivity,
  FiTarget,
  FiStar,
  FiGift,
  FiFileText,
  FiMessageCircle,
  FiHexagon,
  FiGlobe,
  FiHeart,
  FiUserPlus,
  FiPlus,
  FiSearch,
  FiFilter,
  FiMoreVertical,
  FiSun,
  FiMoon,
  FiTrendingUp,
  FiTrendingDown,
  FiClock,
  FiCheckCircle,
  FiAlertCircle,
  FiXCircle,
  FiPause,
  FiDatabase,
  FiCode,
  FiTool,
} from 'react-icons/fi';
import { useSettings } from '../contexts/SettingsContext';
import { loadEmployees } from '../utils/apiHelper';

const PremiumLayoutWrapper = ({ children, user, onLogout }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const { settings } = useSettings();
  const toast = useToast();
  
  // Localized date (Arabic)
  const todayText = new Date().toLocaleDateString('ar-EG', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  });
  // Employees quick stat
  const [employeesCount, setEmployeesCount] = useState(null);
  const [dashboardStats, setDashboardStats] = useState({
    totalEmployees: 0,
    todayAttendance: 0,
    monthlySalary: 0,
    workHours: 0
  });
  const [weeklyHeaderStats, setWeeklyHeaderStats] = useState({ totalWorkers: 0, totalSalary: 0, bonus: 0 });
  const [monthlyHeaderStats, setMonthlyHeaderStats] = useState({ totalEmployees: 0, totalSalary: 0, bonus: 0 });
  const [systemVersion, setSystemVersion] = useState(null);
  
  // Password change modal
  const { isOpen: isPasswordModalOpen, onOpen: onPasswordModalOpen, onClose: onPasswordModalClose } = useDisclosure();
  const [passwordData, setPasswordData] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  useEffect(() => {
    const fetchEmployeesCount = async () => {
      try {
        const result = await loadEmployees();
        if (result && result.success && Array.isArray(result.data)) {
          setEmployeesCount(result.data.length);
        } else if (Array.isArray(result)) {
          // In case apiHelper returns array directly in some scenarios
          setEmployeesCount(result.length);
        } else {
          setEmployeesCount(null);
        }
      } catch (e) {
        setEmployeesCount(null);
      }
    };
    fetchEmployeesCount();
  }, []);

  // Fetch system version
  useEffect(() => {
    const fetchSystemVersion = async () => {
      try {
        const response = await fetch(getApiUrl('/api/update_system.php?action=check'));
        const data = await response.json();
        if (data.success && data.currentVersion) {
          setSystemVersion(data.currentVersion);
        }
      } catch (e) {
        console.log('Could not fetch system version');
      }
    };
    fetchSystemVersion();
  }, []);

  // Load dashboard stats
  useEffect(() => {
    const fetchDashboardStats = async () => {
      try {
        // Fetch employees count
        const employeesResult = await loadEmployees();
        const totalEmployees = employeesResult?.success ? employeesResult.data.length : 
                              Array.isArray(employeesResult) ? employeesResult.length : 0;

        // Fetch today's attendance
        const today = new Date().toISOString().split('T')[0];
        const attendanceResponse = await fetch(getApiUrl('/api/simple_attendance_api.php'), {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'get_attendance_records',
            start_date: today,
            end_date: today
          })
        });
        const attendanceData = await attendanceResponse.json();
        const todayAttendance = attendanceData?.success ? attendanceData.data.length : 0;

        // Calculate monthly salary (simplified)
        const monthlySalary = totalEmployees * 5000; // Average salary

        // Calculate work hours (simplified)
        const workHours = todayAttendance * 8; // 8 hours per employee

        setDashboardStats({
          totalEmployees,
          todayAttendance,
          monthlySalary,
          workHours
        });
      } catch (error) {
        console.error('Error fetching dashboard stats:', error);
      }
    };

    if (location.pathname === '/') {
      fetchDashboardStats();
    }
  }, [location.pathname]);

  // Header stats for weekly/monthly salary pages
  useEffect(() => {
    const fetchWeekly = async () => {
      try {
        const start = dayjs().startOf('week').format('YYYY-MM-DD');
        const end = dayjs().endOf('week').format('YYYY-MM-DD');
        const resp = await fetch('/api/unified_salary_api_v2.php', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'get_weekly_salary_data', start_date: start, end_date: end, salary_type: 'Weekly' })
        });
        const text = await resp.text();
        let json; try { json = JSON.parse(text); } catch { json = { success: false, data: [] }; }
        if (json.success && Array.isArray(json.data)) {
          const totalWorkers = json.data.length;
          const totalSalary = json.data.reduce((s, r) => s + (parseFloat(r.net_weekly_amount) || 0), 0);
          const bonus = json.data.reduce((s, r) => s + (parseFloat(r.attendance_bonus) || 0), 0);
          setWeeklyHeaderStats({ totalWorkers, totalSalary, bonus });
        } else {
          setWeeklyHeaderStats({ totalWorkers: 0, totalSalary: 0, bonus: 0 });
        }
      } catch {
        setWeeklyHeaderStats({ totalWorkers: 0, totalSalary: 0, bonus: 0 });
      }
    };
    const fetchMonthly = async () => {
      try {
        const start = dayjs().startOf('month').format('YYYY-MM-DD');
        const end = dayjs().endOf('month').format('YYYY-MM-DD');
        const resp = await fetch('/api/unified_salary_api_v2.php', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ action: 'get_monthly_salary_data', start_date: start, end_date: end, salary_type: 'Monthly' })
        });
        const text = await resp.text();
        let json; try { json = JSON.parse(text); } catch { json = { success: false, data: [] }; }
        if (json.success && Array.isArray(json.data)) {
          const totalEmployees = json.data.length;
          const totalSalary = json.data.reduce((s, r) => s + (parseFloat(r.net_monthly_amount) || 0), 0);
          const bonus = json.data.reduce((s, r) => s + (parseFloat(r.special_bonus) || 0), 0);
          setMonthlyHeaderStats({ totalEmployees, totalSalary, bonus });
        } else {
          setMonthlyHeaderStats({ totalEmployees: 0, totalSalary: 0, bonus: 0 });
        }
      } catch {
        setMonthlyHeaderStats({ totalEmployees: 0, totalSalary: 0, bonus: 0 });
      }
    };

    if (location.pathname === '/weekly-salary') fetchWeekly();
    if (location.pathname === '/monthly-salary') fetchMonthly();
  }, [location.pathname]);
  
  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const { isOpen: isMobileMenuOpen, onOpen: onMobileMenuOpen, onClose: onMobileMenuClose } = useDisclosure();
  
  // Responsive values
  const sidebarWidth = useBreakpointValue({ base: '280px', md: isSidebarCollapsed ? '60px' : '280px' });
  const isMobile = useBreakpointValue({ base: true, lg: false });

  const menuItems = [
    {
      key: '/',
      icon: FiHome,
      label: 'الرئيسية',
      color: '#FF6B6B',
      bgGradient: 'linear(135deg, #FF6B6B 0%, #FF8E8E 100%)',
    },
    {
      key: '/unified-employees',
      icon: FiUsers,
      label: 'الموظفين',
      color: '#4ECDC4',
      bgGradient: 'linear(135deg, #4ECDC4 0%, #6EDDD6 100%)',
    },
    {
      key: '/departments',
      icon: FiBriefcase,
      label: 'الأقسام',
      color: '#45B7D1',
      bgGradient: 'linear(135deg, #45B7D1 0%, #6BC5D8 100%)',
    },
    {
      key: '/unified-attendance',
      icon: FiCalendar,
      label: 'الحضور والانصراف',
      color: '#96CEB4',
      bgGradient: 'linear(135deg, #96CEB4 0%, #A8D5C1 100%)',
    },
    {
      key: '/weekly-salary',
      icon: FiCalendar,
      label: 'الراتب الأسبوعي',
      color: '#81C784',
      bgGradient: 'linear(135deg, #81C784 0%, #A5D6A7 100%)',
    },
    {
      key: '/monthly-salary',
      icon: FiCalendar,
      label: 'الراتب الشهري',
      color: '#BA68C8',
      bgGradient: 'linear(135deg, #BA68C8 0%, #CE93D8 100%)',
    },
    {
      key: '/advances',
      icon: FiDollarSign,
      label: 'السلف',
      color: '#FFA726',
      bgGradient: 'linear(135deg, #FFA726 0%, #FFB74D 100%)',
    },
    {
      key: '/dynamic-system-manager',
      icon: FiZap,
      label: 'أعمدة الرواتب',
      color: '#DDA0DD',
      bgGradient: 'linear(135deg, #DDA0DD 0%, #E6B8E6 100%)',
    },
    {
      key: '/fingerprint-management',
      icon: FiShield,
      label: 'إدارة البصمة',
      color: '#F8B500',
      bgGradient: 'linear(135deg, #F8B500 0%, #FAC733 100%)',
    },
    {
      key: '/system-settings',
      label: 'الإعدادات',
      icon: FiSettings,
      color: '#A8A8A8',
      bgGradient: 'linear(135deg, #A8A8A8 0%, #C0C0C0 100%)',
    },
  ];


  useEffect(() => {
    // Load notifications
    setNotifications([
      { id: 1, title: 'طلب إجازة جديد', time: 'منذ 5 دقائق', unread: true, type: 'leave' },
      { id: 2, title: 'تأخير في الحضور', time: 'منذ 15 دقيقة', unread: true, type: 'attendance' },
      { id: 3, title: 'تم إضافة موظف جديد', time: 'منذ ساعة', unread: false, type: 'employee' },
    ]);
  }, []);

  const toggleSidebar = () => {
    setIsSidebarCollapsed(!isSidebarCollapsed);
  };

  const handleMenuClick = (path) => {
    navigate(path);
    onMobileMenuClose();
  };

  const handleLogout = () => {
    onLogout();
    toast({
      title: 'تم تسجيل الخروج بنجاح',
      status: 'success',
      duration: 3000,
      isClosable: true,
    });
  };

  // Handle password change
  const handlePasswordChange = async () => {
    if (!passwordData.currentPassword || !passwordData.newPassword || !passwordData.confirmPassword) {
      toast({
        title: 'خطأ',
        description: 'يرجى ملء جميع الحقول',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
      return;
    }

    if (passwordData.newPassword !== passwordData.confirmPassword) {
      toast({
        title: 'خطأ',
        description: 'كلمة المرور الجديدة غير متطابقة',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
      return;
    }

    if (passwordData.newPassword.length < 6) {
      toast({
        title: 'خطأ',
        description: 'كلمة المرور يجب أن تكون 6 أحرف على الأقل',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
      return;
    }

    try {
      // Here you would make an API call to change the password
      // For now, we'll just show a success message
      toast({
        title: 'تم بنجاح',
        description: 'تم تغيير كلمة المرور بنجاح',
        status: 'success',
        duration: 3000,
        isClosable: true,
      });
      
      // Reset form and close modal
      setPasswordData({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
      });
      onPasswordModalClose();
    } catch (error) {
      toast({
        title: 'خطأ',
        description: 'حدث خطأ أثناء تغيير كلمة المرور',
        status: 'error',
        duration: 3000,
        isClosable: true,
      });
    }
  };

  const getNotificationIcon = (type) => {
    switch (type) {
      case 'leave': return FiClock;
      case 'attendance': return FiAlertCircle;
      case 'employee': return FiCheckCircle;
      default: return FiBell;
    }
  };

  const SidebarContent = ({ isMobile = false }) => {
    return (
    <VStack
      spacing="0"
      h="100vh"
      className="stake-sidebar"
      borderRight={isMobile ? "none" : "1px solid"}
      borderColor="#2f4553"
      bg="linear-gradient(180deg, #0f212e 0%, #0a1820 100%)"
      position="relative"
      boxShadow={isMobile ? "none" : "0 0 40px rgba(0,0,0,0.3)"}
      overflow="hidden"
    >
      {/* Background Pattern */}
      <Box
        position="absolute"
        top="0"
        left="0"
        right="0"
        bottom="0"
        opacity="0. 1"
        bgImage="url('data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iNjAiIGhlaWdodD0iNjAiIHZpZXdCb3g9IjAgMCA2MCA2MCIgeG1sbnM9Imh0dHA6Ly93d3cudzMub3JnLzIwMDAvc3ZnIj48ZyBmaWxsPSJub25lIiBmaWxsLXJ1bGU9ImV2ZW5vZGQiPjxnIGZpbGw9IiNmZmZmZmYiIGZpbGwtb3BhY2l0eT0iMC4xIj48Y2lyY2xlIGN4PSIzMCIgY3k9IjMwIiByPSIyIi8+PC9nPjwvZz48L3N2ZyUzR')"
        zIndex="0"
      />

      {/* Sidebar Header */}
      <Box
        p={isSidebarCollapsed && !isMobile ? "4" : "6"}
        w="full"
        position="relative"
        zIndex="1"
      >
        <VStack spacing="4" align="center">
          {(!isSidebarCollapsed || isMobile) && (
            <>
              <VStack spacing="2" align="center">
                <HStack spacing="2" align="center">
                  <Hide below="lg">
                    <IconButton
                      icon={<FiMenu />}
                      size="xs"
                      variant="ghost"
                      aria-label={isSidebarCollapsed ? 'توسيع الشريط الجانبي' : 'طي الشريط الجانبي'}
                      onClick={toggleSidebar}
                      bg="transparent"
                      color="#d5dceb"
                      _hover={{ bg: '#1a2c38', color: 'white' }}
                    />
                  </Hide>
                  <Text 
                    fontSize="md" 
                    fontWeight="bold" 
                    color="#d5dceb" 
                    textAlign="center"
                    whiteSpace="nowrap"
                  >
                    {settings.systemName}
                    {systemVersion && (
                      <Text 
                        as="sup" 
                        fontSize="9px" 
                        color="#63b3ed" 
                        fontWeight="normal"
                        mr="1"
                      >
                        v{systemVersion}
                      </Text>
                    )}
                  </Text>
                </HStack>
              </VStack>
            </>
          )}

          {/* Collapsed sidebar toggle button */}
          {isSidebarCollapsed && !isMobile && (
            <Hide below="lg">
              <IconButton
                icon={<FiMenu />}
                size="sm"
                variant="ghost"
                aria-label="توسيع الشريط الجانبي"
                onClick={toggleSidebar}
                bg="transparent"
                color="var(--color-grey-100)"
                _hover={{ bg: 'var(--color-grey-600)', color: 'var(--color-white)' }}
              />
            </Hide>
          )}
          
        </VStack>
      </Box>

      {/* Navigation Menu - Stake.com Style */}
      <Box flex="1" overflowY="auto" p={isSidebarCollapsed && !isMobile ? "2" : "5"}>
        {isSidebarCollapsed && !isMobile ? (
          <VStack spacing="2" align="center">
            {menuItems.map((item, index) => {
              const Icon = item.icon;
              const isActive = location.pathname === item.key;
              
              return (
                <Tooltip
                  key={item.key}
                  label={item.label}
                  placement="right"
                  hasArrow
                  bg="#1a2c38"
                  color="white"
                  border="1px solid"
                  borderColor="#2f4553"
                >
                  <IconButton
                    icon={<Icon size="20" />}
                    variant="ghost"
                    size="md"
                    bg="transparent"
                    color="#b1bad3"
                    borderRadius="8px"
                    w="40px"
                    h="40px"
                    aria-current={isActive ? "page" : undefined}
                    onClick={() => handleMenuClick(item.key)}
                    _hover={{
                      bg: 'rgba(255, 255, 255, 0.05)',
                      color: 'white',
                    }}
                    _active={{
                      bg: 'rgba(255, 255, 255, 0.05)',
                      color: 'white',
                    }}
                    sx={{
                      '&:hover': {
                        backgroundColor: 'rgba(255, 255, 255, 0.05) !important',
                        color: 'white !important',
                      },
                      '&:active': {
                        backgroundColor: 'rgba(255, 255, 255, 0.05) !important',
                        color: 'white !important',
                      }
                    }}
                  />
                </Tooltip>
              );
            })}
          </VStack>
        ) : (
          <Box bg="transparent" borderRadius="0" overflow="hidden" w="full">
            <VStack spacing="0" align="stretch">
              {menuItems.map((item, index) => {
                const Icon = item.icon;
                const isActive = location.pathname === item.key;
                
                return (
                  <Tooltip
                    key={item.key}
                    label=""
                    placement="left"
                    hasArrow
                  >
                    <Button
                      leftIcon={<Icon size="20" />}
                      variant="ghost"
                      justifyContent="flex-start"
                      h="44px"
                      fontSize="sm"
                      fontWeight="600"
                      bg="transparent"
                      color="#b1bad3"
                      borderRadius="0"
                      w="full"
                      minW="full"
                      border="none"
                      px="16px"
                      py="8px"
                      position="relative"
                      aria-current={isActive ? "page" : undefined}
                      _hover={{
                        bg: 'rgba(255, 255, 255, 0.05)',
                        color: 'white',
                        transform: 'none',
                        boxShadow: 'none',
                        borderRadius: '0',
                      }}
                      _active={{
                        bg: 'rgba(255, 255, 255, 0.05)',
                        color: 'white',
                        borderRadius: '0',
                      }}
                    _before={isActive ? {
                      content: '""',
                      position: 'absolute',
                      left: '0',
                      top: '0',
                      bottom: '0',
                      width: '3px',
                      bg: '#3b82f6',
                      zIndex: '1'
                    } : {}}
                    transition="all 0.2s ease"
                    overflow="hidden"
                    boxShadow="none"
                    onClick={() => handleMenuClick(item.key)}
                      sx={{
                        '&:hover': {
                          backgroundColor: 'rgba(255, 255, 255, 0.05) !important',
                          color: 'white !important',
                          borderRadius: '0 !important',
                        },
                        '&:active': {
                          backgroundColor: 'rgba(255, 255, 255, 0.05) !important',
                          color: 'white !important',
                          borderRadius: '0 !important',
                        }
                      }}
                  >
                    {item.label}
                  </Button>
                </Tooltip>
              );
            })}
          </VStack>
        </Box>
        )}
      </Box>

    </VStack>
    );
  };

  return (
    <Box minH="100vh" className="stake-main-content" bg="var(--stake-bg-secondary, #1a2c38)" color="var(--stake-text-primary, #d5dceb)">
      <Flex>
        {/* Desktop Sidebar */}
        <Hide below="lg">
          <Box
            w={sidebarWidth}
            h="100vh"
            position="fixed"
            right="0"
            top="0"
            zIndex="10"
            transition="width 0.3s ease"
            overflow="hidden"
            className="stake-sidebar"
            bg="linear-gradient(-90deg, #13202b 0%, #1a2c38 100%)"
            borderLeft="1px solid #2f4553"
          >
            <SidebarContent />
          </Box>
        </Hide>

        {/* Main Content Area */}
        <Box
          flex="1"
          mr={{ base: "0", lg: sidebarWidth }}
          minH="100vh"
          transition="margin 0.3s ease"
        
        >
          {/* Header */}
          <Box
            className="stake-header"
            bg="linear-gradient(90deg, #0f212e 0%, #1a2c38 100%)"
            borderBottom="1px solid #2f4553"
            px="4"
            py="2"
            position="sticky"
            top="0"
            zIndex="5"
          >
            <Flex align="center" justify="space-between" h="56px" position="relative">
              {/* Left Side - Mobile Menu */}
              <HStack spacing="3" flex="1">
                <Show below="lg">
                  <IconButton
                    icon={<FiMenu />}
                    variant="ghost"
                    onClick={onMobileMenuOpen}
                    aria-label="فتح القائمة"
                    size="md"
                    className="stake-btn-secondary"
                    _hover={{ bg: 'var(--stake-bg-hover)', transform: 'scale(1.05)' }}
                    borderRadius="xl"
                    color="var(--stake-text-primary)"
                  />
                </Show>
              </HStack>

              {/* Center - Company Logo, Name and Date */}
              <HStack 
                spacing="3" 
                align="center" 
                position="absolute" 
                left="50%" 
                transform="translateX(-50%)"
              >
                  <HStack spacing="3">
                    {/* Company Logo */}
                    {settings.companyLogo ? (
                      <Image
                        src={settings.companyLogo}
                        alt="Company Logo"
                        w="32px"
                        h="32px"
                        borderRadius="full"
                        border="2px solid"
                        borderColor="var(--stake-border-primary)"
                       boxShadow="var(--stake-shadow-lg)"
                      />
                    ) : (
                      <Circle size="8" bg="var(--stake-primary)" color="white">
                        <Icon as={FiUsers} boxSize="4" />
                      </Circle>
                    )}
                    <Text fontSize="md" fontWeight="700" color="var(--stake-text-primary)">
                      {settings.companyName || 'TimePay'}
                    </Text>
                  </HStack>
                  <Divider orientation="vertical" h="20px" borderColor="var(--stake-border-primary)" />
                  <Text fontSize="xs" color="var(--stake-text-secondary)">
                    {todayText}
                  </Text>
                  






                  
              </HStack>

              {/* Right Side - User Menu */}
              <HStack spacing="4">

                {/* User Menu */}
                <Menu>
                  <MenuButton
                    as={IconButton}
                    icon={<FiUser />}
                    variant="ghost"
                    aria-label="قائمة الإدمن"
                    size="lg"
                    color="var(--stake-text-primary)"
                  />
                  <MenuList 
                    bg="white" 
                    boxShadow="0 10px 40px rgba(0, 0, 0, 0.15), 0 4px 20px rgba(0, 0, 0, 0.1)" 
                    borderRadius="16px" 
                    border="none"
                    p="8px"
                    minW="200px"
                    mt="8px"
                  >
                    {/* Header */}
                    <Box p="12px 16px" borderBottom="1px solid" borderColor="gray.100">
                      <VStack spacing="1" align="flex-start">
                        <Text fontSize="sm" fontWeight="600" color="gray.800">
                          {user?.name || 'مدير النظام'}
                        </Text>
                        <Text fontSize="xs" color="gray.500">
                          {user?.role || 'مدير النظام'}
                       
                        </Text>
                      </VStack>
                    </Box>
                    
                    {/* Menu Items */}
                    <Box p="4px">
                      <MenuItem 
                        icon={<FiUser size="16" />} 
                        onClick={onPasswordModalOpen}
                        _hover={{ 
                          bg: 'blue.50', 
                          color: 'blue.600',
                          transform: 'translateX(2px)'
                        }} 
                        borderRadius="8px" 
                        mb="2px" 
                        color="gray.700"
                        fontSize="sm"
                        fontWeight="500"
                        transition="all 0.2s ease"
                      >
                        الملف الشخصي
                      </MenuItem>
                      
                      <MenuItem 
                        icon={<FiSettings size="16" />} 
                        onClick={() => navigate('/system-settings')}
                        _hover={{ 
                          bg: 'gray.50', 
                          color: 'gray.700',
                          transform: 'translateX(2px)'
                        }} 
                        borderRadius="8px" 
                        mb="2px" 
                        color="gray.700"
                        fontSize="sm"
                        fontWeight="500"
                        transition="all 0.2s ease"
                      >
                        الإعدادات
                      </MenuItem>
                      
                      <MenuDivider borderColor="gray.200" my="4px" />
                      
                      <MenuItem 
                        icon={<FiLogOut size="16" />} 
                        onClick={handleLogout} 
                        color="red.600" 
                        _hover={{ 
                          bg: 'red.50', 
                          color: 'red.700',
                          transform: 'translateX(2px)'
                        }} 
                        borderRadius="8px"
                        fontSize="sm"
                        fontWeight="500"
                        transition="all 0.2s ease"
                      >
                        تسجيل الخروج
                      </MenuItem>
                    </Box>
                  </MenuList>
                </Menu>
              </HStack>
            </Flex>
          </Box>


          {/* Page Content */}
          <Box p="8" className="stake-main-content" bg="var(--stake-bg-secondary, #1a2c38)" color="var(--color-grey-200)">
            {children}
          </Box>
        </Box>
      </Flex>

      {/* Mobile Drawer */}
      <Drawer isOpen={isMobileMenuOpen} onClose={onMobileMenuClose} placement="right">
        <DrawerOverlay />
        <DrawerContent maxW="280px" className="stake-sidebar" bg="linear-gradient(180deg, #0f212e 0%, #0a1820 100%)" borderLeft="1px solid #2f4553">
          <DrawerCloseButton color="#d5dceb" bg="#1a2c38" _hover={{ bg: '#2f4553', color: 'white' }} />
          <DrawerHeader borderBottomWidth="1px" bg="linear-gradient(180deg, #0f212e 0%, #0a1820 100%)" color="#d5dceb" borderColor="#2f4553">
            <Text color="#d5dceb">القائمة</Text>
          </DrawerHeader>
          <DrawerBody p="0" className="stake-sidebar" bg="linear-gradient(180deg, #0f212e 0%, #0a1820 100%)" color="#d5dceb">
            <SidebarContent isMobile />
          </DrawerBody>
        </DrawerContent>
      </Drawer>

      {/* Password Change Modal */}
      <Modal isOpen={isPasswordModalOpen} onClose={onPasswordModalClose} size="lg">
        <ModalOverlay bg="rgba(0, 0, 0, 0.6)" backdropFilter="blur(4px)" />
        <ModalContent 
          bg="linear-gradient(135deg, #ffffff 0%, #f8fafc 100%)" 
          borderRadius="20px" 
          boxShadow="0 25px 50px rgba(0, 0, 0, 0.25), 0 10px 30px rgba(0, 0, 0, 0.15)"
          border="1px solid"
          borderColor="rgba(255, 255, 255, 0.2)"
          mx="4"
        >
          <ModalHeader 
            bg="linear-gradient(135deg, #667eea 0%, #764ba2 100%)"
            color="white"
            borderRadius="20px 20px 0 0"
            py="6"
            px="8"
            position="relative"
            overflow="hidden"
          >
            <Box
              position="absolute"
              top="0"
              right="0"
              w="100px"
              h="100px"
              bg="rgba(255, 255, 255, 0.1)"
              borderRadius="50%"
              transform="translate(30px, -30px)"
            />
            <Box
              position="absolute"
              bottom="0"
              left="0"
              w="60px"
              h="60px"
              bg="rgba(255, 255, 255, 0.1)"
              borderRadius="50%"
              transform="translate(-20px, 20px)"
            />
            <HStack spacing="4" position="relative" zIndex="1">
              <Box
                p="3"
                bg="rgba(255, 255, 255, 0.2)"
                borderRadius="12px"
                backdropFilter="blur(10px)"
              >
                <Icon as={FiUser} size="24" />
              </Box>
              <VStack align="flex-start" spacing="1">
                <Text fontSize="xl" fontWeight="700">
                  تغيير كلمة المرور
                </Text>
                <Text fontSize="sm" opacity="0.9">
                  قم بتحديث كلمة المرور الخاصة بك
                </Text>
              </VStack>
            </HStack>
          </ModalHeader>
          
          <ModalBody py="8" px="8">
            <VStack spacing="6">
              <FormControl>
                <FormLabel 
                  fontSize="sm" 
                  fontWeight="600" 
                  color="#374151"
                  mb="3"
                  display="flex"
                  alignItems="center"
                  gap="2"
                >
                  <Box w="2" h="2" bg="#667eea" borderRadius="full" />
                  كلمة المرور الحالية
                </FormLabel>
                <Input
                  type="password"
                  value={passwordData.currentPassword}
                  onChange={(e) => setPasswordData({...passwordData, currentPassword: e.target.value})}
                  placeholder="أدخل كلمة المرور الحالية"
                  borderRadius="12px"
                  border="2px solid"
                  borderColor="#e5e7eb"
                  bg="white"
                  h="48px"
                  fontSize="sm"
                  _focus={{ 
                    borderColor: '#667eea', 
                    boxShadow: '0 0 0 3px rgba(102, 126, 234, 0.1)',
                    bg: 'white'
                  }}
                  _hover={{ borderColor: '#d1d5db' }}
                  transition="all 0.2s ease"
                />
              </FormControl>
              
              <FormControl>
                <FormLabel 
                  fontSize="sm" 
                  fontWeight="600" 
                  color="#374151"
                  mb="3"
                  display="flex"
                  alignItems="center"
                  gap="2"
                >
                  <Box w="2" h="2" bg="#10b981" borderRadius="full" />
                  كلمة المرور الجديدة
                </FormLabel>
                <Input
                  type="password"
                  value={passwordData.newPassword}
                  onChange={(e) => setPasswordData({...passwordData, newPassword: e.target.value})}
                  placeholder="أدخل كلمة المرور الجديدة"
                  borderRadius="12px"
                  border="2px solid"
                  borderColor="#e5e7eb"
                  bg="white"
                  h="48px"
                  fontSize="sm"
                  _focus={{ 
                    borderColor: '#10b981', 
                    boxShadow: '0 0 0 3px rgba(16, 185, 129, 0.1)',
                    bg: 'white'
                  }}
                  _hover={{ borderColor: '#d1d5db' }}
                  transition="all 0.2s ease"
                />
              </FormControl>
              
              <FormControl>
                <FormLabel 
                  fontSize="sm" 
                  fontWeight="600" 
                  color="#374151"
                  mb="3"
                  display="flex"
                  alignItems="center"
                  gap="2"
                >
                  <Box w="2" h="2" bg="#f59e0b" borderRadius="full" />
                  تأكيد كلمة المرور الجديدة
                </FormLabel>
                <Input
                  type="password"
                  value={passwordData.confirmPassword}
                  onChange={(e) => setPasswordData({...passwordData, confirmPassword: e.target.value})}
                  placeholder="أعد إدخال كلمة المرور الجديدة"
                  borderRadius="12px"
                  border="2px solid"
                  borderColor="#e5e7eb"
                  bg="white"
                  h="48px"
                  fontSize="sm"
                  _focus={{ 
                    borderColor: '#f59e0b', 
                    boxShadow: '0 0 0 3px rgba(245, 158, 11, 0.1)',
                    bg: 'white'
                  }}
                  _hover={{ borderColor: '#d1d5db' }}
                  transition="all 0.2s ease"
                />
              </FormControl>
            </VStack>
          </ModalBody>
          
          <ModalFooter 
            bg="linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%)"
            borderRadius="0 0 20px 20px"
            py="6"
            px="8"
            borderTop="1px solid"
            borderColor="rgba(0, 0, 0, 0.05)"
          >
            <HStack spacing="4" w="full" justify="flex-end">
              <Button
                variant="ghost"
                onClick={onPasswordModalClose}
                color="#6b7280"
                _hover={{ 
                  bg: 'rgba(107, 114, 128, 0.1)',
                  color: '#374151'
                }}
                borderRadius="12px"
                px="6"
                h="44px"
                fontSize="sm"
                fontWeight="500"
                transition="all 0.2s ease"
              >
                إلغاء
              </Button>
              <Button
                onClick={handlePasswordChange}
                bg="linear-gradient(135deg, #667eea 0%, #764ba2 100%)"
                color="white"
                _hover={{ 
                  bg: 'linear-gradient(135deg, #5a67d8 0%, #6b46c1 100%)',
                  transform: 'translateY(-1px)',
                  boxShadow: '0 10px 25px rgba(102, 126, 234, 0.3)'
                }}
                _active={{ transform: 'translateY(0)' }}
                borderRadius="12px"
                px="8"
                h="44px"
                fontSize="sm"
                fontWeight="600"
                transition="all 0.2s ease"
                boxShadow="0 4px 15px rgba(102, 126, 234, 0.2)"
              >
                تغيير كلمة المرور
              </Button>
            </HStack>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </Box>
  );
};

export default PremiumLayoutWrapper;