import React, { useState, useEffect } from 'react';
import { getApiUrl } from '../utils/apiUrlHelper';
import {
  Box,
  VStack,
  Text,
  Button,
  Input,
  InputGroup,
  InputRightElement,
  InputLeftElement,
  FormControl,
  FormLabel,
  IconButton,
  useToast,
  Alert,
  AlertIcon,
  AlertDescription,
  Icon,
} from '@chakra-ui/react';
import { FiUser, FiLock, FiEye, FiEyeOff } from 'react-icons/fi';

const Login = ({ onLogin }) => {
  const [formData, setFormData] = useState({ username: '', password: '' });
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [systemName, setSystemName] = useState('');
  const toast = useToast();

  useEffect(() => {
    document.body.style.margin = '0';
    document.body.style.padding = '0';
    document.body.style.overflow = 'hidden';
    document.documentElement.style.margin = '0';
    document.documentElement.style.padding = '0';
    document.documentElement.style.overflow = 'hidden';

    const loadSystemName = async () => {
      try {
        // جلب اسم النظام من متغيرات النظام
        const response = await fetch(getApiUrl('/api/system_variables_api.php?action=get_variables'));
        const result = await response.json();
        if (result.success && result.data) {
          // البحث عن system_name في المتغيرات
          const systemNameVar = result.data.find(v => v.key === 'system_name' || v.name === 'system_name');
          if (systemNameVar && systemNameVar.value) {
            setSystemName(systemNameVar.value);
          }
        }
      } catch (err) {
        console.error('Error loading system name:', err);
      }
    };
    loadSystemName();

    return () => {
      document.body.style.margin = '';
      document.body.style.padding = '';
      document.body.style.overflow = '';
      document.documentElement.style.margin = '';
      document.documentElement.style.padding = '';
      document.documentElement.style.overflow = '';
    };
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    if (error) setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const response = await fetch(getApiUrl('/api/login.php'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ username: formData.username, password: formData.password })
      });

      const result = await response.json();

      if (result.success) {
        toast({
          title: 'تم تسجيل الدخول بنجاح',
          description: `مرحباً ${result.user.full_name}`,
          status: 'success',
          duration: 3000,
          isClosable: true,
        });
        onLogin(result.user, result.token);
      } else {
        setError(result.message || 'اسم المستخدم أو كلمة المرور غير صحيحة');
      }
    } catch (err) {
      console.error('Login error:', err);
      setError('حدث خطأ في الاتصال. يرجى المحاولة مرة أخرى.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box
      position="fixed"
      top="0"
      left="0"
      right="0"
      bottom="0"
      w="100vw"
      h="100vh"
      overflow="hidden"
      m="0"
      p="0"
      display="flex"
      flexDirection="column"
      fontFamily="'Cairo', 'Tajawal', sans-serif"
    
    >
      {/* Main Content */}
      <Box
        flex="1"
        display="flex"
        alignItems="center"
        justifyContent="center"
      >
        <Box
          w="100%"
          maxW="800px"
          mx="4"
          bg="white"
          borderRadius="24px"
          boxShadow="0 25px 50px rgba(0, 0, 0, 0.15)"
          overflow="hidden"
          display="flex"
          minH="520px"
        >
          {/* Left - Image */}
          <Box
            w="50%"
            display={{ base: 'none', lg: 'flex' }}
        
            alignItems="center"
            justifyContent="center"
            p={0}
          >
            <Box
              as="img"
              src="/login-pic.png"
              alt="Login"
              w="100%"
              h="100%"
              objectFit="contain"
              objectPosition="center center"
            />
          </Box>

          {/* Right - Form */}
          <Box
            w={{ base: '100%', lg: '85%' }}
            display="flex"
            flexDirection="column"
            justifyContent="center"
            alignItems="center"
            p={0}
          >
            <VStack spacing={8} align="center" w="100%" maxW="360px" px={8}>
              {/* Title */}
              <VStack spacing={2} align="center" textAlign="center">
                <Text
                  fontSize="32px"
                  fontWeight="800"
                  color="#1e293b"
                  fontFamily="'Cairo', 'Tajawal', sans-serif"
                  lineHeight="1.2"
                >
                  تسجيل الدخول
                </Text>
                <Text
                  fontSize="15px"
                  color="#64748b"
                  fontWeight="500"
                  fontFamily="'Cairo', 'Tajawal', sans-serif"
                >
                  أدخل بياناتك للوصول إلى حسابك
                </Text>
              </VStack>

              {/* Form */}
              <form onSubmit={handleSubmit} style={{ width: '100%' }}>
                <VStack spacing={5} align="stretch">
                  {/* Username */}
                  <FormControl isRequired>
                    <FormLabel
                      fontSize="14px"
                      fontWeight="700"
                      color="#334155"
                      mb={2}
                      fontFamily="'Cairo', 'Tajawal', sans-serif"
                      textAlign="right"
                    >
                      اسم المستخدم
                    </FormLabel>
                    <InputGroup size="lg">
                      <InputRightElement h="54px" w="50px" pointerEvents="none">
                        <Icon as={FiUser} color="#6366f1" boxSize="22px" />
                      </InputRightElement>
                      <Input
                        name="username"
                        type="text"
                        placeholder="أدخل اسم المستخدم"
                        value={formData.username}
                        onChange={handleInputChange}
                        h="54px"
                        fontSize="15px"
                        fontWeight="500"
                        bg="#f8fafc"
                        border="2px solid #e2e8f0"
                        borderRadius="12px"
                        pr="55px"
                        pl="45px"
                        color="#1e293b"
                        fontFamily="'Cairo', 'Tajawal', sans-serif"
                        textAlign="right"
                        dir="rtl"
                        _hover={{
                          borderColor: '#94a3b8',
                          bg: '#f1f5f9',
                        }}
                        _focus={{
                          borderColor: '#6366f1',
                          bg: '#ffffff',
                          boxShadow: '0 0 0 4px rgba(99, 102, 241, 0.15)',
                        }}
                        _placeholder={{
                          color: '#94a3b8',
                          fontWeight: '400',
                        }}
                      />
                    </InputGroup>
                  </FormControl>

                  {/* Password */}
                  <FormControl isRequired>
                    <FormLabel
                      fontSize="14px"
                      fontWeight="700"
                      color="#334155"
                      mb={2}
                      fontFamily="'Cairo', 'Tajawal', sans-serif"
                      textAlign="right"
                    >
                      كلمة المرور
                    </FormLabel>
                    <InputGroup size="lg">
                      <InputRightElement h="54px" w="50px" pointerEvents="none">
                        <Icon as={FiLock} color="#6366f1" boxSize="22px" />
                      </InputRightElement>
                      <InputLeftElement h="54px" w="45px">
                        <IconButton
                          aria-label={showPassword ? 'إخفاء' : 'إظهار'}
                          icon={showPassword ? <FiEyeOff size={18} /> : <FiEye size={18} />}
                          variant="ghost"
                          size="sm"
                          color="#64748b"
                          borderRadius="8px"
                          _hover={{ bg: '#f1f5f9', color: '#6366f1' }}
                          onClick={() => setShowPassword(!showPassword)}
                        />
                      </InputLeftElement>
                      <Input
                        name="password"
                        type={showPassword ? 'text' : 'password'}
                        placeholder="أدخل كلمة المرور"
                        value={formData.password}
                        onChange={handleInputChange}
                        h="54px"
                        fontSize="15px"
                        fontWeight="500"
                        bg="#f8fafc"
                        border="2px solid #e2e8f0"
                        borderRadius="12px"
                        pr="55px"
                        pl="45px"
                        color="#1e293b"
                        fontFamily="'Cairo', 'Tajawal', sans-serif"
                        textAlign="right"
                        dir="rtl"
                        _hover={{
                          borderColor: '#94a3b8',
                          bg: '#f1f5f9',
                        }}
                        _focus={{
                          borderColor: '#6366f1',
                          bg: '#ffffff',
                          boxShadow: '0 0 0 4px rgba(99, 102, 241, 0.15)',
                        }}
                        _placeholder={{
                          color: '#94a3b8',
                          fontWeight: '400',
                        }}
                      />
                    </InputGroup>
                  </FormControl>

                  {/* Error */}
                  {error && (
                    <Alert
                      status="error"
                      borderRadius="10px"
                      fontSize="13px"
                      fontWeight="500"
                      bg="#fef2f2"
                      border="1px solid #fecaca"
                      py={2}
                      px={3}
                    >
                      <AlertIcon color="#ef4444" boxSize={4} />
                      <AlertDescription color="#991b1b" fontSize="13px">{error}</AlertDescription>
                    </Alert>
                  )}

                  {/* Button */}
                  <Button
                    type="submit"
                    w="full"
                    h="54px"
                    fontSize="16px"
                    fontWeight="700"
                    fontFamily="'Cairo', 'Tajawal', sans-serif"
                    borderRadius="12px"
                    color="white"
                    isLoading={loading}
                    loadingText="جاري تسجيل الدخول..."
                    bg="#6366f1"
                    boxShadow="0 8px 25px rgba(99, 102, 241, 0.35)"
                    _hover={{
                      bg: '#4f46e5',
                      transform: 'translateY(-2px)',
                      boxShadow: '0 12px 35px rgba(99, 102, 241, 0.45)',
                    }}
                    _active={{
                      transform: 'translateY(0)',
                      bg: '#4338ca',
                    }}
                    transition="all 0.3s ease"
                  >
                    تسجيل الدخول
                  </Button>
                </VStack>
              </form>
            </VStack>
          </Box>
        </Box>
      </Box>

      {/* Footer - يظهر فقط إذا كان هناك اسم للنظام */}
      {systemName && (
        <Box
          bg="rgba(255, 255, 255, 0.1)"
          backdropFilter="blur(10px)"
          py={3}
          px={6}
        >
          <Text
            fontSize="13px"
            color="white"
            textAlign="center"
            fontWeight="600"
            fontFamily="'Cairo', 'Tajawal', sans-serif"
          >
            {systemName}
          </Text>
        </Box>
      )}
    </Box>
  );
};

export default Login;
