import React, { useState, useEffect } from 'react';
import {
  Box,
  Heading,
  Text,
  HStack,
  VStack,
  SimpleGrid,
  Button,
  Icon,
  useToast,
  Card,
  CardBody,
  CardHeader,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  TableContainer,
  Badge,
  Progress,
  Alert,
  AlertIcon,
  AlertTitle,
  AlertDescription,
  Center,
  Divider,
  Flex,
  Spacer,
  IconButton,
  Tooltip,
  Spinner,
  CircularProgress,
  CircularProgressLabel,
} from '@chakra-ui/react';
import { 
  FiLink, 
  FiCheckCircle, 
  FiAlertCircle,
  FiRefreshCw,
  FiUsers,
  FiCalendar,
  FiDatabase,
  FiServer,
  FiActivity,
  FiClock,
  FiTrendingUp,
  FiShield,
  FiZap
} from 'react-icons/fi';

const FingerprintIntegrationTab = () => {
  const toast = useToast();
  const [loading, setLoading] = useState(false);
  const [integrationData, setIntegrationData] = useState(null);
  const [syncProgress, setSyncProgress] = useState(0);
  const [syncResult, setSyncResult] = useState(null);

  useEffect(() => {
    checkIntegration();
  }, []);

  const checkIntegration = async () => {
    try {
      setLoading(true);
      const response = await fetch(getApiUrl('/api/fingerprint_system_integration.php'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ action: 'check_integration' })
      });
      
      const data = await response.json();
      if (data.success) {
        setIntegrationData(data.results);
        toast({
          title: 'تم فحص التكامل',
          description: 'تم فحص حالة التكامل بنجاح',
          status: 'success',
          duration: 3000,
        });
      } else {
        toast({
          title: 'فشل في فحص التكامل',
          description: data.message,
          status: 'error',
          duration: 3000,
        });
      }
    } catch (error) {
      toast({
        title: 'خطأ في فحص التكامل',
        description: error.message,
        status: 'error',
        duration: 3000,
      });
    } finally {
      setLoading(false);
    }
  };

  const syncEmployees = async () => {
    try {
      setLoading(true);
      setSyncProgress(0);
      
      const progressInterval = setInterval(() => {
        setSyncProgress(prev => {
          if (prev >= 90) {
            clearInterval(progressInterval);
            return 90;
          }
          return prev + 20;
        });
      }, 300);

      const response = await fetch(getApiUrl('/api/fingerprint_system_integration.php'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ action: 'sync_employees' })
      });
      
      const data = await response.json();
      
      clearInterval(progressInterval);
      setSyncProgress(100);
      
      if (data.success) {
        setSyncResult(data);
        toast({
          title: 'تم مزامنة الموظفين',
          description: 'تم مزامنة الموظفين بنجاح',
          status: 'success',
          duration: 5000,
        });
        checkIntegration(); // Refresh data
      } else {
        toast({
          title: 'فشل في مزامنة الموظفين',
          description: data.message,
          status: 'error',
          duration: 5000,
        });
      }
    } catch (error) {
      toast({
        title: 'خطأ في مزامنة الموظفين',
        description: error.message,
        status: 'error',
        duration: 5000,
      });
    } finally {
      setLoading(false);
    }
  };

  const syncAttendance = async () => {
    try {
      setLoading(true);
      setSyncProgress(0);
      
      const progressInterval = setInterval(() => {
        setSyncProgress(prev => {
          if (prev >= 90) {
            clearInterval(progressInterval);
            return 90;
          }
          return prev + 20;
        });
      }, 300);

      const response = await fetch(getApiUrl('/api/fingerprint_system_integration.php'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ action: 'sync_attendance' })
      });
      
      const data = await response.json();
      
      clearInterval(progressInterval);
      setSyncProgress(100);
      
      if (data.success) {
        setSyncResult(data);
        toast({
          title: 'تم مزامنة الحضور',
          description: 'تم مزامنة الحضور بنجاح',
          status: 'success',
          duration: 5000,
        });
        checkIntegration(); // Refresh data
      } else {
        toast({
          title: 'فشل في مزامنة الحضور',
          description: data.message,
          status: 'error',
          duration: 5000,
        });
      }
    } catch (error) {
      toast({
        title: 'خطأ في مزامنة الحضور',
        description: error.message,
        status: 'error',
        duration: 5000,
      });
    } finally {
      setLoading(false);
    }
  };

  const fullSync = async () => {
    try {
      setLoading(true);
      setSyncProgress(0);
      
      const progressInterval = setInterval(() => {
        setSyncProgress(prev => {
          if (prev >= 90) {
            clearInterval(progressInterval);
            return 90;
          }
          return prev + 15;
        });
      }, 400);

      const response = await fetch(getApiUrl('/api/fingerprint_system_integration.php'), {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ action: 'full_sync' })
      });
      
      const data = await response.json();
      
      clearInterval(progressInterval);
      setSyncProgress(100);
      
      if (data.success) {
        setSyncResult(data);
        toast({
          title: 'تم المزامنة الكاملة',
          description: 'تم المزامنة الكاملة بنجاح',
          status: 'success',
          duration: 5000,
        });
        checkIntegration(); // Refresh data
      } else {
        toast({
          title: 'فشل في المزامنة الكاملة',
          description: data.message,
          status: 'error',
          duration: 5000,
        });
      }
    } catch (error) {
      toast({
        title: 'خطأ في المزامنة الكاملة',
        description: error.message,
        status: 'error',
        duration: 5000,
      });
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'connected': return 'green';
      case 'disconnected': return 'red';
      case 'warning': return 'orange';
      default: return 'gray';
    }
  };

  const getStatusText = (status) => {
    switch (status) {
      case 'connected': return 'متصل';
      case 'disconnected': return 'غير متصل';
      case 'warning': return 'تحذير';
      default: return 'غير معروف';
    }
  };

  return (
    <Box className="stake-card" overflow="hidden">
      <Box p="6">
        {/* Header Section */}
        <Box mb="8">
          <HStack spacing="8" align="flex-start">
            <VStack align="flex-start" spacing="2" flex="1" minW="300px">
              <Heading size="lg" className="stake-heading-3">
                تكامل نظام البصمة
              </Heading>
              <Text color="gray.600" fontSize="lg">
                إدارة التكامل بين نظام البصمة ونظام إدارة الموظفين
              </Text>
            </VStack>
            
            {/* Action Buttons */}
            <HStack spacing="3">
              <Button
                leftIcon={<FiRefreshCw />}
                className="stake-btn"
                size="md"
                borderRadius="xl"
                onClick={checkIntegration}
                isLoading={loading}
              >
                تحديث الحالة
              </Button>
            </HStack>
          </HStack>
        </Box>

        {/* Integration Status Overview */}
        <SimpleGrid columns={{ base: 1, md: 2, lg: 4 }} spacing="6" mb="8">
          <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
            <CardBody p="6">
              <VStack align="flex-start" spacing="3">
                <HStack spacing="3">
                  <Icon as={FiLink} boxSize="5" color={integrationData?.connection_status === 'connected' ? 'green.400' : 'red.400'} />
                  <Text className="stake-text-secondary" fontSize="sm" fontWeight="500">حالة الاتصال</Text>
                </HStack>
                <Text color="white" fontSize="xl" fontWeight="bold">
                  {integrationData ? getStatusText(integrationData.connection_status) : 'غير محدد'}
                </Text>
                <Badge 
                  colorScheme={getStatusColor(integrationData?.connection_status)} 
                  variant="subtle"
                  borderRadius="full"
                  px="3"
                  py="1"
                >
                  {integrationData?.connection_status === 'connected' ? 'نشط' : 'غير نشط'}
                </Badge>
              </VStack>
            </CardBody>
          </Card>

          <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
            <CardBody p="6">
              <VStack align="flex-start" spacing="3">
                <HStack spacing="3">
                  <Icon as={FiUsers} boxSize="5" color="blue.400" />
                  <Text className="stake-text-secondary" fontSize="sm" fontWeight="500">الموظفين المزامنين</Text>
                </HStack>
                <Text color="white" fontSize="2xl" fontWeight="bold">
                  {integrationData?.synced_employees || 0}
                </Text>
                <Text className="stake-text-secondary" fontSize="xs">من إجمالي {integrationData?.total_employees || 0}</Text>
              </VStack>
            </CardBody>
          </Card>

          <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
            <CardBody p="6">
              <VStack align="flex-start" spacing="3">
                <HStack spacing="3">
                  <Icon as={FiCalendar} boxSize="5" color="purple.400" />
                  <Text className="stake-text-secondary" fontSize="sm" fontWeight="500">سجلات الحضور</Text>
                </HStack>
                <Text color="white" fontSize="2xl" fontWeight="bold">
                  {integrationData?.attendance_records || 0}
                </Text>
                <Text className="stake-text-secondary" fontSize="xs">سجل اليوم</Text>
              </VStack>
            </CardBody>
          </Card>

          <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
            <CardBody p="6">
              <VStack align="flex-start" spacing="3">
                <HStack spacing="3">
                  <Icon as={FiClock} boxSize="5" color="orange.400" />
                  <Text className="stake-text-secondary" fontSize="sm" fontWeight="500">آخر مزامنة</Text>
                </HStack>
                <Text color="white" fontSize="lg" fontWeight="600" noOfLines={1}>
                  {integrationData?.last_sync || 'لم يتم'}
                </Text>
                <Text className="stake-text-secondary" fontSize="xs">منذ آخر تحديث</Text>
              </VStack>
            </CardBody>
          </Card>
        </SimpleGrid>

        {/* Sync Actions */}
        <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)" mb="8">
          <CardHeader>
            <HStack spacing="4">
              <Icon as={FiZap} boxSize="6" color="yellow.400" />
              <VStack align="flex-start" spacing="1">
                <Heading size="md" color="white">عمليات المزامنة</Heading>
                <Text className="stake-text-secondary" fontSize="sm">
                  مزامنة البيانات بين نظام البصمة ونظام إدارة الموظفين
                </Text>
              </VStack>
            </HStack>
          </CardHeader>
          <CardBody>
            <VStack spacing="6">
              <SimpleGrid columns={{ base: 1, md: 3 }} spacing="4" w="full">
                <Button
                  leftIcon={<FiUsers />}
                  className="stake-btn-success"
                  size="lg"
                  borderRadius="xl"
                  onClick={syncEmployees}
                  isLoading={loading}
                  loadingText="جاري المزامنة..."
                  h="60px"
                >
                  مزامنة الموظفين
                </Button>
                
                <Button
                  leftIcon={<FiCalendar />}
                  className="stake-btn"
                  size="lg"
                  borderRadius="xl"
                  onClick={syncAttendance}
                  isLoading={loading}
                  loadingText="جاري المزامنة..."
                  h="60px"
                >
                  مزامنة الحضور
                </Button>
                
                <Button
                  leftIcon={<FiDatabase />}
                  className="stake-btn-secondary"
                  size="lg"
                  borderRadius="xl"
                  onClick={fullSync}
                  isLoading={loading}
                  loadingText="جاري المزامنة..."
                  h="60px"
                >
                  مزامنة كاملة
                </Button>
              </SimpleGrid>

              {loading && (
                <Box w="full" p="6" bg="var(--stake-bg-secondary, #182935)" borderRadius="xl" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
                  <VStack spacing="4">
                    <HStack spacing="3">
                      <Spinner size="md" color="blue.400" />
                      <Text color="white" fontSize="lg" fontWeight="600">جاري المزامنة...</Text>
                    </HStack>
                    <Progress 
                      value={syncProgress} 
                      size="lg" 
                      colorScheme="blue" 
                      borderRadius="full"
                      w="full"
                    />
                    <Text className="stake-text-secondary" fontSize="sm">{syncProgress}% مكتمل</Text>
                  </VStack>
                </Box>
              )}

              {syncResult && (
                <Alert status="success" borderRadius="xl" bg="green.50" border="1px solid" borderColor="green.200">
                  <AlertIcon color="green.500" />
                  <Box>
                    <AlertTitle color="green.800">تمت المزامنة بنجاح!</AlertTitle>
                    <AlertDescription color="green.700">
                      {syncResult.details && (
                        <VStack align="flex-start" spacing="1" mt="2">
                          {Object.entries(syncResult.details).map(([key, value]) => (
                            <Text key={key} fontSize="sm">
                              <Text as="span" fontWeight="600">{key}:</Text> {value}
                            </Text>
                          ))}
                        </VStack>
                      )}
                    </AlertDescription>
                  </Box>
                </Alert>
              )}
            </VStack>
          </CardBody>
        </Card>

        {/* Integration Details */}
        {integrationData && (
          <SimpleGrid columns={{ base: 1, lg: 2 }} spacing="6">
            <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
              <CardHeader>
                <HStack spacing="3">
                  <Icon as={FiServer} boxSize="5" color="blue.400" />
                  <Heading size="md" color="white">معلومات الاتصال</Heading>
                </HStack>
              </CardHeader>
              <CardBody>
                <VStack spacing="4" align="stretch">
                  <HStack justify="space-between">
                    <Text className="stake-text-secondary" fontSize="sm">الخادم:</Text>
                    <Text color="white" fontSize="sm" fontWeight="500">
                      {integrationData.server_info?.host || 'غير محدد'}
                    </Text>
                  </HStack>
                  <Divider borderColor="var(--stake-border-primary, #3e5665)" />
                  <HStack justify="space-between">
                    <Text className="stake-text-secondary" fontSize="sm">المنفذ:</Text>
                    <Text color="white" fontSize="sm" fontWeight="500">
                      {integrationData.server_info?.port || 'غير محدد'}
                    </Text>
                  </HStack>
                  <Divider borderColor="var(--stake-border-primary, #3e5665)" />
                  <HStack justify="space-between">
                    <Text className="stake-text-secondary" fontSize="sm">آخر تحديث:</Text>
                    <Text color="white" fontSize="sm" fontWeight="500">
                      {integrationData.last_sync || 'غير محدد'}
                    </Text>
                  </HStack>
                </VStack>
              </CardBody>
            </Card>

            <Card bg="var(--stake-bg-primary, #0f212e)" borderRadius="xl" boxShadow="0 10px 40px rgba(0, 0, 0, 0.3)" border="1px solid" borderColor="var(--stake-border-primary, #3e5665)">
              <CardHeader>
                <HStack spacing="3">
                  <Icon as={FiTrendingUp} boxSize="5" color="green.400" />
                  <Heading size="md" color="white">إحصائيات المزامنة</Heading>
                </HStack>
              </CardHeader>
              <CardBody>
                <VStack spacing="4" align="stretch">
                  <HStack justify="space-between">
                    <Text className="stake-text-secondary" fontSize="sm">إجمالي الموظفين:</Text>
                    <Text color="white" fontSize="sm" fontWeight="500">
                      {integrationData.total_employees || 0}
                    </Text>
                  </HStack>
                  <Divider borderColor="var(--stake-border-primary, #3e5665)" />
                  <HStack justify="space-between">
                    <Text className="stake-text-secondary" fontSize="sm">الموظفين الجدد:</Text>
                    <Text color="green.400" fontSize="sm" fontWeight="500">
                      {integrationData.new_employees || 0}
                    </Text>
                  </HStack>
                  <Divider borderColor="var(--stake-border-primary, #3e5665)" />
                  <HStack justify="space-between">
                    <Text className="stake-text-secondary" fontSize="sm">سجلات الحضور الجديدة:</Text>
                    <Text color="blue.400" fontSize="sm" fontWeight="500">
                      {integrationData.new_attendance || 0}
                    </Text>
                  </HStack>
                </VStack>
              </CardBody>
            </Card>
          </SimpleGrid>
        )}

        {/* Loading State */}
        {loading && !integrationData && (
          <Center py="20">
            <VStack spacing="6">
              <Spinner size="xl" color="blue.400" thickness="4px" />
              <VStack spacing="2">
                <Text color="white" fontSize="lg" fontWeight="600">جاري فحص حالة التكامل...</Text>
                <Text className="stake-text-secondary" fontSize="sm">يرجى الانتظار</Text>
              </VStack>
            </VStack>
          </Center>
        )}

        {/* No Data State */}
        {!loading && !integrationData && (
          <Center py="20">
            <VStack spacing="6">
              <Icon as={FiAlertCircle} boxSize="16" className="stake-text-secondary" />
              <VStack spacing="2">
                <Text color="white" fontSize="lg" fontWeight="600">لا توجد بيانات</Text>
                <Text className="stake-text-secondary" fontSize="sm">لم يتم العثور على بيانات التكامل</Text>
              </VStack>
              <Button
                leftIcon={<FiRefreshCw />}
                className="stake-btn"
                onClick={checkIntegration}
                borderRadius="xl"
              >
                إعادة المحاولة
              </Button>
            </VStack>
          </Center>
        )}
      </Box>
    </Box>
  );
};

export default FingerprintIntegrationTab;