// دالة لتصحيح المصطلحات العربية
const getArabicPlural = (count, singular, plural) => {
  if (count === 1) {
    return `${count} ${singular}`;
  } else if (count === 2) {
    return `${count} ${singular}`;
  } else if (count >= 3 && count <= 10) {
    return `${count} ${plural}`;
  } else {
    return `${count} ${singular}`;
  }
};

